window.HB_TR["1-chronicles"]["ur"]=["1. آدم، شیٹھ، اینوش،\n2. کینان، محلالیل، جیرد،\n3. ہینوخ، میتوشالح، لمیک،\n4۔ نوح، سام، حام، اور یافتھ۔\n5۔ یافتھ کے بیٹے؛ گومر، اور ماگوگ، اور مادائی، اور جاوان، اور ٹوبال، اور میشچ، اور تیراس۔\n6۔ اور گومر کے بیٹے؛ اشچناز، ریفاتھ، اور توگارمہ۔ {ریفیتھ: یا، دیفاتھ جیسا کہ کچھ نسخوں میں ہے}\n7۔ اور جاوان کے بیٹے؛ الیشاہ، اور ترشش، کٹم، اور ڈوڈنیم۔ {دودانیم: یا، رودانیم، کچھ نقول کے مطابق}\n8۔ ہام کے بیٹے؛ کش، اور مزرائیم، پٹ، اور کنعان۔\n9۔ اور کش کے بیٹے؛ سبا، حویلہ، سبتا، راماہ اور سبتیچا۔ اور راماہ کے بیٹے؛ شیبا، اور ڈیڈن۔\n10۔ اور کش نے نمرود کو جنم دیا: وہ زمین پر طاقتور ہونے لگا۔\n11۔ اور مزرائیم نے لودیم، انامیم، لہابیم اور نفتوہیم کو جنم دیا،\n12۔ اور پتھرسیم، اور کاسلوہیم (جن میں سے فلسطینی تھے)، اور کفثوریم۔\n13۔ اور کنعان نے زیدون کو اپنے سب سے بڑے بیٹے اور ہیث کو جنم دیا،\n14۔ یبوسی بھی، اور اموری اور گرگاشی،\n15۔ اور حویت، اور آرکیت، اور سینائیٹ،\n16۔ اور آروادی، اور زیماری، اور ہماثی۔\n17۔ سام کے بیٹے؛ ایلام، اور آشور، اور ارفکسد، اور لود، اور آرام، اور عز، اور ہل، اور گیتھر، اور مشیخ۔ {میشک: یا، ماش}\n18۔ اور ارفخسعد نے شیلا کو جنم دیا، اور شیلہ نے ایبر کو جنم دیا۔\n19۔ اور ایبر سے دو بیٹے پیدا ہوئے: ایک کا نام {تھا} پیلیگ تھا؛ کیونکہ اس کے زمانے میں زمین تقسیم تھی: اور اس کے بھائی کا نام {تھا} جوکتان۔ {پیلیگ: یعنی، تقسیم}\n20. اور یوقتان نے الموداد، شلیف، ہزارماوت، اور یراح کو جنم دیا،\n21۔ ہدورام بھی، اور اوزال، اور دکلاہ،\n22۔ اور ایبال، اور ابیمائیل، اور سبا،\n23۔ اور اوفیر، اور حویلہ، اور جوباب۔ یہ سب جوکتان کے بیٹے تھے۔\n24۔ شیم، ارفقساد، شلہ،\n25. ایبر، پیلیگ، ریو،\n26. سرگ، ناحور، تیرا،\n27۔ ایبرام؛ وہی ابراہیم ہے۔\n28۔ ابراہیم کے بیٹے؛ آئزک، اور اسماعیل۔\n29۔ یہ {ہیں} ان کی نسلیں: اسماعیل، نیبایوتھ کا سب سے بڑا بیٹا؛ پھر کیدار، اور ادبیل، اور میبسام،\n30. مشمہ، اور دومہ، ماسا، حداد، اور تیما، {حداد: جسے حدر بھی کہا جاتا ہے}\n31۔ جیتور، نافش، اور کیدیمہ۔ یہ اسماعیل کے بیٹے ہیں۔\n32۔ اب کتورہ کے بیٹے، ابراہیم کی کنیزہ: اس نے زمران، جوکشان، میدان، مدیان، عشبک اور شواہ کو جنم دیا۔ اور جوکشان کے بیٹے؛ شیبا، اور ڈیڈن۔\n33۔ اور مدیان کے بیٹے؛ ایفاہ، اور ایفر، اور حنوخ، اور عبیدہ، اور ایلداہ۔ یہ سب کیتوراہ کے بیٹے ہیں۔\n34۔ اور ابراہیم نے اسحاق کو جنم دیا۔ آئزک کے بیٹے؛ عیسو اور اسرائیل۔\n35۔ عیسو کے بیٹے؛ الیفاز، رئوئل، اور یسوع، اور جلم، اور قورح۔\n36۔ الیفاز کے بیٹے؛ تیمان، عمر، زیفی، اور گتام، کناز، اور تیمنا، اور امالک۔ {زیفی: یا، زیفو}\n37۔ رئیل کے بیٹے؛ نہات، زراہ، شمہ، اور مزہ۔\n38۔ اور سائر کے بیٹے؛ لوتان، اور شوبل، اور زیباں، اور عناہ، اور دیشون، اور ایزر، اور دیشان۔\n39۔ اور لوتان کے بیٹے؛ ہوری، اور ہومام: اور تیمنا لوٹن کی بہن تھی۔ {ہومام: یا، ہیمام}\n40۔ شوبال کے بیٹے؛ الیان، اور ماناہات، اور ایبل، شیفی، اور اونام۔ اور زیبعون کے بیٹے؛ آیاہ، اور عناہ۔ {الیان: جسے الوان بھی کہا جاتا ہے} {شیفی: جسے شیفو بھی کہا جاتا ہے}\n41۔ عنا کے بیٹے؛ ڈشن۔ اور ڈشون کے بیٹے؛ امرام، اور اشبان، اور ایتھران، اور چیران۔ {امرام: یا، ہمدان}\n42۔ ایزر کے بیٹے؛ بلہان اور زاوان، {اور} جاکان۔ دیشان کے بیٹے؛ اوز، اور آران۔ {جاکان: یا، اکان}\n43. اب یہ وہ بادشاہ ہیں جو زمین ادوم میں حکمرانی کرتے تھے اس سے پہلے کہ کوئی بادشاہ بنی اسرائیل پر حکومت کرتا تھا؛ بیئور کا بیٹا بیلا: اور اس کے شہر کا نام {تھا} دینہابا۔\n44۔ اور جب بیلا فوت ہوا، تو جوباب، زرا کی بزرہ کی بیٹا، اس کی جگہ حکومت کرنے لگا۔\n45۔ اور جب جوباب فوت ہوا، تو تیمانائٹس کی سرزمین کے ہوشام نے اس کی جگہ حکومت کی۔\n46۔ اور جب حشام مر گیا، حداد بیٹا، جو مآب کے میدان میں مدیان کو مارا گیا تھا، اس کی جگہ حکمرانی کرنے لگا: اور اس کے شہر کا نام آویت تھا۔\n47۔ اور جب حداد فوت ہو گئے، تو مسرکہ کے ساملاح نے ان کی جگہ حکومت کی۔\n48۔ اور جب سملہ مر گیا، تو دریا کے کنارے رہوبوتھ کا شاؤل اس کی جگہ حکمرانی کرنے لگا۔\n49۔ اور جب شاؤل فوت ہوا، تو اخبور کا بیٹا بعلحنان اس کی جگہ حکومت کرنے لگا۔\n50۔ اور جب بعلحنان مر گیا، حداد نے اس کی جگہ حکومت کی: اور اس کے شہر کا نام {پائی} تھا؛ اور ان کی بیوی کا نام {تھا} مہتابل تھا، جو میترد کی بیٹی تھیں، جو مزاہاب کی بیٹی تھیں۔ {حداد: یا، حدار} {پائی: یا، پاؤ}\n51۔ حداد بھی وفات پا گئے۔ اور ایڈوم کے ڈیوک تھے؛ ڈیوک تیمنا، ڈیوک عالیہ، ڈیوک جیتھیتھ،\n52۔ ڈیوک اہولیبامہ، ڈیوک ایلاہ، ڈیوک پینون،\n53۔ ڈیوک کیناز، ڈیوک تیمان، ڈیوک میبزار،\n54۔ ڈیوک مگدیئل، ڈیوک ایرام۔ یہ ادم کے ڈیوک ہیں۔","1. یہ {ہیں} اسرائیل کے بیٹے؛ روبن، شمعون، لیوی اور یہوداہ، یساکر، اور زبولون، {اسرائیل: یا، یعقوب}\n2۔ ڈین، جوزف، اور بنیامن، نفتالی، گاد، اور آشر۔\n3۔ یہوداہ کے بیٹے؛ ار، اور اونان، اور شیلاہ: {جو} تین اس کے ہاں پیدا ہوئے، جو شوا کنعانی کی بیٹی سے تھی۔ اور ار، یہوداہ کا پہلا بیٹا، خداوند کی نظر میں برا تھا؛ اور اس نے اسے مار ڈالا۔\n4۔ اور اس کی بہو تامار نے اسے فراز اور زرا دیا۔ یہوداہ کے تمام بیٹے پانچ سال کے تھے۔\n5۔ فاریز کے بیٹے؛ ہیزرون، اور ہمول۔\n6۔ اور زراح کے بیٹے؛ زمری، اور ایتھن، اور ہیمن، اور کالکول، اور دارا: کل پانچ تھے۔ {زمری: یا، زبدی} {دارا: یا، داردا}\n7۔ اور کارمی کے بیٹے؛ آچار، اسرائیل کا شرارت کرنے والا، جس نے چیز میں گناہ کیا۔ {آچار: یا، اچان}\n8۔ اور ایتھن کے بیٹے؛ آزاریا۔\n9۔ وہ بیٹے بھی جو ہیزرون کے تھے، جو اس کے ہاں پیدا ہوئے؛ جیراہمیل، رام، اور چیلوبائی۔ {رام: گری۔ آرام} {چیلوبائی: یا، کیلب}\n10۔ اور رام نے امیناداب کو جنم دیا؛ اور امیناداب نے یہوداہ کے بچوں کا شہزادہ ناہشون کو جنم دیا؛\n11۔ اور ناہشون نے سلمیٰ کو جنم دیا، اور سلمیٰ نے بوعز کو جنم دیا، {سلمی: جسے سلمون بھی کہا جاتا ہے}\n12۔ اور بوعز نے عوبید کو جنم دیا، اور اوبید نے یسوع کو جنم دیا،\n13۔ اور یسوع نے اپنا پہلا بیٹا ایلیاب کو جنم دیا، ابیناداب دوسرا، اور شمع نے تیسرا پیدا کیا، {شمہ: یا شما}\n14۔ نیتھانیئل چوتھاں، ردائی پانچوں،\n15۔ اوزیم چھٹا، داؤد ساتواں:\n16۔ جن کی بہنیں زرویاہ اور ابیگیل تھیں۔ اور زرویاہ کے بیٹے؛ ابیشائی، اور یوآب، اور عساہل، تین۔\n17۔ اور ابیگیل نے اماسا کو جنم دیا: اور اماسا کے والد یثر اسماعیلی تھے۔ {یتھر...: جسے ایتھرا این اسرائیلی بھی کہا جاتا ہے}\n18۔ اور کیلب حزرون کا بیٹا ازوبہ کی بیوی اور یریوت کے بیٹے پیدا ہوئے: اس کے بیٹے یہ ہیں؛ جیشر، اور شوباب، اور آرڈون۔\n19۔ اور جب ازوبہ مر گیا، کیلیب نے افرات کو اپنے پاس لے لیا، جس سے اسے ہور پیدا ہوا۔\n20۔ اور ہور نے یوری کو جنم دیا، اور یوری نے بزالیل کو جنم دیا۔\n21۔ اور بعد میں حزرون ماخر کی بیٹی کے پاس گیا، جو گلعاد کے والد تھی، جس سے اس نے اس وقت شادی کی جب وہ تیس سال کا تھا؛ اور اس نے اسے سیگوب دیا۔ {شادی شدہ: ہیب۔ لے لیا}\n22۔ اور سگوب نے یائر کو جنم دیا، جس کے پاس گلعاد کی سرزمین میں تین بیس شہر تھے۔\n23۔ اور اس نے گشور اور آرام، یائر کے قصبوں کے ساتھ، کناث اور اس کے قصبوں سے، {حتیٰ کہ} تین سو شہر بھی لے لیے۔ یہ سب ماکھیر کے بیٹوں کے تھے، جو گلعاد کے والد تھے۔\n24۔ اور اس کے بعد حزرون کالبفراتا میں فوت ہو گیا، پھر ابیا حزرون کی بیوی نے اسے آشور کو جنم دیا، جو تیقوع کا باپ تھا۔\n25۔ اور یرحمیل، حزرون کا پہلا بیٹا، رام پہلا اولاد، بونا، اورن، اوزم، {اور} احییاہ تھے۔\n26۔ یرحمیل کی ایک اور بیوی بھی تھی، جس کا نام عطارہ تھا؛ وہ اونام کی ماں تھی۔\n27۔ اور رام کے بیٹے، یرحمیل کے سب سے بڑے بیٹے، معاز، یامین اور ایکر تھے۔\n28۔ اور اونام کے بیٹے شمائی اور جادا تھے۔ اور شمائی کے بیٹے؛ ناداب، اور ابیشور۔\n29۔ اور ابیشور کی بیوی کا نام ابیحیل تھا، اور اس نے اسے اہبان اور مولد دیا۔\n30۔ اور نداب کے بیٹے؛ سلید، اور اپائم: لیکن سلیڈ بغیر اولاد کے مر گیا۔\n31۔ اور اپائیم کے بیٹے؛ ایشی۔ اور ایشی کے بیٹے؛ شیشان۔ اور شیشان کے بچے؛ اہلائی۔\n32۔ اور شمائی کے بھائی جادا کے بیٹے؛ جیتھر، اور جوناتھن: اور جیتھر بغیر بچوں کے مر گیا۔\n33۔ اور جوناتھن کے بیٹے؛ پیلیتھ، اور زازا۔ یہ یرحمیل کے بیٹے تھے۔\n34۔ اب شیشان کے کوئی بیٹے نہیں تھے، صرف بیٹیاں تھیں۔ اور شیشان کا ایک خادم تھا، ایک مصری، جس کا نام جارہ تھا۔\n35۔ اور شیشان نے اپنی بیٹی اپنی خادمہ یرہ کو دے دی، جو اس کی بیوی تھی؛ اور اس نے اسے اتائی پیدا کیا۔\n36۔ اور اتائی نے ناتھن کو جنم دیا، اور ناتھن نے زباد کو جنم دیا،\n37۔ اور زاباد نے افلال کو جنم دیا، اور ایفلال نے اوبید کو جنم دیا،\n38۔ اور اوبید نے یہو کو جنم دیا، اور یہو نے عزریاہ کو جنم دیا،\n39۔ اور عزریاہ نے ہیلیز کو جنم دیا، اور ہیلیز نے الیاسہ کو جنم دیا،\n40۔ اور الیاسہ نے سیسمائی کو جنم دیا، اور سیسمائی نے شلم کو جنم دیا،\n41۔ اور شالوم نے یقمیاہ کو جنم دیا، اور یقمیاہ نے الیشاما کو جنم دیا۔\n42. اب کیلب، یرحمیل کے بھائی کے بیٹے، میشا اس کا پہلا بیٹا تھا، جو زیف کا باپ تھا؛ اور ہیبرون کے والد مریشہ کے بیٹے۔\n43۔ اور حبرون کے بیٹے؛ کورح، اور تپواہ، اور ریکیم، اور شیما۔\n44۔ اور شیما نے راحم کو جنم دیا، جو یورکوم کا باپ تھا: اور رکم نے شمائی کو جنم دیا۔\n45۔ اور شمائی کا بیٹا ماون تھا: اور ماؤن بیت زور کا باپ تھا۔\n46۔ اور ایفاہ، کیلب کی محبوبہ، ننگے ہاران، موزا، اور گزیز: اور ہاران نے گزیز کو جنم دیا۔\n47۔ اور جہدائی کے بیٹے؛ ریگم، اور جوتھم، اور گشان، اور پیلت، اور ایفاہ، اور شاف۔\n48۔ ماخاہ، کیلب کی محبوبہ، ننگی شیبر اور ترحانہ۔\n49۔ اس نے شاف کو جنم دیا جو مدمناہ کا باپ، شیوا مکحبہ کا باپ، اور گبعہ کا باپ؛ اور کالیب {تھا} اخسا کی بیٹی بھی۔\n50۔ یہ کالیب کے بیٹے تھے، جو ہور کا بیٹا تھا، جو افراتا کا پہلا بیٹا تھا؛ شوبل، کرجاتھجاریم کا والد، {ایفراتا: جسے ایفریث بھی کہا جاتا ہے}\n51۔ سلمیٰ بیت لحم کا والد، حارف بیت گیدر کا والد۔\n52۔ اور شوبل، کرجاتھجاریم کے والد، کے بیٹے تھے؛ ہاروئے، {اور} ماناہیتھیٹس کا آدھا۔ {ہاروہ: یا، ریایہ} {آدھا...: یا، مینوچیٹس کا آدھا، یا، ہاتسیہامینوچوتھ}\n53۔ اور کرجاتھجاریم کے خاندان؛ ایتھرائٹس، پوہائیٹس، شوماٹائٹس، اور مشرائیٹس؛ ان میں زراتائٹس اور ایشٹالائٹس شامل تھے۔\n54۔ سلمیٰ کے بیٹے؛ بیت لحم، نیتوفاتھیز، آتاروت، یوآب کا گھر، اور آدھا مناہیتھیٹس، زورائیٹس۔ {آتاروت...: یا، اٹارائٹس، یا، یوآب خاندان کے تاج}\n55۔ اور ان کاتبوں کے خاندان جو جابیز میں رہتے تھے؛ تیراتھیز، شیمتی، {اور} سچاتائی۔ یہ وہ کینائٹس ہیں جو ہیماتھ سے آئے تھے، جو ریخاب خاندان کا باپ تھا۔","1۔ یہ داؤد کے بیٹے تھے، جو اسے ہیبرون میں پیدا ہوئے؛ پہلا بیٹا امنون، جو اہنوعام دی یزریلائٹس کا تھا؛ دوسرا دانیال، ابیگیل دی کارمیلیٹس کا: {دانیال: یا، چلیاب}\n2۔ تیسرا، ابشالوم، ماخاہ کا بیٹا، جو گشور کے بادشاہ تلمائی کی بیٹی تھا؛ چوتھا، ادونیاہ بیٹا ہگیث:\n3۔ پانچویں، شیفطیہ ابیتال کی؛ چھٹاں، ایتریم ایگلہ کی بیوی سے۔\n4. {یہ} چھ ان کے ہاں ہیبرون میں پیدا ہوئے؛ اور وہاں اس نے سات سال اور چھ ماہ حکومت کی: اور یروشلم میں تیس سال حکومت کی۔\n5۔ اور یہ اس کے ہاں یروشلم میں پیدا ہوئے؛ شمیعہ، اور شوباب، اور ناتھن، اور سلیمان، چار سال، جو بثشوا کی بیٹی امیئیل کی بیٹی تھی: {شمیعہ: یا، شموع} {بتشوع: یا، بتشبع} {امیئل: یا، ایلیام}\n6۔ ایبار بھی، اور الیشما، اور ایلیفلیٹ، {الیشما: جسے الیشوع بھی کہا جاتا ہے}\n7۔ اور نوگا، اور نیفگ، اور یافیہ،\n8۔ اور الیشما، اور ایلیادا، اور الیفلیٹ، نو۔ {ایلیادا: یا، بیلیادا}\n9۔ {یہ} داؤد کے تمام بیٹے تھے، کنیزوں کے بیٹوں کے علاوہ، اور ان کی بہن تمار۔\n10۔ اور سلیمان کا بیٹا {تھا} رحبعام، ابیا اس کا بیٹا، آسا اس کا بیٹا، یہوشافات اس کا بیٹا، {ابیا: یا، ابیجام}\n11. یورام اس کا بیٹا، احزیاہ اس کا بیٹا، یوآش اس کا بیٹا، {آہزیہ: یا، عزریا}\n12۔ امازیا اس کا بیٹا، عزریاہ اس کا بیٹا، یوتام اس کا بیٹا، {عزریا: یا، عزیا}\n13۔ آحاز اس کا بیٹا، حزقیاہ اس کا بیٹا، منسی اس کا بیٹا،\n14۔ آمون اس کا بیٹا، جوسیاہ اس کا بیٹا۔\n15۔ اور یوشیا کے بیٹے {تھے}، پہلا یوحنان، دوسرا یہویاکیم، تیسرا صدقیہ، چوتھا شلوم۔ {یوحنان: یا، یہوآہز} {یہویاکیم: یا، ایلیاکیم} {زیدکیاہ: یا، متانیا}\n16۔ اور یہویاقیم کے بیٹے: یقونیاہ اس کا بیٹا، زدیقیاہ اس کا بیٹا۔ {جیکونیا: جسے یہوئچن یا کونیاہ بھی کہا جاتا ہے}\n17۔ اور یکونیاہ کے بیٹے؛ آسیر، سلثیئل اس کا بیٹا، {سلاثیئل: عبرانی۔ شیالٹیئل}\n18۔ مالکیرام بھی، اور پیدعیہ، اور شینزار، یکیمیا، ہوشما، اور ندبیاہ۔\n19۔ اور پیدعیاہ کے بیٹے {تھے}، زروبابل اور شمعی؛ اور زروبابل کے بیٹے؛ مشولام، حنانیا، اور ان کی بہن شلومیت:\n20۔ اور ہشوبا، اور اوہیل، اور بریخیہ، اور حسادیہ، جوشابھسد، پانچ۔\n21۔ اور حنانیاہ کے بیٹے؛ پیلاطیہ اور یسعیا: رفیعیاہ کے بیٹے، ارنان کے بیٹے، عبدیا کے بیٹے، شخنیا کے بیٹے۔\n22۔ اور شحنیا کے بیٹے؛ شمعیہ: اور شمعیاہ کے بیٹے؛ ہتوش، اور ایگیل، اور باریہ، اور نیریاہ، اور شافات، چھ۔\n23۔ اور نیاریاہ کے بیٹے؛ ایلیوئنائی، اور حزقیاہ، اور عزریکام، تین۔ {حزقیاہ: عبرانی۔ ہسکیجہ}\n24۔ اور ایلیونائی کے بیٹے تھے، ہودیہ، اور الیاشب، اور پیلیا، اور اکوب، اور یوحنان، اور دالیہ، اور عنانی، سات سال۔","1۔ یہوداہ کے بیٹے؛ فیریز، ہیزرون، اور کارمی، اور ہور، اور شوبل۔ {کارمی: جسے چیلوبائی یا کیلب بھی کہا جاتا ہے}\n2۔ اور ریعیہ، شوبال کا بیٹا، جہات کو جنم دیا؛ اور جہات نے اہومائی اور لہاد کو جنم دیا۔ یہ {ہیں} زوراتھیوں کے خاندان ہیں۔ {ریایہ: یا، ہارویہ}\n3۔ اور یہ {تھے} ایتام کے والد سے؛ یزریل، اور ایشما، اور ادباش: اور ان کی بہن کا نام {تھا} ہیزل لپونی:\n4۔ اور پنوئل گدور کا والد، اور عزر ہوشاہ کا والد۔ یہ حور کے بیٹے ہیں، جو ایفراتا کا پہلا بیٹا ہے، بیت لحم کا والد۔\n5۔ اور آشور، ٹیکوا کے والد، کی دو بیویاں تھیں، ہیلہ اور نارہ۔\n6۔ اور ناراہ نے اسے آہوزم، ہیفر، تیمنی، اور ہاہاشتاری جنم دیا۔ یہ {تھے} ناراہ کے بیٹے۔\n7۔ اور ہیلہ کے بیٹے، زیریت، یزور، اور ایتنان۔\n8۔ اور کوز نے انوب، زوبیبہ اور حارم کے بیٹے آہارہیل کے خاندان کو جنم دیا۔\n9۔ اور جابیز اپنے بھائیوں سے زیادہ معزز تھا: اور اس کی ماں نے اس کا نام یابتز پکارا، کہتی تھی، کیونکہ میں اسے غم میں مبتلا کرتی ہوں۔ {جابیز: یعنی، غمگین}\n10۔ اور جابز نے اسرائیل کے خدا کو پکارا، کہا، اے کاش تو مجھے برکت دینا، میرا ساحل وسیع کرنا، اور تمہارا ہاتھ میرے ساتھ ہو، اور تم مجھے برائی سے بچانا چاہتے ہو، تاکہ مجھے غم نہ ہو! اور خدا نے اسے وہ دیا جو اس نے مانگا۔ {اوہ...: عبرانی۔ اگر تم چاہو، وغیرہ} {برقرار رکھو...: عبرانی۔ میرے لیے کرو}\n11۔ اور شلب، شوح کا بھائی، نے مہیر کو جنم دیا، جو ایشتون کا باپ تھا۔\n12۔ اور ایشتون نے بثرافا، پاسیع، اور تہنہ، جو ارنہاش کا باپ تھا، پیدا کیا۔ یہ {ہیں} ریخا کے لوگ۔ {ایرنہاش: یا، ناہاش شہر}\n13۔ اور کیناز کے بیٹے؛ اوثنیئل، اور سرایہ: اور اوثنیئل کے بیٹے؛ ہاتھاتھ۔ {ہاتھاتھ...: یا، ہاتھاتھ، اور میونوتھائی، جنہوں نے پیدا کیا، وغیرہ}\n14۔ اور میونوتائی نے اوفرا کو جنم دیا: اور سریاہ نے یوآب کو جنم دیا، جو وادی چراشیم کا باپ تھا؛ کیونکہ وہ کاریگر تھے۔ {وادی: یا، وادی کے باشندے} {چراشم: یعنی، کاریگر} {ہاتھاتھ...: یا، ہاتھاتھ، اور میونوتھائی، جنہوں نے پیدا کیا، وغیرہ}\n15۔ اور کیلب کے بیٹے، یپھنہ کے بیٹے؛ ایرو، ایلاہ، اور نام: اور ایلاہ کے بیٹے، حتیٰ کہ کناز۔ {حتیٰ کہ کیناز: یا، اکناز}\n16۔ اور جہللیل کے بیٹے؛ زپھ، زفاہ، تیریا، اور اسارئیل۔\n17۔ اور عزرا کے بیٹے {تھے}، یتھر، اور مرید، اور ایفر، اور جالون: اور اس نے مریم، شامائی، اور اشباہ کو جنم دیا، جو اشتیموآ کا باپ تھا۔\n18۔ اور اس کی بیوی یہودیجہ نے یرید جو گدور کا باپ تھا، ہیبر جو سوخو کا باپ تھا، اور یکوتھیل زانوح کا باپ تھا۔ اور یہ بتھیاہ کے بیٹے ہیں، جو فرعون کی بیٹی ہے، جسے میرڈ نے لے لیا۔ {یہودیجہ: یا، یہودی}\n19۔ اور اس کی بیوی ہودیاہ کے بیٹے، جو ناحم کی بہن تھی، کیلہ گارمیٹی کا والد، اور اشتیموع مااخاتی کی۔ {ہودیاہ: یا، یہودیجہ، پہلے ذکر ہوا}\n20۔ اور شمعون کے بیٹے {تھے}، امنون، اور رینہ، بن ہانان، اور تیلون۔ اور ایشی کے بیٹے تھے، زوہیت اور بینزوہیتھ۔\n21۔ یہوداہ کے بیٹے شیلہ کے بیٹے، جو لکہ کا باپ تھے، اور لعادہ مریشاہ کے والد تھے، اور ان خاندانوں کے خاندان جو عمدہ کپڑے بناتے تھے، اشبعیہ کے گھرانے سے،\n22۔ اور یوکیم، اور چوزیبا کے لوگ، اور یوآش، اور سراف، جن کا موآب اور یشوبیلحم میں حکمرانی تھی۔ اور یہ سب قدیم چیزیں ہیں۔\n23۔ یہ وہ کمہار تھے، اور وہ جو پودوں اور جھاڑیوں کے درمیان رہتے تھے: وہاں وہ بادشاہ کے کام کے لیے رہتے تھے۔\n24. شمعون کے بیٹے {تھے}، نیموئل اور یمین، جریب، زرح، {اور} شاؤل: {نیمویل: یا، یموئیل} {جریب، زرح: یا، یاچن زوہار}\n25۔ شلم اس کا بیٹا، میبسم کا بیٹا، مشمہ اس کا بیٹا۔\n26۔ اور مشمہ کے بیٹے؛ حموئیل اس کا بیٹا، زخور اس کا بیٹا، شیمئی اس کا بیٹا۔\n27۔ اور شیمئی کے سولہ بیٹے اور چھ بیٹیاں تھیں؛ لیکن اس کے بھائیوں کے زیادہ بچے نہیں تھے، اور ان کے تمام خاندان بھی یہوداہ کے بچوں کی طرح بڑھے۔ {جیسے...: عبرانی۔ تو}\n28۔ اور وہ بیرشبع، مولادہ، اور حزرشوال میں بسے۔\n29۔ اور بلہا پر، اور ایزیم پر، اور تولاڈ پر، {بلحا: یا، بالہ} {تولاد: یا، ایلٹولاد}\n30۔ اور بیتھوئیل، اور ہورمہ پر، اور زیکلاگ پر،\n31۔ اور بیت مارکبوت، ہزارسوسم، بیت بیری میں، اور شعاریم میں۔ یہ ان کے شہر تھے جو داؤد کے دور حکومت تک تھے۔ {Hazarsusim: یا، Hazarsusah}\n32۔ اور ان کے گاؤں {تھے}، ایٹم، اور عین، رمون، اور توچن، اور اشان، پانچ شہر: {ایٹم: یا، ایتھر}\n33۔ اور ان کے تمام گاؤں جو تقریبا ایک ہی شہروں کے گرد تھے، بعل تک۔ یہ ان کی رہائش گاہیں اور ان کی نسل نامہ تھے۔ {بعل: یا، بالعتھ بیر} {ان کا نسب نامہ: یا، جیسا کہ انہوں نے قوموں میں تقسیم کیا}\n34۔ اور مشباب، اور جملک اور یشوع جو امازیہ کا بیٹا ہے،\n35۔ اور یوئیل، اور یہو، یوسیبیاہ کا بیٹا، سریاہ کا بیٹا، جو عسیئل کا بیٹا تھا،\n36۔ اور ایلیوئنائی، اور یعقوبہ، اور یشوحیاہ، اور عسعیا، اور عدئیل، اور یسیمیئل، اور بنایا،\n37۔ اور زیزا، شیفی کا بیٹا، الون کا بیٹا، جدایاہ کا بیٹا، شمری کا بیٹا، شمعیہ کا بیٹا؛\n38۔ جن کے نام {ان} کے نام سے ذکر کیے گئے تھے، وہ اپنے خاندانوں میں شہزادے تھے: اور ان کے آباؤ اجداد کے خاندان میں بہت اضافہ ہوا۔ {ذکر شدہ: عبوری۔ آ رہا ہوں}\n39۔ اور وہ گدور کے داخلی راستے تک گئے، جو وادی کے مشرقی کنارے پر تھا، تاکہ اپنے ریوڑ کے لیے چراگاہ تلاش کریں۔\n40۔ اور انہوں نے موٹی چراگاہ اور اچھا علاقہ پایا، اور زمین چوڑی، پرسکون اور پرامن تھی؛ کیونکہ ہام کے لوگ قدیم زمانے سے وہاں رہتے تھے۔\n41۔ اور یہ نام سے لکھے گئے تھے جو یہوداہ کے بادشاہ حزقیاہ کے زمانے میں آئے تھے، انہوں نے ان کے خیمے اور وہاں پائے جانے والے بستیوں کو تباہ کر دیا، اور آج تک انہیں مکمل طور پر تباہ کر دیا، اور ان کے کمروں میں رہتے ہیں: کیونکہ وہاں ان کے ریوڑ کے لیے چراگاہ تھی۔\n42۔ اور ان میں سے کچھ، حتیٰ کہ شمعون کے بیٹوں میں سے پانچ سو آدمی، سعیر کے کوہ پر گئے، جن کے کپتان پلاتیا، نیاریا، رفیعیاہ اور عزئیل تھے، جو عشی کے بیٹے تھے۔\n43۔ اور انہوں نے باقی امالیکیوں کو مار ڈالا جو بچ نکلے تھے اور آج تک وہاں مقیم ہیں۔","1۔ اب روبن کے بیٹے، جو اسرائیل کا پہلا بیٹا تھا، (کیونکہ وہ پہلا تھا؛ لیکن چونکہ اس نے اپنے باپ کے بستر کو ناپاک کیا، اس کا پیدائشی حق یوسف بیٹے اسرائیل کے بیٹوں کو دیا گیا: اور نسب نامہ پیدائشی حق کے بعد شمار نہیں کیا جاتا۔\n2۔ کیونکہ یہوداہ اپنے بھائیوں پر غالب آیا، اور اس سے سب سے بڑا حکمران آیا؛ لیکن پیدائشی حق {تھا} جوزف کا:) {سردار...: یا، شہزادہ}\n3۔ روبن کے بیٹے، {میں کہتا ہوں}، اسرائیل کے پہلے بیٹے {تھے}، حنوخ، اور پالو، حزرون، اور کارمی۔\n4۔ جوئل کے بیٹے؛ شمعیہ اس کا بیٹا، جوج اس کا بیٹا، شمعی اس کا بیٹا،\n5۔ میکاہ اس کا بیٹا، ریعیہ اس کا بیٹا، بعل اس کا بیٹا،\n6۔ بیرہ، اس کا بیٹا، جسے آشور کے بادشاہ ٹلگاتپلنیسر نے {قیدی} لے جایا: وہ روبینیوں کا {شہزادہ} تھا۔ {ٹلگیتھ پلنیسر: جسے ٹگلیتھ پائلزر بھی کہا جاتا ہے}\n7۔ اور ان کے خاندانوں کے بھائی، جب ان کی نسلوں کی نسل شمار ہوئی، سردار جیئیل اور زکریا تھے،\n8۔ اور بیلا، عزاز کا بیٹا، شمعہ کا بیٹا، جو یوئیل کا بیٹا تھا، جو عاروئر میں رہتا تھا، حتیٰ کہ نیبو اور بعلمیون تک: {شمع: یا، شمعیہ}\n9۔ اور مشرق کی طرف وہ فرات کے دریا سے ویرانے کے داخلے تک آباد ہوا: کیونکہ ان کے مویشی گلعاد کی زمین میں کثرت سے پھیلے ہوئے تھے۔\n10۔ اور ساؤل کے زمانے میں انہوں نے ہگاریوں سے جنگ کی، جو ان کے ہاتھوں مارے گئے، اور وہ اپنے خیموں میں پورے مشرقی گلیعاد کے علاقے میں بسے۔ {پورے وقت...: عبرانی۔ مشرق کے تمام چہرے پر}\n11۔ اور گاد کے بچے ان کے خلاف باشان کی سرزمین میں سلخاہ تک بسے:\n12۔ یوئیل سردار، اور شافام اگلا، اور جانائی، اور شافات باشان میں۔\n13۔ اور ان کے باپ و اجداد کے گھرانے کے بھائی {تھے}، مائیکل، مشولم، اور سبا، اور جورائی، اور یچان، اور ضیاء، اور حبر، سات۔\n14. یہ ابیحیل، حوری کا بیٹا، جاروح کا بیٹا، گلعاد کا بیٹا، مائیکل کا بیٹا، یشیشائی کا بیٹا، جہدو کا بیٹا، بوز کا بیٹا ہے؛\n15۔ احی عبدیل کا بیٹا، گونی کا بیٹا، ان کے آباؤ اجداد کے خاندان کا سردار۔\n16۔ اور وہ باشان کے گلعاد میں، اس کے شہروں میں، اور شارون کے تمام مضافات میں، ان کی سرحدوں پر، بسے۔ {ان کے...: عبرانی۔ ان کے آگے بڑھنے کے طریقے}\n17۔ یہ سب یوتام بادشاہ یہوداہ کے زمانے اور یربعام بادشاہ اسرائیل کے زمانے میں شجرہ نسب کے مطابق شمار کیے گئے۔\n18۔ روبن کے بیٹے، گادیوں کے بیٹے، اور مناسی قبیلے کا آدھا حصہ، بہادر آدمیوں سے، جو بکلر اور تلوار اٹھا سکتے تھے، تیر اندازی کر سکتے تھے، اور جنگ میں ماہر تھے، چار ہزار سات سو تین سو تھے، جو جنگ میں نکلے۔ {بہادر...: عبرانی۔ بہادری کے بیٹے}\n19۔ اور انہوں نے ہگاریوں سے، جیتور، نیفش، اور نوداب سے جنگ کی۔\n20۔ اور انہیں ان کے خلاف مدد ملی، اور ہگاریوں کو ان کے ہاتھ میں دے دیا گیا، اور جو کچھ بھی ان کے ساتھ تھا، کیونکہ انہوں نے جنگ میں خدا سے دعا کی، اور خدا ان سے بے زار تھا؛ کیونکہ انہوں نے اس پر بھروسہ کیا۔\n21۔ اور انہوں نے اپنے مویشی لے لیے؛ ان کے اونٹوں میں پچاس ہزار، بھیڑوں میں سے دو سو پچاس ہزار، اور گدھوں میں سے دو ہزار، اور انسانوں میں ایک سو ہزار۔ {لیا...: عبرانی۔ لیڈ کیپٹیو} {مرد: عبرانی۔ انسانوں کی روحیں}\n22۔ کیونکہ بہت سے مارے گئے، کیونکہ جنگ خدا کی تھی۔ اور وہ قید تک ان کی جگہ رہے۔\n23۔ اور منسی کے آدھے قبیلے کے بچے اس سرزمین میں بستے تھے: وہ باشان سے بعلحرمون اور سینیر تک پہنچے، اور پھر ہیرمون کے پہاڑ تک پہنچے۔\n24۔ اور یہ اپنے آباؤ اجداد کے گھر کے سربراہ تھے، حتیٰ کہ ایفر، عیشی، ایلیل، عزریل، یرمیا، ہوداویہ، اور جہدیئل، بہادر لوگ، مشہور لوگ، اور اپنے باپ دادا کے خاندان کے سربراہ۔ {مشہور...: عبرانی۔ نام رکھنے والے مرد}\n25۔ اور انہوں نے اپنے باپ اجداد کے خدا کے خلاف زیادتی کی، اور زمین کے لوگوں کے دیوتاؤں کے پیچھے طوائف ہو گئے، جنہیں خدا نے ان سے پہلے تباہ کر دیا تھا۔\n26۔ اور اسرائیل کے خدا نے آشور کے بادشاہ پل کی روح اور آشور کے بادشاہ تیلگتھپلنیسر کی روح کو جگایا، اور انہیں لے گیا، حتیٰ کہ روبینی، گادیت، اور مناسی کے آدھے قبیلے کو بھی، اور انہیں ہالاہ، حبور، ہارا اور آج تک دریائے گوزان لے آیا۔","1۔ لیوی کے بیٹے؛ گرشون، کوہاتھ، اور میراری۔ {گرشون: یا، گرشوم}\n2۔ اور کوہات کے بیٹے؛ امرام، اظہار، اور حبرون، اور عزیل۔\n3۔ اور امرام کے بچے؛ ہارون، اور موسیٰ، اور مریم۔ ہارون کے بیٹے بھی؛ ناداب، اور ابیہو، الیعازر، اور ایثمار۔\n4۔ الیعازر نے فینیحاس کو جنم دیا، فینیحاس نے ابیشع کو جنم دیا،\n5۔ اور ابیشوع نے بکی کو جنم دیا، اور بکی نے عوزی کو جنم دیا،\n6۔ اور اوزی نے زرحیاہ کو جنم دیا، اور زرحیاہ نے میرایوت کو جنم دیا،\n7۔ میریوتھ نے امریہ کو جنم دیا، اور امریاہ نے اہتوب کو جنم دیا،\n8۔ اور آہیتوب نے زادوک کو جنم دیا، اور زادوک نے اہیماز کو جنم دیا،\n9۔ اور احمعاز نے عزریاہ کو جنم دیا، اور عزریاہ نے یوحنان کو جنم دیا،\n10۔ اور یوحنان نے عزریاہ کو جنم دیا، (وہی ہے جس نے یروشلم میں سلیمان کے بنائے ہوئے مندر میں کاہن کا عہدہ انجام دیا:) {مندر میں: عبرانی۔ گھر میں}\n11۔ اور عزریاہ نے امریہ کو جنم دیا، اور امریاہ نے احیتوب کو جنم دیا،\n12۔ اور اہتوب نے زادوک کو جنم دیا، اور زادوک نے شلم کو جنم دیا، {شلم: یا، مشولم}\n13۔ اور شلم نے حلقیہ کو جنم دیا، اور حلقیاہ نے عزریا کو جنم دیا،\n14۔ اور عزریاہ نے سرایا کو جنم دیا، اور سریاہ نے یہوزادق کو جنم دیا،\n15۔ اور یہوزادق {قید میں} چلا گیا، جب خداوند نے یہوداہ اور یروشلم کو نبوکدنصر کے ہاتھوں لے گیا۔\n16۔ لیوی کے بیٹے؛ گرشوم، کوہاتھ، اور میراری۔ {گرشوم: یا، گرشون}\n17۔ اور یہ {ہیں} گرشوم کے بیٹوں کے نام؛ لبنی اور شیمئی۔\n18۔ اور کوہات کے بیٹے، عمرام، اور اظہار، اور حبرون، اور عزئیل۔\n19۔ مراری کے بیٹے؛ مہلی، اور مشی۔ اور یہ لاویوں کے خاندان ہیں جو ان کے آباؤ اجداد کے مطابق ہیں۔\n20۔ گرشوم کا؛ لبنی اس کا بیٹا، جہاد اس کا بیٹا، زمہ اس کا بیٹا،\n21۔ جوح اس کا بیٹا، ایدو اس کا بیٹا، زیرہ اس کا بیٹا، جیترائی اس کا بیٹا۔ {جواہ: یا، ایتھن} {ایدو: یا، آدایہ} {جیترائی: جسے ایتھنی بھی کہا جاتا ہے}\n22۔ کوہات کے بیٹے؛ امیناداب اس کا بیٹا، کورہ اس کا بیٹا، عسیر اس کا بیٹا، {امینادب: یا، اظہار}\n23۔ ایلکانہ اس کا بیٹا، اور ابیاسف اس کا بیٹا، اور عسیر اس کا بیٹا،\n24۔ تحات اس کا بیٹا، یوریئل اس کا بیٹا، عزیاہ اس کا بیٹا، اور شاؤل اس کا بیٹا۔\n25۔ اور الکانہ کے بیٹے؛ اماسائی، اور اہیموتھ۔\n26۔ {جہاں تک} الکاناہ: الکانہ کے بیٹے؛ زوفائی اس کا بیٹا، اور نہات اس کا بیٹا، {زوفائی: یا، زوف}\n27۔ ایلیاب اس کا بیٹا، جیروہام اس کا بیٹا، ایلکانہ اس کا بیٹا۔\n28۔ اور سموئیل کے بیٹے؛ پہلی اولاد واشنی، اور ابیاہ۔ {واشنی: جسے جوئل بھی کہا جاتا ہے}\n29۔ مراری کے بیٹے؛ محلی، لبنی اس کا بیٹا، شمعی اس کا بیٹا، عزا اس کا بیٹا،\n30۔ شمیعہ اس کا بیٹا، حاجیہ اس کا بیٹا، عسیاہ اس کا بیٹا۔\n31. اور یہ وہ لوگ ہیں جنہیں داؤد نے خداوند کے گھر میں گانے کی خدمت کے لیے رکھا تھا، جب صندوق آرام کر گیا۔\n32۔ اور وہ جماعت کے خیمہ کے گھر کے سامنے گانے کے ساتھ خدمت کرتے رہے، یہاں تک کہ سلیمان نے یروشلم میں خداوند کا گھر تعمیر کر دیا: اور {پھر} وہ اپنے حکم کے مطابق اپنے عہدے پر انتظار کرتے رہے۔\n33۔ اور یہ وہ لوگ ہیں جو اپنے بچوں کے ساتھ انتظار کرتے تھے۔ کوہاتیوں کے بیٹوں میں: ہیمان ایک گلوکار، یوئیل کا بیٹا، شیموئیل کا بیٹا، {انتظار کیا: عبرانی۔ کھڑا ہوا}\n34۔ ایلکانہ کا بیٹا، یروحام کا بیٹا، ایلیل کا بیٹا، توح کا بیٹا،\n35۔ زوف کا بیٹا، الکانہ کا بیٹا، مہات کا بیٹا، اماسائی کا بیٹا،\n36. الکانہ کا بیٹا، یوئیل کا بیٹا، عزریاہ کا بیٹا، زفانیاہ کا بیٹا،\n37۔ تحات کا بیٹا، آسیر کا بیٹا، ایبیاساف کا بیٹا، جو قورح کا بیٹا تھا،\n38۔ اظہار کا بیٹا، کوحات کا بیٹا، لاوی کا بیٹا، جو اسرائیل کا بیٹا تھا۔\n39۔ اور اس کا بھائی عصاف، جو اس کے دائیں ہاتھ پر کھڑا تھا، {حتی} اصف، برخیاہ کا بیٹا، شمیعہ کا بیٹا،\n40۔ مائیکل کا بیٹا، بعسیاہ کا بیٹا، مالکیا کا بیٹا،\n41۔ ایتھنی کا بیٹا، زراہ کا بیٹا، عدیاہ کا بیٹا،\n42. ایتھن کا بیٹا، زیمہ کا بیٹا، شمعی کا بیٹا،\n43۔ جہات کا بیٹا، گرشوم کا بیٹا، لاوی کا بیٹا۔\n44۔ اور ان کے بھائی، میراری کے بیٹے {بائیں ہاتھ پر کھڑے تھے}: ایتھن، کیشی کا بیٹا، عبدی کا بیٹا، ملوچ کا بیٹا، {کیشی: یا، کوشیع}\n45۔ حشبہیا کا بیٹا، اماصیہ کا بیٹا، ہلکیا کا بیٹا،\n46۔ امزی کا بیٹا، بانی کا بیٹا، شمر کا بیٹا،\n47۔ محلی کا بیٹا، موشی کا بیٹا، میراری کا بیٹا، لاوی کا بیٹا۔\n48۔ ان کے بھائی، لاوی، بھی خدا کے گھر کے خیمے کی ہر قسم کی خدمت کے لیے مقرر کیے گئے۔\n49۔ لیکن ہارون اور اس کے بیٹوں نے سلائی کی قربان گاہ اور لوبان کی قربان گاہ پر پیش کی، {اور انہیں مقدس ترین جگہ کے تمام کاموں کے لیے مقرر کیا گیا}، اور اسرائیل کے لیے کفارہ دینے کے لیے، جیسا کہ موسیٰ خدا کے بندے نے حکم دیا تھا۔\n50۔ اور یہ ہارون کے بیٹے ہیں؛ الیعازر اس کا بیٹا، فینیحاس اس کا بیٹا، ابیشوع اس کا بیٹا،\n51۔ بوکی اس کا بیٹا، عوزی اس کا بیٹا، زرحیاہ اس کا بیٹا،\n52۔ میریوت اس کا بیٹا، امریاہ اس کا بیٹا، اہیتب اس کا بیٹا،\n53۔ زادوک اس کا بیٹا، احیماز اس کا بیٹا۔\n54۔ اب یہ ان کے قلعوں میں اپنے ساحلوں پر رہنے کی جگہیں ہیں، ہارون کے بیٹوں اور کوہاتی خاندانوں کے: کیونکہ ان کا سب کچھ تھا۔\n55۔ اور انہوں نے انہیں یہوداہ کی سرزمین اور اس کے آس پاس کے مضافات میں ہیبرون دیا۔\n56۔ لیکن شہر کے کھیت اور اس کے دیہات انہوں نے کیلب کے بیٹے یپھونہ کو دے دیے۔\n57۔ اور ہارون کے بیٹوں کو انہوں نے یہوداہ کے شہر دیے، یعنی ہبرون، پناہ کا شہر، اور لبنہ کو اس کے مضافات کے ساتھ، اور جتیر اور اشتیموآ کو ان کے مضافات کے ساتھ،\n58۔ اور ہیلن اپنے مضافات کے ساتھ، دیبیر اپنے مضافات کے ساتھ، {ہیلن: یا، ہولون}\n59۔ اور آشان اپنے مضافات کے ساتھ، اور بیت شمش اپنے مضافات کے ساتھ: {آشان: یا، عین}\n60۔ اور بنیامین کے قبیلے سے؛ گیبا اپنے مضافات کے ساتھ، علیمیتھ اپنے مضافات کے ساتھ، اور اناتھوتھ اپنے مضافات کے ساتھ۔ ان کے خاندانوں کے تمام شہر تیرہ شہر تھے۔ {الیمیتھ: یا، المون}\n61۔ اور کوہات کے بیٹوں کو، {جو} اس قبیلے کے خاندان سے باقی تھے، {شہر دیے گئے} آدھے قبیلے سے، {یعنی، مناسی کے آدھے {قبیلے} سے، قرعہ اندازی کے ذریعے، دس شہروں میں۔\n62۔ اور گرشوم کے بیٹوں کو، جو اپنے خاندانوں میں اساکر کے قبیلے سے، آشر کے قبیلے سے، نفتالی قبیلے سے، اور منشیہ قبیلے سے باشان میں، تیرہ شہروں سے تعلق رکھتے ہیں۔\n63۔ مراری کے بیٹوں کو قرعہ اندازی کے ذریعے دیے گئے، ان کے خاندانوں میں، قبیلہ روبن سے، قبیلہ گاد سے، اور قبیلہ زبولون سے، بارہ شہر دیے گئے۔\n64۔ اور بنی اسرائیل نے لاویوں کو یہ شہر اور ان کے مضافات دیے۔\n65۔ اور انہوں نے یہوداہ کے بچوں کے قبیلے سے، شمعون کے بچوں کے قبیلے سے، اور بنیامین کے بچوں کے قبیلے سے یہ شہر قرعہ اندازی کیے، جنہیں {ان} کے ناموں سے پکارا جاتا ہے۔\n66۔ اور کوہات کے بیٹوں کے خاندانوں کی باقیات کے شہر افریم قبیلے سے تھے۔\n67۔ اور انہوں نے انہیں پناہ کے شہر دیے، شیخم جو پہاڑ افریم میں تھا اور اس کے مضافات بھی؛ {انہوں نے دیا} اور گیزر کو اس کے مضافات کے ساتھ،\n68۔ اور یوکمیم اپنے مضافات کے ساتھ، اور بیت حورون اپنے مضافات کے ساتھ،\n69۔ اور ایجالون اپنے مضافات کے ساتھ، اور گاتھرمون اپنے مضافات کے ساتھ:\n70۔ اور منسی کے آدھے قبیلے سے؛ انیر اپنے مضافات کے ساتھ، اور بلیئم اپنے مضافات کے ساتھ، کوہاتھ کے بیٹوں کے باقیات کے خاندان کے لیے۔\n71۔ گرشوم کے بیٹوں کو، جو مناسی کے نصف قبیلے کے خاندان سے دیے گئے، باشان کے گولان اور اس کے مضافات کے ساتھ، اور اشتاروت کو اس کے مضافات کے ساتھ:\n72۔ اور اساکار کے قبیلے سے؛ کیدیش اپنے مضافات کے ساتھ، دابیراتھ اپنے مضافات کے ساتھ،\n73۔ اور راموتھ اپنے مضافات کے ساتھ، اور انیم اپنے مضافات کے ساتھ:\n74۔ اور آشر کے قبیلے سے؛ مشعل اپنے مضافات کے ساتھ، اور عبدون اپنے مضافات کے ساتھ،\n75۔ اور حکوک اپنے مضافات کے ساتھ، اور ریحوب اپنے مضافات کے ساتھ:\n76۔ اور نفتالی قبیلے سے؛ کیدیش گلیل میں اس کے مضافات کے ساتھ، ہیمون اپنے مضافات کے ساتھ، اور کرجاتھائم اپنے مضافات کے ساتھ۔\n77۔ زبولون قبیلے سے مراری کے باقی بچوں کو دیا گیا، ریمون کو اس کے مضافات کے ساتھ، اور تابور اپنے مضافات سے:\n78۔ اور دوسری طرف اردن یریحو کے پاس، اردن کے مشرقی کنارے پر، انہیں قبیلہ روبن سے دیے گئے، بزر صحرا میں اس کے مضافات کے ساتھ، اور جہزہ اپنے مضافات کے ساتھ،\n79۔ کیڈیموتھ بھی اپنے مضافات کے ساتھ، اور میفاتھ اپنے مضافات کے ساتھ:\n80۔ اور قبیلہ گاد سے؛ راموتھ گلعاد میں اپنے مضافات کے ساتھ، اور مہانائم اپنے مضافات کے ساتھ،\n81۔ اور ہیشبون اپنے مضافات کے ساتھ، اور جازر اپنے مضافات کے ساتھ۔","1۔ اب یساکر کے بیٹے تھے، تولا، اور پواہ، یاشب، اور شمرون، چار سال کے تھے۔\n2۔ اور تولا کے بیٹے؛ عزی، اور رفیعیہ، اور یریئل، اور جہمائی، اور جبسام، اور شموئیل، اپنے والد کے گھرانے کے سربراہ، {یعنی}، تولا کے: {وہ} اپنی نسلوں میں بہادر اور طاقتور لوگ تھے؛ جس کی تعداد داؤد کے زمانے میں دو بیس ہزار چھ سو تھی۔\n3۔ اور عوزی کے بیٹے؛ ازرایہ: اور ازراحیاہ کے بیٹے؛ مائیکل، اور اوبادیہ، اور جوئل، اشیہ، پانچ: سب سردار تھے۔\n4۔ اور ان کے ساتھ، ان کی نسلوں کے ذریعے، ان کے باپ و اجداد کے گھرانے کے بعد، جنگ کے لیے سپاہیوں کے گروہ تھے، چھ اور تیس ہزار مرد: کیونکہ ان کے بہت سے بیویاں اور بیٹے تھے۔\n5۔ اور ان کے بھائی اساکر کے تمام خاندانوں میں بہادر اور طاقتور تھے، جنہیں ان کی نسل نامہ کے مطابق مجموعی طور پر چالیس سات ہزار شمار کیا جاتا تھا۔\n6۔ {بنیامین کے بیٹے}؛ بیلا، بیچر، اور جیدیئل، تین۔\n7۔ اور بیلا کے بیٹے؛ ایزبون، اور اوزی، اور عزیل، اور جیریموتھ، اور ایری، پانچ؛ ان کے باپوں کے خاندان کے سربراہ، بہادر آدمی؛ اور ان کی نسب نامہ کے مطابق بیس، بارہ ہزار، تیس اور چو۔\n8۔ اور بیچر کے بیٹے؛ زیمیرا، اور یواش، اور ایلیعزر، اور ایلیوئنائی، اور عمری، اور یریموتھ، اور ابیاہ، اور انتھوت، اور عالمیت۔ یہ سب بیچر کے بیٹے ہیں۔\n9۔ اور ان کی تعداد، ان کی نسل در نسل کے حساب سے، اپنے آباؤ اجداد کے خاندان کے سربراہ، بہادر مرد، بیس ہزار دو سو تھی۔\n10۔ جدیدیل کے بیٹے بھی؛ بلہان: اور بلہان کے بیٹے؛ یسوع، اور بنیمن، اور ایہود، اور چناناہ، اور زیتھن، اور تاثرش، اور اہیشاہر۔\n11۔ یہ سب جیدیائیل کے بیٹے، اپنے باپ و اجداد کے سروں کے ذریعے، بہادر آدمی، سترہ ہزار دو سو فوجی تھے، جنگ اور جنگ کے لیے تیار تھے۔\n12۔ شوپیم بھی، اور ہوپیم، ایر کے بیٹے، {اور} ہوشیم، آہر کے بیٹے۔ {آئر: یا، ایری} {آہر: یا، اہیرم}\n13۔ نفتالی کے بیٹے؛ جہزیئل، اور گونی، اور یزر، اور شلم، بلحا کے بیٹے۔\n14۔ منسی کے بیٹے؛ اشریئل، جسے اس نے جنم دیا: ({لیکن} اس کی محبوبہ آرامیتس نے گلیڈ کے والد ماکیر کو جنم دیا:\n15۔ اور ماکیر نے ہپیم اور شوپیم کی بہن سے شادی کی، جس کی بہن کا نام ماخا تھا؛) اور دوسرے {تھا} کا نام زیلوفہاد تھا: اور زیلوفہاد کی بیٹیاں تھیں۔\n16۔ اور ماخر کی بیوی ماخا نے بیٹا پیدا کیا، اور اس کا نام پیریش رکھا؛ اور ان کے بھائی کا نام {تھا} شیرش؛ اور ان کے بیٹے اولام اور راکیم تھے۔\n17۔ اور اولام کے بیٹے؛ بیدان۔ یہ {تھے} گلعاد کے بیٹے، جو ماخر کا بیٹا تھا، مناسی کا بیٹا۔\n18۔ اور اس کی بہن ہمولکیث نے ایشود، ابیزر اور مہالہ کو جنم دیا۔\n19۔ اور شمیدا کے بیٹے تھے، آحیان، شکیم، لیخی، اور انیام۔\n20۔ اور افرائیم کے بیٹے؛ شثلہ، اور بیرد اس کا بیٹا، اور تحث کا بیٹا، اور ایلادہ اس کا بیٹا، اور طحاث اس کا بیٹا،\n21۔ اور زاباد اس کا بیٹا، اور شثلہ اس کا بیٹا، اور ایزر اور ایلعد، جنہیں گات کے لوگ {جو اس زمین میں پیدا ہوئے تھے} نے مار ڈالا، کیونکہ وہ اپنے مویشی لے جانے آئے تھے۔\n22۔ اور افرائیم ان کے والد نے کئی دن سوگ منایا، اور اس کے بھائی اسے تسلی دینے آئے۔\n23۔ اور جب وہ اپنی بیوی کے پاس گیا، تو وہ حاملہ ہوئی اور ایک بیٹا پیدا ہوا، اور اس نے اپنا نام بیریاہ رکھا، کیونکہ یہ اس کے گھر کے ساتھ برا تھا۔\n24۔ (اور اس کی بیٹی {تھی} شیراح، جس نے بیت حورون کو نیتر، اوپر اور اوزین شراہ تعمیر کیا۔)\n25۔ اور رفاہ اس کا بیٹا تھا، وہ بھی رشیف، اور تیلہ اس کا بیٹا، اور تہان اس کا بیٹا،\n26۔ لادان اس کا بیٹا، امیہود اس کا بیٹا، الیشامہ اس کا بیٹا،\n27۔ اس کا بیٹا نہیں، یہوشع اس کا بیٹا۔ {نان: یا، نن} {یہوشوع: یا، یشوع}\n28۔ اور ان کی جائیداد اور رہائش گاہیں بیت ایل اور اس کے قصبے، مشرق کی طرف ناران، اور مغرب کی طرف گیزر، اور ان کے قصبے شامل تھے؛ شیکم اور اس کے قصبے، غزہ اور اس کے قصبوں تک: {قصبے: عبرانی۔ بیٹیاں} {غزہ کے لیے: یا، آداسا}\n29۔ اور مناسی کے بچوں کی سرحدوں پر، بیت شیان اور اس کے قصبوں، طعناخ اور اس کے شہروں، مگیدو اور اس کے قصبوں، دور اور اس کے قصبوں کے پاس۔ ان میں یوسف کے بیٹے اسرائیل کے بچے رہتے تھے۔ {ٹاؤنز: عبرانی۔ بیٹیاں}\n30۔ آشر کے بیٹے؛ ایمنا، اور اسعوا، اور اشعائی، اور بریہ، اور سراح ان کی بہن۔\n31۔ اور بریاہ کے بیٹے؛ ہیبر، اور مالخیئل، جو برزاویت کا باپ ہے۔\n32۔ اور ہیبر نے یافلیٹ، شومر، ہوتھم، اور شوع کو ان کی بہن پیدا کیا۔\n33۔ اور یافلیٹ کے بیٹے؛ پاسچ، اور بمہال، اور اشوت۔ یہ {ہیں} جافلیٹ کے بچے ہیں۔\n34۔ اور شامر کے بیٹے؛ آہی، اور روہگہ، جہبا، اور آرام۔\n35۔ اور اس کے بھائی ہیلم کے بیٹے؛ زوفاہ، اور ایمنا، اور شیلش، اور امل۔\n36۔ زوفاہ کے بیٹے؛ سواہ، اور ہارنیفر، اور شوال، اور بیری، اور امرہ،\n37۔ بیزر، ہود، شمعہ، شلشاہ، ایتھران، اور بیرا۔\n38۔ اور یتر کے بیٹے؛ جیفونہ، اور پسپاہ، اور آرا۔\n39۔ اور اولا کے بیٹے؛ آراہ، اور ہانیئل، اور ریزیا۔\n40۔ یہ سب آشر کے بچے تھے، ان کے والد کے گھرانے کے سربراہ، منتخب اور بہادر آدمی، شہزادوں کے سردار۔ اور نسب نامے میں ان لوگوں کی تعداد جو جنگ کے لیے تیار تھے {اور} جنگ کے لیے تیار تھے {چھہ ہزار آدمی تھے}۔","1۔ اب بنیامین نے بیلا کو اپنا سب سے بڑا بیٹا پیدا کیا، اشبل دوسرا اور آہارہ تیسرا تھا،\n2۔ نوہا چوتھا، اور رافا پانچواں۔\n3۔ اور بیلا کے بیٹے تھے، آدار، اور گیرا، اور ابیہود، {ادار: یا، آرد}\n4۔ اور ابیشوا، اور نعمان، اور آہواہ،\n5۔ اور گیرا، اور شیفوفان، اور ہورام۔ {شیفوفان: یا، شوپھام}\n6۔ اور یہ ایہود کے بیٹے ہیں: یہ گبا کے باشندوں کے باپوں کے سر ہیں، اور انہوں نے انہیں مناہاتھ منتقل کر دیا:\n7۔ اور نعمان، آحیاہ، اور جیرا، اس نے انہیں ہٹا دیا، اور عزا اور احیہود کو جنم دیا۔\n8۔ اور شاہریم نے موآب کے ملک میں اولاد پیدا کی، جب اس نے انہیں بھیج دیا؛ ہوشم اور بارا اس کی بیویاں تھیں۔\n9۔ اور اس نے ہودیش سے اپنی بیوی، جوباب، زیبیا، اور میشا، اور ملکم کو جنم دیا،\n10۔ اور جیوز، اور شاچیا، اور مرما۔ یہ اس کے بیٹے تھے، باپوں کے سربراہ۔\n11۔ اور ہوشم سے اس نے ابیتوب اور ایلپال کو جنم دیا۔\n12۔ ایلپال کے بیٹے؛ ایبر، اور میشام، اور شیمد، جنہوں نے اونو اور لود کو ان کے شہروں کے ساتھ تعمیر کیا:\n13۔ بریاہ بھی، اور شمع، جو ایجالون کے باشندوں کے باپوں کے سربراہ تھے، جنہوں نے گات کے باشندوں کو نکال دیا:\n14۔ اور اہیو، شاشاک، اور یرموت،\n15. اور زبادیہ، اور عراد، اور آدر،\n16۔ اور مائیکل، اور اسپاہ، اور یوہا، بریاہ کے بیٹے؛\n17. اور زبادیہ، اور مشولم، اور حزقی، اور حبر،\n18۔ اشمرائی بھی، اور یزلیہ، اور یوباب، جو ایلپال کے بیٹے تھے؛\n19۔ اور جکیم، اور زکری، اور زبدی،\n20۔ اور ایلینائی، اور زیلتھائی، اور ایلیئل،\n21۔ اور ادایاہ، اور برایہ، اور شمراتھ، شمحی کے بیٹے؛ {شمہی: یا، شیما}\n22۔ اور اشپان، اور حبر، اور ایلیل،\n23. اور عبدون اور زکری اور حنان,\n24. اور حنانیا، اور ایلام، اور انتوتھیاہ،\n25۔ اور ایفیدیہ، اور پینویل، شاشاک کے بیٹے؛\n26۔ اور شمشیرائی، اور شحاریہ، اور اتھلیاہ،\n27۔ اور یریسیاہ، اور ایلیا، اور زکری، یروہام کے بیٹے۔\n28۔ یہ {تھے} آباؤ اجداد کے سربراہ، اپنی نسلوں کے مطابق، سردار {انسان}۔ یہ یروشلم میں رہتے تھے۔\n29۔ اور گبعون میں گبعون کا باپ رہتا تھا؛ جس کی بیوی کا نام {تھا} ماخاہ: {والد...: جسے جہیل بھی کہا جاتا ہے}\n30۔ اور اس کا پہلا بیٹا عبدون، زور، کیش، بعل، اور ندب،\n31۔ اور گیدور، اور اہیو، اور زاکر۔ {زاکر: یا، زکریا}\n32۔ اور مکلوت نے شمعیہ کو جنم دیا۔ اور یہ بھی اپنے بھائیوں کے ساتھ یروشلم میں رہتے تھے، ان کے خلاف۔ {شمیع: یا، شمیم}\n33۔ اور نیر نے کیش کو جنم دیا، اور کیش نے ساؤل کو جنم دیا، اور ساؤل نے یوناتھن، اور ملکیشوع، اور ابینادب، اور اشبال کو جنم دیا۔ {ابیناداب: جسے ایشوئی بھی کہا جاتا ہے} {اشبال: یا، اشبوشیث}\n34۔ اور یوناتھن کا بیٹا {تھا} مریبعل؛ اور مریبعل نے مائیکا کو جنم دیا۔ {مریبعل: یا، مفیبوشث}\n35۔ اور میکاہ کے بیٹے {تھے}، پیثون، اور ملخ، اور تریعہ، اور آحاز۔ {تاریا: یا، تہریا}\n36۔ اور آحاز نے یہوداہ کو جنم دیا؛ اور یہوداہ نے علیمت، عزماوت اور زمری کو جنم دیا؛ اور زمری نے موزا کو جنم دیا، {یہوداہ: جسے یراہ بھی کہا جاتا ہے}\n37. اور موزا نے بینیا کو جنم دیا: رافا اس کا بیٹا تھا، ایلیاسا اس کا بیٹا، عزیل اس کا بیٹا: {رافا: جسے رفعیاہ بھی کہا جاتا ہے}\n38۔ اور عزیل کے چھ بیٹے تھے، جن کے نام یہ ہیں: عزریکام، بوخرو، اسماعیل، اور شیاریہ، اور عوبدیہ، اور حنان۔ یہ سب ازل کے بیٹے تھے۔\n39۔ اور اشیق کے بیٹے اس کے بھائی تھے، اولام اس کا پہلا بیٹا، یہوش دوم، اور الیفلیٹ تیسرا۔\n40۔ اور اولام کے بیٹے بہادر اور بہادر تھے، جن کے کئی بیٹے تھے، اور بیٹوں کے بیٹے ایک سو پچاس تھے۔ یہ سب بنیامین کے بیٹوں کے ہیں۔","1۔ یوں تمام اسرائیل کو نسب ناموں کے مطابق شمار کیا گیا؛ اور دیکھو، وہ اسرائیل اور یہوداہ کے بادشاہوں کی کتاب میں {لکھے گئے}، {جو} کو ان کی گناہ کی وجہ سے بابل لے جایا گیا۔\n2۔ اب وہ پہلے باشندے جو اپنے شہروں میں اپنی جائیدادوں میں آباد ہوئے وہ تھے: اسرائیلی، کاہن، لاوی اور نیتھینیم۔\n3۔ اور یروشلم میں یہوداہ کے بیٹے، بنیامین کے بیٹے، اور افرائیم اور منسی کے بچوں کے بچے رہتے تھے؛\n4۔ اوتھائی، امیہود کا بیٹا، عمری کا بیٹا، امری کا بیٹا، بانی کا بیٹا، فریز کے بیٹے یہوداہ کے بیٹے کا بیٹا۔\n5۔ اور شیلونائٹس کی؛ عسیاہ پہلا بیٹا، اور اس کے بیٹے۔\n6۔ اور زراح کے بیٹوں کی؛ جوئل، اور ان کے بھائی، چھ سو نوے۔\n7۔ اور بنیامین کے بیٹوں کی؛ سلو مشولام کا بیٹا، ہوداویاہ کا بیٹا، حسینوح کا بیٹا،\n8۔ اور ابنیاہ، یروہام کا بیٹا، اور ایلہ، عوزی کا بیٹا، میکری کا بیٹا، اور مشولم، شفاتیاہ کا بیٹا، رئیل کا بیٹا، ابن ابنیہ؛\n9۔ اور ان کے بھائی، اپنی نسلوں کے مطابق، نو سو پچاس چھ۔ یہ سب لوگ اپنے آباؤ اجداد کے گھر میں باپوں کے سردار تھے۔\n10۔ اور پادریوں کی؛ جدیدیہ، یہویاریب اور یاچن بھی،\n11۔ اور عزریاہ ہلکیاہ کا بیٹا، مشولم کا بیٹا، زادوک کا بیٹا، میرایوت کا بیٹا، احیتب کا بیٹا، خدا کے گھرانے کا حکمران؛ {آزاریا: جسے سرایاہ بھی کہا جاتا ہے}\n12۔ اور عدایہ، یروہام کا بیٹا، پاشور کا بیٹا، ملکییاہ کا بیٹا، اور ماسیائی، جو عدیل کا بیٹا تھا، جہزراہ کا بیٹا، مشلم کا بیٹا، مشلمیت کا بیٹا، جو میر کا بیٹا تھا؛\n13۔ اور ان کے بھائی، ان کے باپ و اجداد کے خاندان کے سربراہ، ہزار سات سو تینٹھ؛ خدا کے گھر کی خدمت کے لیے بہت قابل لوگ تھے۔ {بہت...: عبرانی بہادر آدمی}\n14۔ اور لاویوں کی؛ شمعیہ، حشوب کا بیٹا، عزریکم کا بیٹا، ہشابیاہ کا بیٹا، مراری کے بیٹوں سے؛\n15۔ اور بککر، ہیرش، اور گلال، اور متانیاہ جو میکاہ کا بیٹا تھا، زکری کا بیٹا، جو آصف کا بیٹا تھا؛\n16۔ اور عوبدیہ، شمعیہ کا بیٹا، جو گلال کا بیٹا تھا، جو یدوتون کا بیٹا تھا، اور بریخیا آسا کا بیٹا، جو القانا کا بیٹا تھا، جو نیتوفحیوں کے دیہات میں رہتے تھے۔\n17۔ اور دربان {تھے}، شلوم، اور عکوب، اور تلمون، اور احمان، اور ان کے بھائی: شلم {تھا} سردار؛\n18۔ جو اب تک بادشاہ کے دروازے میں مشرق کی طرف انتظار کرتے تھے: وہ لاوی کے بچوں کی صحبت میں قلی تھے۔\n19۔ اور شلوم، جو کورے کا بیٹا تھا، ایبیاساف کا بیٹا، جو کوراح کا بیٹا تھا، اور اس کے بھائی، جو اس کے والد کے گھرانے سے تھے، اور اس کے باپ حضرات عبادت کے کاموں کے ذمہ دار تھے، خیمہ کے دروازوں کے محافظ؛ اور ان کے باپ، جو خداوند کے لشکر کے اوپر تھے، داخلے کے محافظ تھے۔ {گیٹس: عبوری۔ تھریش ہولڈز}\n20۔ اور فینحاس، الیعازر کا بیٹا، ماضی میں ان پر حکمران تھا، {اور} خداوند {تھا} اس کے ساتھ۔\n21۔ {اور} زکریا، مشلیمیاہ کا بیٹا، جماعت کے خیمہ کے دروازے کا پورٹر تھا۔\n22۔ یہ سب {جو} دروازے پر پورٹر کے طور پر منتخب کیے گئے تھے {تھے} دو سو بارہ۔ یہ ان کے گاؤں میں ان کی نسل نامے کی بنیاد پر شمار کیے جاتے تھے، جنہیں داؤد اور سیموئل پیش گو نے اپنے مقررہ عہدے پر مقرر کیا تھا۔ {کیا...: عبرانی۔ قائم شدہ} {سیٹ...: یا، ٹرسٹ}\n23۔ تو انہوں نے اور ان کے بچوں نے خداوند کے گھر کے دروازوں کی نگرانی کی، یعنی خیمہ گاہ کے گھر، کی حفاظت کے ذریعے۔\n24۔ چار حصوں میں پورٹرز تھے، مشرق، مغرب، شمال اور جنوب کی طرف۔\n25۔ اور ان کے بھائی، {جو اپنے گاؤں میں تھے} سات دن بعد وقتا فوقتا ان کے ساتھ آتے تھے۔\n26۔ ان لاویوں کے لیے، جو چار بڑے پورٹرز تھے، اپنے مقررہ عہدے پر تھے، اور خدا کے گھر کے کمروں اور خزانوں پر قابض تھے۔ {سیٹ...: یا، ٹرسٹ} {چیمبرز: یا، گودام}\n27۔ اور وہ خدا کے گھر کے آس پاس ٹھہرتے، کیونکہ ان پر ذمہ داری اور ہر صبح اس کا افتتاح ان کے لیے تھا۔\n28۔ اور ان میں سے {کچھ نے} کو خدمت کرنے والے جہازوں کی ذمہ داری دی گئی کہ وہ انہیں کہانیوں کے ذریعے اندر اور باہر لائیں۔ {لاؤ...: عبرانی انہیں کہانیوں سے اندر لاؤ، اور کہانی کے مطابق آگے بڑھو}\n29۔ ان میں سے کچھ کو بھی برتنوں، مقدس مقام کے تمام آلات، عمدہ آٹا، شراب، تیل، لوبان اور مصالحوں کی نگرانی کے لیے مقرر کیا گیا۔ {آلات: یا، برتن}\n30۔ اور کچھ پادریوں کے بیٹوں نے مصالحوں کا مرہم بنایا۔\n31۔ اور متیتیا، لاویوں میں سے {ایک}، جو شلم قرحی کا سب سے بڑا بیٹا تھا، ان اشیاء پر عہدہ رکھتا تھا جو برتنوں میں بنائی جاتی تھیں۔ {سیٹ...: یا، ٹرسٹ} {میں...: یا، چپٹی پلیٹوں پر، یا، سلائس}\n32۔ اور اپنے بھائیوں کے {دیگر}، کوہاتی کے بیٹوں میں، {روٹی کے اوپر} تھے، تاکہ ہر سبت کو تیار کریں۔ {شو بریڈ: عبوری۔ آرڈر کی روٹی}\n33۔ اور یہ وہ گلوکار ہیں، جو لاویوں کے باپوں میں سے سردار، {جو کمروں میں رہ گئے تھے} آزاد تھے: کیونکہ وہ دن رات {یہ} کام کرتے تھے۔ {وہ...: عبرانی۔ ان پر}\n34۔ لاویوں کے یہ بڑے باپ اپنی نسلوں میں سردار رہے؛ یہ یروشلم میں رہتے تھے۔\n35۔ اور گبعون میں گبعون کے والد، یہیئل، مقیم تھے، جن کی بیوی کا نام {ماخاہ} تھا:\n36۔ اور اس کا پہلا بیٹا عبدون، پھر زور، اور کیش، اور بعل، اور نیر، اور ندب،\n37۔ اور گدور، اور آحیو، اور زکریا اور مکلوت۔\n38۔ اور مکلوت نے شمیم کو جنم دیا۔ اور وہ بھی اپنے بھائیوں کے ساتھ یروشلم میں رہتے تھے، اپنے بھائیوں کے خلاف۔\n39۔ اور نیر نے کیش کو جنم دیا؛ اور کیش نے ساؤل کو جنم دیا؛ اور ساؤل نے یوناتھن، مالکیشوع، ابیناداب اور اشبال کو جنم دیا۔\n40۔ اور یوناتھن کا بیٹا مریبعل تھا: اور مریبعل نے میکاہ کو جنم دیا۔\n41۔ اور میکاہ کے بیٹے {تھے}، پیتھون اور میلخ، اور طحریا، {اور آحاز}۔\n42۔ اور آحاز نے یراہ کو جنم دیا؛ اور یرا نے علیمتھ، عزماویتھ، اور زمری کو جنم دیا؛ اور زمری نے موزا کو جنم دیا؛\n43۔ اور موزا نے بینیا کو جنم دیا؛ اور رفیعیاہ اس کا بیٹا، ایلیاسا اس کا بیٹا، عزیل اس کا بیٹا۔\n44۔ اور عزیل کے چھ بیٹے تھے، جن کے نام یہ ہیں: عزریکام، بوخرو، اسماعیل، اور شریعیہ، اور عوبدیہ، اور حنان: یہ عزل کے بیٹے تھے۔","1۔ اب فلسطینیوں نے اسرائیل کے خلاف جنگ کی؛ اور اسرائیل کے لوگ فلسطینیوں کے سامنے سے بھاگ گئے اور جبل گلبوا میں مارے گئے۔ {قتل: یا، زخمی}\n2۔ اور فلسطینیوں نے ساؤل اور اس کے بیٹوں کے پیچھے سختی سے پیروی کی؛ اور فلسطینیوں نے یوناتھن، ابیناداب اور ملکیشوع کو قتل کر دیا، جو ساؤل کے بیٹے تھے۔ {ابیناداب: جسے ایشوئی بھی کہا جاتا ہے}\n3۔ اور جنگ شاول کے خلاف سخت ہو گئی، تیر اندازوں نے اسے مارا، اور وہ تیر اندازوں سے زخمی ہو گیا۔ {اور تیر انداز: عبرانی۔ اور تیر چلانے والے کمان} {ہٹ: عبرانی۔ مل گیا}\n4۔ پھر ساؤل نے اپنے زرہ بردار سے کہا، اپنی تلوار نکالو اور مجھے اس میں گھونپ دو؛ کہیں یہ غیر ختنہ شدہ لوگ آ کر مجھ پر ظلم نہ کریں۔ لیکن اس کا آرمر بیئرر ایسا نہیں کرتا؛ کیونکہ وہ شدید خوفزدہ تھا۔ تو ساؤل نے تلوار لی اور اس پر گر پڑا۔ {مجھے گالی دو: یا، میرا مذاق اڑاؤ}\n5۔ اور جب اس کے زرہ بردار نے دیکھا کہ ساؤل مر چکا ہے، تو وہ بھی تلوار پر گر پڑا اور مر گیا۔\n6۔ یوں شاول مر گیا، اس کے تین بیٹے اور اس کا پورا گھرانے ایک ساتھ مر گئے۔\n7۔ اور جب وادی میں موجود تمام اسرائیلی لوگوں نے دیکھا کہ وہ بھاگ گئے ہیں، اور ساؤل اور اس کے بیٹے مر چکے ہیں، تو وہ اپنے شہروں کو چھوڑ کر بھاگ گئے: اور فلسطینی آئے اور وہاں بسے۔\n8۔ اور کل جب فلسطینی مقتولوں کو کپڑے اتارنے آئے، تو انہوں نے ساؤل اور اس کے بیٹوں کو جبل گلبوا میں گرے ہوئے پایا۔\n9۔ اور جب انہوں نے اسے کپڑے اتارے، تو اس کا سر اور زرہ لے کر فلسطینیوں کی سرزمین میں بھیج دیے تاکہ اپنے بتوں اور لوگوں تک خبر پہنچائیں۔\n10۔ اور انہوں نے اس کی زرہ اپنے دیوتاؤں کے گھر میں رکھی، اور اس کا سر داگون کے مندر میں باندھ دیا۔\n11۔ اور جب تمام جابشجلعاد نے سنا کہ فلسطینیوں نے ساؤل کے ساتھ کیا کیا،\n12۔ وہ سب بہادر لوگ اٹھے، اور شاول کی لاش اور اس کے بیٹوں کی لاشیں لے کر جابش لے گئے، ان کی ہڈیاں جابش کے بلوط کے درخت کے نیچے دفن کیں، اور سات دن روزہ رکھا۔\n13. یوں ساؤل اپنی اس گناہ کی وجہ سے مر گیا جو اس نے خداوند کے خلاف کی، {حتیٰ کہ} خداوند کے کلام کے خلاف بھی، جسے اس نے نہ مانا، اور اس لیے کہ اس نے {کسی مانوس روح} سے {مشورہ} مانگا کہ وہ اس سے پوچھے؛ {کمیٹڈ: عبوری۔ خلاف ورزی شدہ}\n14۔ اور خداوند سے نہ پوچھا، اس لیے اس نے اسے قتل کر دیا اور بادشاہی یسوع کے بیٹے داؤد کو دے دی۔ {جیسسی: عبرانی۔ ایسائی}","1۔ پھر تمام اسرائیل نے خود کو داؤد کے پاس ہیبرون میں جمع کیا اور کہا، دیکھو، ہم تیری ہڈی اور تمہارا گوشت ہیں۔\n2۔ اور اس کے علاوہ، جب ساؤل بادشاہ تھا، تو نے وہ شخص کیا جو اسرائیل میں نکلا اور لایا تھا: اور خداوند تیرے خدا نے تم سے کہا، تو میرے لوگوں کو اسرائیل کھلاؤ گے، اور میرے لوگوں کے اسرائیل پر حکمرانی کرو گے۔ {وقت کے ساتھ...: عبرانی۔ کل اور تیسرے دن دونوں} {feed: or, rule}\n3۔ اسی لیے اسرائیل کے تمام بزرگ بادشاہ کے پاس حبرون آئے؛ اور داؤد نے ان کے ساتھ ہیبرون میں خداوند کے سامنے عہد کیا؛ اور انہوں نے داؤد کو اسرائیل پر بادشاہ مقرر کیا، جیسا کہ خداوند نے سیموئل کے کلام کے مطابق بنایا۔ {بذریعہ: عبرانی ہاتھوں سے}\n4۔ اور داؤد اور تمام اسرائیل یروشلم گئے، جو {ہے} یبوس؛ جہاں یبوسیوں {تھے}، جو اس زمین کے باشندے تھے۔\n5۔ اور یبس کے باشندوں نے داؤد سے کہا، تم یہاں نہیں آؤ گے۔ اس کے باوجود داؤد نے صیون کا قلعہ لے لیا، جو داؤد کا شہر ہے۔\n6۔ اور داؤد نے کہا، جو بھی پہلے یبوسیوں کو مارے گا وہ سردار اور کپتان ہوگا۔ تو زرویاہ کا بیٹا یوآب سب سے پہلے اوپر چلا گیا اور سردار بن گیا۔ {چیف: عبرانی۔ سر}\n7۔ اور داؤد قلعے میں رہتا تھا؛ اسی لیے اسے شہر داؤد کہا۔ {یہ: یعنی، زایون}\n8۔ اور اس نے شہر کے ارد گرد تعمیر کیا، یہاں تک کہ میلو کے آس پاس سے: اور یوآب نے باقی شہر کی مرمت کی۔ {مرمت شدہ: عبرانی۔ دوبارہ زندہ کیا گیا}\n9۔ یوں داؤد بڑھتا گیا: کیونکہ لشکروں کا رب اس کے ساتھ تھا۔ {موم شدہ...: عببرانی۔ میں جا رہا تھا اور بڑھ رہا تھا}\n10۔ یہ بھی ان طاقتور لوگوں میں سے سردار ہیں جنہیں داؤد نے دیا تھا، جنہوں نے اس کی بادشاہی میں اس کے ساتھ مضبوطی اختیار کی، {اور} پورے اسرائیل کے ساتھ، تاکہ اسے بادشاہ بنایا جا سکے، جیسا کہ خداوند کے کلام کے مطابق اسرائیل کے بارے میں ہے۔ {مضبوط...: یا، اس کے ساتھ مضبوطی سے تھامے ہوئے}\n11۔ اور یہ ان طاقتور لوگوں کی تعداد ہے جو داؤد کے پاس تھے؛ یاشوبیم، ایک ہخمونائیٹ، کپتانوں کا سردار: اس نے ایک وقت میں تین سو مارے گئے لوگوں کے خلاف نیزہ اٹھایا۔ {ایک ہخمونائیٹ: یا، ہاخمونی کا بیٹا}\n12۔ اور اس کے بعد الیعزر آیا، جو ڈوڈو کا بیٹا تھا، آہوہائی، جو تین طاقتوروں میں سے ایک تھا۔\n13۔ وہ داؤد کے ساتھ پاسدمیم میں تھا، اور وہاں فلسطینیوں کو جنگ کے لیے جمع کیا گیا، جہاں جو سے بھرا ہوا زمین تھا؛ اور لوگ فلسطینیوں کے سامنے سے بھاگ گئے۔ {پدمیم: جسے ایفسدمیم بھی کہا جاتا ہے}\n14۔ اور وہ اس پارسل کے بیچ میں بیٹھ گئے، اسے پہنچا دیا، اور فلسطینیوں کو قتل کر دیا؛ اور خداوند نے انہیں ایک عظیم نجات کے ذریعے بچایا۔ {سیٹ...: یا، کھڑا رہا} {نجات: یا، نجات}\n15۔ اب تیس کپتانوں میں سے تین چٹان پر داؤد کے پاس گئے، جو ادولام کی غار میں تھا؛ اور فلسطینیوں کا لشکر وادی رفائیم میں خیمہ زن تھا۔ {تین...: یا، تیس پر تین کپتان}\n16۔ اور داؤد {تھا} اس وقت قلعے میں تھا، اور فلسطینیوں کا گڑھ {تھا} بیت لحم میں۔\n17۔ اور داؤد نے آرزو کی، اور کہا، اے کاش کوئی مجھے بیت لحم کے کنویں کا پانی پیتا جو دروازے پر ہے!\n18۔ اور تینوں فلسطینیوں کے لشکر کو توڑ کر بیت اللحم کے کنویں سے پانی نکالا جو دروازے کے پاس تھا، اور اسے لے کر داؤد کے پاس لے گئے، لیکن داؤد نے اسے نہیں پیا، بلکہ اسے خداوند کے لیے بہا دیا،\n19۔ اور کہا، میرے خدا نہ کرے، کہ میں یہ کام کروں: کیا میں ان لوگوں کا خون پی لوں جنہوں نے اپنی جانیں خطرے میں ڈال دی ہیں؟ کیونکہ ان کی جانوں کے خطرے کے ساتھ وہ سب کچھ لے آئے۔ اسی لیے وہ اسے نہیں پیتا تھا۔ ان چیزوں نے ان تینوں کو سب سے زیادہ متاثر کیا۔ {جن کے پاس ہے...: عبرانی۔ اپنی جانوں کے ساتھ؟}\n20۔ اور ابیشائی، جو یوآب کا بھائی تھا، تینوں میں سے سردار تھا: کیونکہ اس نے تین سو کے خلاف نیزہ اٹھایا اور انہیں مار ڈالا، اور اس کا نام تینوں میں رہا۔\n21۔ ان تینوں میں سے وہ دونوں سے زیادہ معزز تھا؛ کیونکہ وہ ان کا کپتان تھا: اگرچہ وہ {پہلے} تین تک نہ پہنچ سکا۔\n22۔ بنایا، یہوعیدہ کا بیٹا، کبزئیل کے بہادر آدمی کا بیٹا، جس نے کئی اعمال کیے تھے؛ اس نے موآب کے دو شیر نما آدمیوں کو مارا: اور وہ برفانی دن میں گڑھے میں شیر کو مار ڈالا۔ {جس نے...: عبرانی عظیم کارنامہ}\n23۔ اور اس نے ایک مصری کو مار ڈالا، جو پانچ ہاتھ لمبے قد کا {عظیم} آدمی تھا؛ اور مصری کے ہاتھ میں ایک نیزہ تھا جو بننے والے کی بیم کی طرح تھا؛ اور وہ اس کے پاس ایک چھڑی لے کر آیا، اور مصری کے ہاتھ سے نیزہ چھین لیا اور اپنے نیزے سے اسے مار ڈالا۔ {زبردست...: عبرانی۔ پیمائش}\n24۔ یہ {چیزیں} بنی یہوعیدہ کے بیٹے کے ساتھ ہوئیں، اور ان کا نام تینوں طاقتوں میں شامل تھا۔\n25۔ دیکھو، وہ تیس میں معزز تھا، لیکن {پہلے} تین تک نہ پہنچ سکا: اور داؤد نے اسے اپنی حفاظت میں رکھا۔\n26۔ فوجوں کے بہادر سپاہی بھی تھے، عساہیل یوآب کا بھائی، ایلحنان بیت لحم کے دودو کا بیٹا،\n27۔ شیموتھ دی ہارورائٹ، ہیلیز دی پیلونائٹ، {شیموتھ: یا، شممہ} {ہارورائٹ: یا، ہاروڈائٹ} {پیلونائٹ: یا، پالٹائٹ}\n28۔ ایرا، اکیش دی ٹیکوائٹ کا بیٹا، ابیزر انتوتھیٹ،\n29۔ سیبیکائی دی ہوشاتی، ایلائی دی آہوہیت، {سیبیکائی: یا، میبونائی} {ایلا: یا، زالمون}\n30۔ مہارائی نیتوفثائٹ، ہیلد بعناہ نیتوفثی کے بیٹے، {ہیلد: یا، ہیلیب}\n31۔ ایتھائی، جو گبعیہ کے ربائی کا بیٹا تھا، {جو بنیامین کے بچوں سے متعلق تھا}، بنایاہ پیراتھونائٹ،\n32۔ گاش کی ندیوں کے ہورائی، ابیل ارباٹائٹ، {ہورائی: یا، ہدائی} {ابیئل: یا، ابیالبون}\n33۔ عظماویت بہارومائی، ایلیہبا شعلبونائی،\n34۔ ہاشم دی گیزونائٹ کے بیٹے، جوناتھن شاج دی ہراریٹی کا بیٹا، {ہاشم: یا، یاشن}\n35۔ اہیام، سکار ہراریٹی کا بیٹا، ایلیفال یور کا بیٹا، {سکار: یا، شارار} {ایلیفال: یا، الیفلیٹ} {یور: یا، اہاسبائی}\n36۔ ہیفر دی میکیراتھائیٹ، آہیجہ دی پیلونائٹ،\n37۔ ہیزرو دی کارمیلیٹ، نارائی ایزبائی کا بیٹا، {ہیزرو: یا ہیزرائی} {نارائی: یا پارائی دی اربیٹ}\n38۔ یوئیل، ناتھن کا بھائی، میبھر، ہجری کا بیٹا، {بیٹا...: یا، ہیگریٹ}\n39۔ زیلیک عمونائی، نہارائی بیروتھی، یوآب کے زرویاہ کے بیٹے کا زرہ بردار،\n40۔ ایرا دی ایتھرائٹ، گاریب دی ایتھرائٹ،\n41۔ اوریاہ دی ہٹی، زباد اہلائی کا بیٹا،\n42۔ ادینا، شیزا روبینائی کا بیٹا، روبینیوں کا کپتان، اور اس کے ساتھ تیس افراد،\n43۔ حنان ماخاہ کا بیٹا، اور یوشافاٹ متھنائٹ،\n44۔ اوزیا آشتراتی، شمع اور یحییئل ہوتھان آرورائٹی کے بیٹے،\n45۔ جدیئل، شمری کا بیٹا، اور اس کا بھائی جوہا، تیزیت، {بیٹا...: یا، شمریٹ}\n46۔ الیئل مہاوی، اور جریبائی، اور یشویہ، النعم کے بیٹے، اور ایثما موآبی،\n47۔ ایلیئل، اور اوبید، اور یسیئل دی میسوبائٹ۔","1۔ اب یہ وہ لوگ ہیں جو داؤد کے پاس زکلاگ آئے، جب وہ ابھی تک اپنے آپ کو قریب رکھتا تھا کیونکہ ساؤل کا بیٹا کیش تھا: اور وہ طاقتور لوگوں میں شامل تھے، جنگ کے مددگار۔ {جبکہ...: عبرانی۔ ابھی تک خاموش رہنا}\n2. {وہ} کمانوں سے مسلح تھے، اور دائیں اور بایاں دونوں ہاتھ سے پتھر پھینکنے اور تیر چلانے میں استعمال کر سکتے تھے، حتیٰ کہ ساؤل کے بنیامین بھائیوں کے بھی۔\n3۔ سردار {تھا} آحیزر تھا، پھر یوآش، شیمعہ گبیتی کے بیٹے؛ اور جیزیئل، اور پیلٹ، عزماویت کے بیٹے؛ اور براخا، اور یہو انتوتی، {شمعہ: یا، ہسماہ}\n4۔ اور اسماعیاہ گبعونی جو تیس اور تیس سے زیادہ میں سے ایک طاقتور آدمی تھا؛ اور یرمیا، اور جہزیئل، اور یوحنان، اور یوساباد جدیراتی،\n5۔ ایلوزائی، اور یریموت، اور بیلیاہ، اور شمریہ، اور شفطیہ ہاروفی،\n6۔ القانہ، اور یسیاہ، اور عزریل، اور یعزر، اور یشوبیم، جو کہ کورہیت ہیں،\n7۔ اور یویلا اور زبادیہ، جو جدور کے یروحام کے بیٹے تھے۔\n8۔ اور وہاں گدائیوں میں سے داؤد کے پاس الگ ہو گئے اور بیابان میں طاقتور آدمیوں کے لیے کھڑے ہو گئے، {اور} جنگی لوگ جو جنگ کے لیے موزوں تھے، جو ڈھال اور بکلر سنبھال سکتے تھے، جن کے چہرے شیروں کے چہروں کی طرح تھے، اور پہاڑوں پر موجود رو کی طرح تیز تھے؛ {جنگ کی: عبرانی۔ میزبان کا} {جیسے تیز...: عبرانی جیسے پہاڑوں پر چڑھ کر جلدی کریں}\n9۔ ایزر اول، عوبدیا دوسرے، ایلیاب تیسرا،\n10۔ مشمنہ چوتھا، یرمیاہ پانچواں،\n11۔ عطائی چھٹا، ایلیئل ساتواں،\n12. یوحنان آٹھواں، الزاد آباد نویں،\n13. یرمیاہ دسویں، مکبانائی گیارہواں۔\n14۔ یہ {تھے} گاد کے بیٹوں میں سے، لشکر کے کپتان: سب سے کم {تھا} سو سے زیادہ، اور سب سے بڑا ہزار سے زیادہ۔ {ایک...: یا، جو سب سے کم سو کا مقابلہ کر سکتا تھا، اور سب سے بڑا ہزار}\n15۔ یہ وہ ہیں جو پہلے مہینے میں اردن کے اوپر سے گزرے، جب وہ اس کے تمام کنارے سے گزر چکا تھا؛ اور انہوں نے تمام وادیوں کو، مشرق اور مغرب کی طرف بھگا دیا۔ {اوور فلو: ہیب۔ بھر گیا}\n16۔ اور وہاں بنیامین اور یہوداہ کے بچوں میں سے داؤد کی گرفت میں آئے۔\n17۔ اور داؤد ان سے ملنے نکلا، اور جواب دیا اور کہا، اگر تم امن سے میرے پاس آؤ اور میری مدد کرو، تو میرا دل تم سے جڑ جائے گا؛ لیکن اگر {تم آؤ} مجھے میرے دشمنوں کے سامنے دھوکہ دینے آؤ، اور دیکھتے ہوئے کہ {میرے ہاتھوں میں کوئی ظلم نہیں} تو ہمارے باپ اجداد کے خدا کی طرف دیکھے،  اور اسے ڈانٹا۔ {ملنے کے لیے...: عبرانی۔ ان سے پہلے} {بن جانا: عبرانی۔ ایک ہو} {غلط: یا، تشدد}\n18۔ پھر روح اماسائی پر آئی، {جو کپتانوں کا سردار تھا}، {اور اس نے کہا}، 'ہم تیرے ہیں}، داؤد، اور تیرے ساتھ، اے یسوع کے بیٹے: سلام، سلامتی {ہو} تم پر، اور تمہارے مددگاروں کو [سلام}؛ کیونکہ تیرا خدا تمہاری مدد کرتا ہے۔ پھر ڈیوڈ نے انہیں قبول کیا اور انہیں بینڈ کا کپتان بنایا۔ {آیا...: عبوری۔ کپڑوں میں}\n19۔ اور منسی کے کچھ لوگ داؤد کے سامنے آئے، جب وہ فلسطینیوں کے ساتھ ساؤل کے خلاف جنگ میں آیا، لیکن انہوں نے ان کی مدد نہ کی، کیونکہ فلسطینیوں کے سرداروں نے مشورے پر اسے بھیج دیا، کہتے ہوئے، وہ اپنے مالک ساؤل کے سامنے ہمارے سر خطرے میں ڈالے گا۔ {اس کے لیے...: عبرانی ہمارے سروں پر}\n20۔ جب وہ ذیکلاگ گیا، تو اس کے پاس مناسے، عدناہ، یوزآباد، جیدیئل، مائیکل، یوزآباد، ایلیہو، اور زیلتھائی آئے، جو منسی کے ہزاروں کپتانوں میں سے ایک تھے۔\n21۔ اور انہوں نے داؤد کی مدد کی {روورز کے} گروہ کے خلاف: کیونکہ وہ سب بہادر لوگ تھے، اور لشکر کے کپتان تھے۔ {خلاف...: یا، بینڈ کے ساتھ}\n22۔ کیونکہ {اسی وقت} دن بہ دن داؤد اس کی مدد کے لیے آتا رہا، یہاں تک کہ وہ خدا کی طرح ایک عظیم میزبان بن گیا۔\n23۔ اور یہ وہ تعداد ہے جو جنگ کے لیے تیار گروہوں کے پاس آئے اور داؤد کے پاس ہیبرون آئے، تاکہ ساؤل کی بادشاہی کو خداوند کے کلام کے مطابق اس کے حوالے کر دیں۔ {بینڈز: OR، کپتان، یا، مرد: عبوری۔ ہیڈز}\n24۔ یہوداہ کے وہ بچے جو ڈھال اور نیزہ کے ساتھ تھے، چھ ہزار آٹھ سو تھے، جنگ کے لیے تیار تھے۔ {مسلح: یا، تیار}\n25۔ شمعون کے بچوں میں سے، جو جنگ کے لیے بہادر تھے، سات ہزار ایک سو۔\n26۔ لاوی کے بچوں میں سے چار ہزار چھ سو۔\n27۔ اور یہوعیادا {تھا} ہارونیوں کا سردار، اور اس کے ساتھ تین ہزار سات سو تھے؛\n28۔ اور زادوک، ایک بہادر نوجوان، اور اپنے والد کے گھرانے کے بائیس کپتان۔\n29۔ اور بنیامین کے بچوں میں، جو ساؤل کے رشتہ دار تھے، تین ہزار، کیونکہ اب تک ان میں سے زیادہ تر نے ساؤل کے گھرانے کی سرپرستی کی تھی۔ {ہم آہنگی: عبوری۔ بھائی} {سب سے عظیم...: عبرانی ان میں سے کثرت}\n30۔ اور افرائیم کے بچوں میں سے بیس ہزار آٹھ سو، بہادر مرد، جو اپنے باپوں کے گھرانے میں مشہور تھے۔ {مشہور: عبوری۔ نام رکھنے والے مرد}\n31۔ اور مناسی کے آدھے قبیلے میں سے اٹھارہ ہزار، جن کا نام ظاہر کیا گیا تھا، آئیں اور داؤد کو بادشاہ بنائیں۔\n32۔ اور اساکر کے بچوں کے بارے میں، {جو وہ لوگ تھے} جو وقت کو سمجھتے تھے، تاکہ وہ جان سکیں کہ اسرائیل کو کیا کرنا چاہیے؛ ان کے سر دو سو تھے؛ اور ان کے تمام بھائی ان کے حکم پر تھے۔\n33۔ زبولون کے بارے میں، جو جنگ کے لیے نکلے، جنگ میں ماہر، تمام جنگی آلات کے ساتھ، پچاس ہزار، جو رتبہ برقرار رکھ سکتے تھے: {وہ دوہری دل کے نہیں تھے۔ {ماہر...: یا، رینجرز آف بیٹل، یا، رینجرز ان بیٹل} {برقرار رکھو...: یا، لڑائی کو ترتیب میں سیٹ کرو} {نہیں...: ہیب۔ بغیر دل اور دل کے}\n34۔ اور نفتالی کے ہزار کپتان، اور ان کے ساتھ ڈھال اور نیزے کے ساتھ، تیس سات ہزار۔\n35۔ اور ڈینیوں کی جنگ میں ماہر بیس آٹھ ہزار چھ سو۔\n36۔ اور آشر کے بارے میں، جو جنگ میں ماہر تھے، چالیس ہزار۔ {ماہر: یا، اپنی رینک برقرار رکھنا}\n37۔ اور اردن کے دوسری طرف، روبینی، گادیت اور مناسی کے آدھے قبیلے کے، جنگ کے لیے ہر قسم کے جنگی آلات کے ساتھ، ایک لاکھ بیس ہزار۔\n38۔ یہ تمام جنگی آدمی، جو رتبہ برقرار رکھ سکتے تھے، کامل دل کے ساتھ ہیبرون آئے تاکہ داؤد کو پورے اسرائیل کا بادشاہ بنائیں؛ اور باقی سب اسرائیل بھی ایک دل کے تھے تاکہ داؤد کو بادشاہ بنایا جا سکے۔\n39۔ اور وہ تین دن داؤد کے ساتھ تھے، کھاتے اور پی رہے تھے: کیونکہ ان کے بھائیوں نے ان کے لیے تیاری کی تھی۔\n40۔ مزید برآں، جو ان کے قریب تھے، {حتی} یساکر، زبولون اور نفتالی کے پاس بھی، گدھوں، اونٹوں، خچروں پر، اور بیلوں پر روٹی لاتے تھے، {اور} گوشت، آٹا، انجیر کے کے، کشمش کے گچھے، شراب، تیل، بیل، اور بھیڑیں وافر مقدار میں لاتے تھے: کیونکہ {اسرائیل} میں خوشی تھی۔ {گوشت...: یا، کھانے کی مقدار}","1۔ اور داؤد نے ہزاروں اور سینکڑوں کے کپتانوں سے مشورہ کیا، {اور} ہر رہنما سے۔\n2۔ اور داؤد نے اسرائیل کی تمام جماعت سے کہا، اگر یہ آپ کے لیے اچھا لگے، اور خداوند ہمارے خدا کی طرف سے اچھا ہے، تو ہم اپنے بھائیوں کو ہر جگہ بھیجیں، جو اسرائیل کی سرزمین میں باقی ہیں، اور ان کے ساتھ ان کے شہروں اور مضافات میں موجود کاہنوں اور لاویوں کو بھی،  تاکہ وہ ہمارے پاس جمع ہو جائیں: {بھیجو...: عبرانی۔ آگے بڑھو اور بھیجو} {ان کے...: عبرانی میں۔ اپنے مضافات کے شہروں میں}\n3۔ اور ہم اپنے خدا کا تابوت دوبارہ اپنے پاس لاتے ہیں: کیونکہ ہم نے ساؤل کے زمانے میں اس سے سوال نہیں کیا۔ {لاؤ...: عبرانی بلائیں}\n4۔ اور تمام جماعت نے کہا کہ وہ ایسا کریں گے: کیونکہ یہ سب لوگوں کی نظر میں درست تھا۔\n5۔ یوں داؤد نے تمام اسرائیل، مصر کے شیحور سے لے کر ہیمتھ کے داخلے تک، جمع کیا تاکہ خدا کا صندوق کرجاتھجاریم سے لے آئے۔\n6۔ اور داؤد اوپر گیا، اور تمام اسرائیل، بعلہ کی طرف، {یعنی}، کیرجاتجاریم کی طرف، جو {یہوداہ کا تھا}، وہاں سے خدا خداوند کا صندوق لائے گا، جو {درمیان} کروبیوں میں رہتا ہے، جس کا نام {اس پر} پکارا جاتا ہے۔\n7۔ اور انہوں نے خدا کی صندوق کو ابیناداب کے گھر سے ایک نئی گاڑی میں اٹھایا: اور عوزا اور اہیو نے گاڑی چلائی۔ {اٹھایا گیا...: عبرانی۔ آرک بنایا تاکہ سواری کر سکوں}\n8۔ اور داؤد اور تمام اسرائیل نے خدا کے سامنے اپنی پوری طاقت، گانے سے، ہارپ، زبور کے ساتھ، سر و آواز، جھنجھن، اور ترمپٹ کے ساتھ بجایا۔ {گانا: عبرانی۔ گانے}\n9۔ اور جب وہ چیدون کے تھریشنگ فلور پر پہنچے، عزا نے صندوق پکڑنے کے لیے ہاتھ بڑھایا؛ کیونکہ بیلوں نے لڑکھڑایا۔ {چیدون: جسے ناچون بھی کہا جاتا ہے} {لڑکھڑایا: یا، ہلا دیا}\n10۔ اور خداوند کا غصہ عزا پر بھڑک اٹھا، اور اس نے اسے مارا کیونکہ اس نے صندوق پر ہاتھ رکھا: اور وہاں وہ خدا کے سامنے مر گیا۔\n11۔ اور داؤد ناراض ہوا، کیونکہ خداوند نے عزا پر حملہ کر دیا تھا: اسی لیے وہ جگہ آج تک پیریزوزا کہلاتی ہے۔ {پیریزوزا: یعنی، عزا کی دراڑ}\n12۔ اور اس دن داؤد خدا سے ڈر گیا، کہنے لگا، میں خدا کی صندوق {گھر} کو کیسے لے آؤں؟\n13۔ یوں داؤد نے صندوق {گھر} اپنے پاس داؤد کے شہر میں نہیں لایا، بلکہ اسے اوبیدیدوم دی گٹی کے گھر لے گیا۔ {لایا گیا: عبوری۔ ہٹا دیا گیا}\n14۔ اور خدا کا صندوق اوبیدیدوم کے خاندان کے پاس تین ماہ تک اس کے گھر میں رہا۔ اور خداوند نے اوبیدیڈوم کے گھرانے اور جو کچھ اس کے پاس تھا اسے برکت دی۔","1۔ اب ہیرم بادشاہ ٹائر نے داؤد کے پاس پیغامبر بھیجے، دیودار کی لکڑی، مزدوروں اور بڑھئیوں کے ساتھ، تاکہ اس کے لیے گھر بنائیں۔\n2۔ اور داؤد نے محسوس کیا کہ خداوند نے اسے اسرائیل پر بادشاہ مقرر کیا ہے، کیونکہ اس کی بادشاہی اس کے لوگوں اسرائیل کی وجہ سے بلند ہوئی۔\n3۔ اور داؤد نے یروشلم میں مزید بیویاں حاصل کیں: اور داؤد نے مزید بیٹے اور بیٹیاں پیدا کیں۔ {مزید: عبوری۔ ابھی تک}\n4۔ اب یہ {ہیں} ان {اس} کے بچوں کے نام جو اس کے یروشلم میں تھے؛ شموعہ، اور شوباب، ناتھن، اور سلیمان،\n5۔ اور ایبار، اور الیشوع، اور ایلپالیت،\n6۔ اور نوگا، اور نیفگ، اور یافیہ،\n7۔ اور الیشما، اور بیلیادا، اور ایلیفالٹ۔ {بیلیادا: جسے ایلیادا بھی کہا جاتا ہے}\n8۔ اور جب فلسطینیوں نے سنا کہ داؤد کو پورے اسرائیل کا بادشاہ مقرر کیا گیا ہے، تو تمام فلسطینی داؤد کو تلاش کرنے چلے گئے۔ اور داؤد نے سنا، اور ان کے خلاف نکل گیا۔\n9۔ اور فلسطینی آئے اور ریفائیم کی وادی میں پھیل گئے۔\n10۔ اور داؤد نے خدا سے پوچھا کہ کیا میں فلسطینیوں کے خلاف جاؤں؟ اور کیا تم انہیں میرے ہاتھ میں دے دو گے؟ اور خداوند نے اس سے کہا، اوپر چڑھو؛ کیونکہ میں انہیں تمہارے ہاتھ میں دے دوں گا۔\n11۔ تو وہ بعلپرازیم کے پاس آئے؛ اور ڈیوڈ نے انہیں وہاں مارا۔ پھر داؤد نے کہا، خدا نے میرے دشمنوں پر میرے ہاتھ سے ایسے حملہ کیا جیسے پانی پھٹتا ہے: اسی لیے انہوں نے اس جگہ کا نام بعلپرازیم رکھا۔ {بعلپیرازم: یعنی، دراڑوں کی جگہ}\n12۔ اور جب انہوں نے اپنے دیوتاؤں کو وہاں چھوڑ دیا، داؤد نے حکم دیا، اور انہیں آگ سے جلا دیا گیا۔\n13۔ اور فلسطینیوں نے ایک بار پھر وادی میں پھیل گئے۔\n14۔ اسی لیے داؤد نے دوبارہ خدا سے پوچھا؛ اور خدا نے اس سے کہا، ان کے پیچھے مت جانا؛ ان سے منہ موڑ لیں، اور انہیں شہتوت کے درختوں کے ساتھ دیکھیں۔\n15۔ اور جب تم شہتوت کے درختوں کی چوٹیوں سے چلنے کی آواز سنو گے، تب تم جنگ کے لیے نکلو گے: کیونکہ خدا تمہارے سامنے نکلا ہے تاکہ فلسطینیوں کے لشکر کو شکست دے۔\n16۔ لہٰذا داؤد نے خدا کے حکم کے مطابق عمل کیا: اور انہوں نے فلسطینیوں کے لشکر کو گبعون سے حتیٰ کہ گیزر تک شکست دی۔ {گبیون: جسے گیبا بھی کہا جاتا ہے}\n17۔ اور داؤد کی شہرت تمام زمینوں تک پھیل گئی؛ اور خداوند نے اس کا خوف تمام قوموں پر ڈالا۔","1۔ اور {داؤد} نے اسے داؤد کے شہر میں گھر بنائے، خدا کے صندوق کے لیے جگہ تیار کی، اور اس کے لیے خیمہ بنایا۔\n2۔ پھر داؤد نے کہا، خدا کا تابوت صرف لاویوں کو لے جانا چاہیے: کیونکہ خداوند نے خدا کا صندوق اٹھانے اور ہمیشہ کے لیے اس کی خدمت کرنے کا انتخاب کیا ہے۔ {کوئی نہیں...: عبرانی۔ یہ خدا کا صندوق اٹھانے کے لیے نہیں، بلکہ لاویوں کے لیے ہے}\n3۔ اور داؤد نے تمام اسرائیلیوں کو یروشلم میں جمع کیا، تاکہ خداوند کا صندوق اس کی جگہ لے آئیں، جو اس نے اس کے لیے تیار کیا تھا۔\n4۔ اور داؤد نے ہارون کے بچوں اور لاویوں کو جمع کیا:\n5۔ کوہاتھ کے بیٹوں سے؛ یوریل سردار، اور اس کے بھائی سو بیس: {بھائی: یا، رشتہ دار}\n6۔ میراری کے بیٹوں سے؛ عسیاہ سردار اور اس کے بھائی دو سو بیس:\n7۔ گرشوم کے بیٹوں سے؛ جوئل سردار اور اس کے بھائیوں کی تعداد تیس سو ہے:\n8۔ ایلیزافان کے بیٹوں سے؛ شمعیاہ سردار اور اس کے دو سو بھائی:\n9۔ حبرون کے بیٹوں سے؛ ایلیئل سردار اور اس کے بھائیوں نے چاروں:\n10۔ عزیل کے بیٹوں کی؛ امیناڈاب سردار اور اس کے بھائی ایک سو بارہ۔\n11۔ اور داؤد نے زادوک اور ابیاتار کو کاہنوں، اور لاویوں کو، یوریل، عسعیا، اور یوئیل، شمعیا، اور ایلیل، اور امیناداب کو بلایا،\n12۔ اور انہوں نے ان سے کہا، تم لاویوں کے باپ اجداد کے سردار ہو: اپنے آپ کو پاک کرو، تم اور تمہارے بھائیو، تاکہ تم خداوند خدا اسرائیل کی تابوت کو اس جگہ لے آؤ جو میں نے اس کے لیے تیار کی ہے۔\n13۔ کیونکہ تم نے شروع میں ایسا نہیں کیا، خداوند ہمارے خدا نے ہم پر ظلم کیا، کیونکہ ہم نے اسے مناسب حکم کے مطابق نہیں مانگا۔\n14۔ یوں کاہنوں اور لاویوں نے خود کو مقدس بنایا تاکہ خداوند خدا اسرائیل کا تابوت اٹھا سکیں۔\n15۔ اور لاویوں کے بچوں نے خدا کا صندوق اپنے کندھوں پر اٹھایا اور اس پر لاٹھیاں تھیں، جیسا کہ موسیٰ نے خداوند کے کلام کے مطابق حکم دیا تھا۔\n16۔ اور داؤد نے لاویوں کے سردار سے کہا کہ وہ اپنے بھائیوں کو موسیقی، زبور، ہارپ اور سمبلز کے آلات کے ساتھ گانے والے مقرر کریں، اور خوشی سے آواز بلند کریں۔\n17۔ یوں لاویوں نے ہیمان کو یوئیل کا بیٹا مقرر کیا؛ اور اس کے بھائیوں میں، آساف، بریخیاہ کا بیٹا؛ اور مراری کے بیٹوں کے بھائی ایتھن جو کشایہ کا بیٹا تھا؛\n18۔ اور ان کے ساتھ ان کے دوسرے درجے کے بھائی، زکریا، بن، یازیئل، شمیرموت، یحییل، اونی، ایلیاب، بنایا، ماسیہ، متیتیا، الیفیلیہ، مکنیا، اوبیدوم، اور یئیئل، جو کہ دربان تھے۔\n19۔ یوں گلوکار، ہیمان، آساف، اور ایتھن، {کو پیتل کے سنبلز سے آواز دینے کے لیے مقرر کیا گیا}؛\n20۔ اور زکریا، اور عزیل، اور شمیرموت، اور یہیئل، اور اونی، اور ایلیاب، اور ماسیہیہ، اور بنایا، جن کے زبور علموتھ پر ہیں؛\n21۔ اور متیتیا، اور ایلفیلیہ، اور مکنیا، اور اوبیدوم، اور جیئل، اور عززیہ، جن کے پاس شمنیت پر ہارپ تھے تاکہ وہ نمایاں ہوں۔ {پر...: یا، آٹھویں تاریخ کو نگرانی کے لیے}\n22۔ اور چنانیہ، لاویوں کا سردار، {تھا} گانے کے لیے: اس نے گیت کی تعلیم دی، کیونکہ وہ {ماہر} تھا۔ {تھا...: یا، گاڑی کے لیے تھا: اس نے گاڑی کے بارے میں ہدایت دی} {گانا: عبرانی۔ اٹھانا}\n23۔ اور بریخیاہ اور الکانہ کشتی کے دربان تھے۔\n24۔ اور شبانیا، اور یہوشافاط، اور نیتھانیل، اور اماسائی، زکریا، اور بنایا، اور ایلیعزر جو کاہنوں تھے، خدا کے صندوق کے سامنے بگل سے بجاتے تھے: اور اوبیدیدوم اور یہیاہ صندوق کے دربان تھے۔\n25۔ تو داؤد، اسرائیل کے بزرگ، اور ہزاروں کے کپتان، خوشی خوشی خداوند کے عہد نامے کا صندوق اوبیدیدوم کے گھر سے نکالنے گئے۔\n26۔ اور جب خدا نے لاویوں کی مدد کی جو خداوند کے عہد کا صندوق اٹھائے ہوئے تھے، تو انہوں نے سات بیل اور سات مینڈھے پیش کیے۔\n27۔ اور داؤد نے عمدہ کپڑے کا لباس پہنا، اور تمام لاوی جو صندوق ننگا کرتے تھے، اور گانے والے، اور چنانیاہ گانے والوں کے ساتھ گیت کا ماہر: داؤد کے پاس بھی کپڑے کا ایفود تھا۔ {گانا: یا، گاڑی}\n28۔ یوں تمام اسرائیل نے خداوند کے عہد کے صندوق کو چیختے ہوئے، کارنیٹ کی آواز، بگل اور جھنجھوں کے ساتھ اٹھایا، اور زبور اور ہارپ کے ساتھ شور کیا۔\n29۔ اور ایسا ہوا، {جسے} خداوند کے عہد کا صندوق داؤد کے شہر میں آیا، کہ شاول کی بیٹی میخال نے کھڑکی سے باہر دیکھا کہ بادشاہ داؤد ناچ رہا ہے اور کھیل رہا ہے، اور اس نے دل سے اسے حقیر سمجھا۔","1۔ تو انہوں نے خدا کا صندوق لایا اور اسے اس خیمے کے بیچ میں رکھا جو داؤد نے اس کے لیے بنایا تھا، اور خدا کے سامنے جلتی ہوئی قربانیاں اور امن کی قربانیاں پیش کیں۔\n2۔ اور جب داؤد نے جلنے کی قربانیاں اور صلح کی قربانیاں ختم کیں، تو اس نے خداوند کے نام پر لوگوں کو برکت دی۔\n3۔ اور اس نے اسرائیل کے ہر فرد کو، مرد اور عورت دونوں، ہر ایک کو روٹی، گوشت کا ایک ٹکڑا اور شراب کا ایک پیالہ دیا۔\n4۔ اور اس نے لاویوں میں سے کچھ کو مقرر کیا کہ وہ خداوند کے صندوق کے سامنے خدمت کریں، اور اسرائیل کے خداوند خدا کا شکر ادا کریں، اور اس کی تعریف کریں:\n5۔ اصف، سردار، اور اس کے ساتھ زکریا، یئیل، اور شمیرموت، اور یہیئل، اور متیتیا، اور ایلیاب، اور بنایا، اور اوبیدوم؛ اور یئیئل زبور اور ہارپ کے ساتھ؛ لیکن آساف نے سنبلز سے آواز نکالی؛ {زبور کے ساتھ...: عبرانی۔ زبور اور ہارپ کے آلات کے ساتھ}\n6۔ بنایاہ اور جہازئیل وہ کاہن، جو خدا کے عہد کے صندوق کے سامنے مسلسل بگل بجاتے ہیں۔\n7۔ پھر اسی دن داؤد نے سب سے پہلے {یہ زبور} خداوند کا شکریہ ادا کرنے کے لیے اصفف اور اس کے بھائیوں کے ہاتھ میں دیا۔\n8۔ خداوند کا شکر ادا کرو، اس کا نام پکارو، اس کے اعمال کو لوگوں میں ظاہر کرو۔\n9۔ اس کے لیے گاؤ، اس کے لیے زبور گاؤ، اس کے تمام حیرت انگیز کاموں کے بارے میں بتاؤ۔\n10۔ اس کے مقدس نام میں جلال پائے: خداوند کی تلاش کرنے والوں کے دل خوش ہوں۔\n11۔ خداوند اور اس کی طاقت تلاش کرو، اس کا چہرہ مسلسل تلاش کرو۔\n12۔ اس کے شاندار کاموں کو یاد رکھو جو اس نے کیے، اس کے عجائبات کو، اور اس کے منہ کے فیصلے؛\n13۔ اے اسرائیل کی نسل اے اس کے بندے، اے یعقوب کے بیٹوں، اس کے منتخب کردہ لوگوں۔\n14. وہ خداوند ہمارا خدا ہے؛ اس کے فیصلے پوری زمین میں ہیں۔\n15۔ ہمیشہ اس کے عہد کا خیال رکھو؛ وہ لفظ {جو} اس نے ہزار نسلوں تک حکم دیا؛\n16۔ {حتیٰ کہ اس عہد کے بارے میں} جو اس نے ابراہیم کے ساتھ کیا تھا، اور اسحاق سے اپنی قسم کا؛\n17۔ اور یہی بات یعقوب کو قانون کے طور پر تصدیق کی ہے، {اور} اسرائیل کے لیے {ایک دائمی عہد کے لیے}،\n18۔ کہتا ہوں، میں تمہیں کنعان کی زمین دوں گا، تمہاری وراثت کا حصہ؛ {سب لوگ: عبرانی۔ رسی}\n19۔ جب تم چند تھے، یہاں تک کہ چند بھی، اور اس میں اجنبی تھے۔ {کچھ بھی: عبوری۔ تعداد میں مرد وغیرہ}\n20۔ اور {جب} وہ ایک قوم سے دوسری قوم گئے، اور {ایک} سلطنت سے دوسری قوم؛\n21۔ اس نے کسی کو ان کے ساتھ ظلم کرنے کی اجازت نہیں دی: ہاں، اس نے بادشاہوں کو ان کی خاطر ڈانٹا،\n22. {کہا}، میرے مسح شدہ کو ہاتھ نہ لگاؤ، اور میرے نبیوں کو نقصان نہ پہنچاؤ۔\n23. خداوند کے لیے گاؤ، ساری زمین؛ دن بہ دن اپنی نجات دکھاتا ہے۔\n24۔ کافروں میں اپنی شان کا اعلان کرو؛ تمام قوموں میں ان کے شاندار کام۔\n25. کیونکہ عظیم {ہے} خداوند ہے، اور بہت زیادہ تعریف کے لائق ہے: وہ بھی تمام دیوتاؤں سے بڑھ کر خوفزدہ ہے۔\n26۔ کیونکہ قوم کے تمام دیوتا بت ہیں: لیکن خداوند نے آسمان بنایا۔\n27۔ جلال اور عزت اس کی موجودگی میں ہے؛ طاقت اور خوشی اس کی جگہ ہے۔\n28. اے قوم کے رشتہ داروں، خداوند کو عطا فرما، خداوند کو جلال اور طاقت دو۔\n29۔ خداوند کو اس کے نام کی جلال عطا فرما: ایک قربانی پیش کرو اور اس کے سامنے آؤ: پاکیزگی کی خوبصورتی میں خداوند کی عبادت کرو۔\n30۔ اس کے سامنے خوف رکھو، ساری زمین: دنیا بھی مستحکم ہوگی، تاکہ اسے ہلا نہ دیا جائے۔\n31۔ آسمان خوش ہوں، اور زمین خوش ہو: اور {لوگ} قوموں میں کہیں، خداوند بادشاہت کرتا ہے۔\n32۔ سمندر کو گرجنے دو، اور اس کی بھرپوریت کو بھی: کھیتوں کو خوشی ہو، اور اس میں جو کچھ بھی ہے۔\n33۔ پھر جنگل کے درخت خداوند کی موجودگی میں گائیں گے، کیونکہ وہ زمین کا فیصلہ کرنے آیا ہے۔\n34۔ اے خداوند کا شکر ادا کرو؛ کیونکہ {وہ} اچھا ہے؛ اس کی رحمت {ہمیشہ کے لیے} کے لیے۔\n35۔ اور کہو، اے خدا، ہماری نجات کے خدا، ہمیں بچا، اور ہمیں اکٹھا کر، اور کافروں سے نجات دے، تاکہ ہم تیرے مقدس نام کا شکر ادا کریں، {اور} تیری تعریف میں جلال پائیں۔\n36۔ ہمیشہ ہمیشہ کے لیے اسرائیل کے خداوند خدا کو مبارک ہو۔ اور سب نے کہا، آمین، اور خداوند کی تعریف کی۔\n37۔ تو وہ وہاں سے خداوند اصاف اور اس کے بھائیوں کے عہد کے صندوق کے سامنے روانہ ہوا، تاکہ روزانہ کے کام کے مطابق صندوق کے سامنے مسلسل خدمت کرے:\n38۔ اور اوبیدیڈوم اپنے بھائیوں کے ساتھ، تین سو اور آٹھ؛ اوبیدیڈوم، جو جدیدتون اور ہوسا {بعدی} پورٹرز کا بیٹا بھی تھا:\n39۔ اور زادوک کاہن، اور اس کے بھائی، کاہن، خداوند کے خیمے کے سامنے، جو گبعون میں بلند مقام پر تھا،\n40۔ خداوند کے سامنے سلائی کی قربان گاہ پر صبح اور شام مسلسل نذرانہ پیش کرنا، اور خداوند کے قانون میں لکھی ہوئی تمام چیزوں کے مطابق جو اس نے اسرائیل کو حکم دیا؛ {صبح بخیر...: عبوری۔ صبح اور شام میں}\n41۔ اور ان کے ساتھ ہیمان اور جیدوتھن، اور باقی جو منتخب ہوئے، جن کا نام ظاہر کیا گیا، خداوند کا شکر ادا کرنے کے لیے، کیونکہ اس کی رحمت ہمیشہ قائم رہتی ہے؛\n42۔ اور ان کے ساتھ ہیمن اور جیدوتھن، جن میں بگل اور سنبلز تھے ان کے لیے جو آواز نکالیں، اور خدا کے ساز بھی۔ اور جیدوتھون کے بیٹے قلی تھے۔ {پورٹرز: عبرانی۔ دروازے کے لیے}\n43۔ اور تمام لوگ ہر آدمی کو اس کے گھر روانہ ہو گئے: اور داؤد اپنے گھر کو برکت دینے کے لیے واپس آیا۔","1۔ اب ایسا ہوا جب داؤد اپنے گھر میں بیٹھا تھا، کہ داؤد نے ناتھن نبی سے کہا، دیکھو، میں دیودار کے گھر میں رہتا ہوں، لیکن خداوند کے عہد کا صندوق پردے کے نیچے ہے۔\n2۔ پھر ناتھن نے داؤد سے کہا، اپنے دل میں جو کچھ ہے وہ کرو؛ کیونکہ خدا تمہارے ساتھ ہے۔\n3۔ اور اسی رات خدا کا کلام ناتھن کے پاس آیا، جس میں کہا گیا،\n4۔ جاؤ اور میرے بندے کو داؤد سے بتانا، خداوند یوں فرماتا ہے، تو مجھے رہنے کے لیے گھر نہیں بنا سکتا:\n5۔ کیونکہ میں نے آج تک اس دن سے کسی گھر میں نہیں رہا؛ لیکن خیمے سے خیمے تک، اور {ایک} خیمہ {سے دوسرے تک} گئے۔ {چلے گئے ہیں: عبوری۔ رہا ہوں}\n6۔ جہاں بھی میں نے پورے اسرائیل کے ساتھ چلنا شروع کیا، میں نے اسرائیل کے کسی بھی جج سے ایک لفظ کہا، جنہیں میں نے اپنے لوگوں کو کھلانے کا حکم دیا تھا، کہہ دیا، تم نے میرے لیے دیودار کا گھر کیوں نہیں بنایا؟\n7۔ اب تو تم میرے بندے داؤد سے یوں کہو گے، یوں فرماتا ہے رب لشکروں میں، میں نے تمہیں بھیڑوں کے بستر سے نکالا، {حتیٰ کہ} بھیڑوں کی پیروی سے بھی، تاکہ تم میرے قوم اسرائیل پر حکمران ہو: {پیروی سے: عبرانی۔ اس کے بعد سے}\n8۔ اور میں تمہارے ساتھ تھا جہاں بھی تم گئے، اور تمہارے تمام دشمنوں کو تمہارے سامنے سے کاٹ دیا، اور تمہیں زمین پر موجود عظیم لوگوں کے نام جیسا نام دیا۔\n9۔ اور میں اپنے لوگوں کے لیے اسرائیل کے لیے جگہ مقرر کروں گا، انہیں لگاؤں گا، اور وہ اپنی جگہ رہیں گے، اور مزید منتقل نہیں ہوں گے؛ نہ ہی برائی کے بچے انہیں مزید ضائع کریں گے، جیسا کہ ابتدا میں تھا،\n10۔ اور جب سے میں نے اپنے لوگوں اسرائیل پر ججوں کو حکم دیا تھا۔ مزید برآں، میں تمہارے تمام دشمنوں کو زیر کروں گا۔ مزید یہ کہ میں تمہیں بتاتا ہوں کہ خداوند تمہارے لیے ایک گھر بنائے گا۔\n11۔ اور جب تمہارے دن ختم ہو جائیں گے تو تمہیں اپنے باپ دادا کے ساتھ جانا ہوگا، کہ میں تمہارے بعد تمہاری نسل کو زندہ کروں گا، جو تمہارے بیٹوں کی ہوں گی؛ اور میں اس کی سلطنت قائم کروں گا۔\n12۔ وہ میرے لیے ایک گھر بنائے گا، اور میں اس کا تخت ہمیشہ کے لیے قائم رکھوں گا۔\n13۔ میں اس کا باپ بنوں گا، اور وہ میرا بیٹا ہوگا: اور میں اس سے اپنی رحمت نہیں چھینوں گا، جیسا کہ میں نے اس سے لیا جو تمہارے سامنے تھا:\n14۔ لیکن میں اسے ہمیشہ کے لیے اپنے گھر اور اپنی بادشاہی میں آباد کروں گا: اور اس کا تخت ہمیشہ کے لیے قائم ہوگا۔\n15۔ ان تمام الفاظ کے مطابق، اور اس تمام خواب کے مطابق، ناتھن نے بھی داؤد سے بات کی۔\n16۔ اور داؤد بادشاہ آیا اور خداوند کے سامنے بیٹھ گیا، اور کہا، اے خداوند خدا، میں کون ہوں، اور میرا گھر کیا ہے جو تو مجھے یہاں لے آیا ہے؟\n17. اور {پھر بھی} یہ تمہاری نظر میں ایک چھوٹی سی بات تھی، اے خدا؛ کیونکہ تو نے بھی کافی عرصے سے اپنے خادم کے گھر کی بات کی ہے، اور مجھے ایک اعلیٰ درجے کے آدمی کی حیثیت کے مطابق دیکھا، اے خداوند خدا۔\n18۔ ڈیوڈ آپ سے اپنے خادم کی عزت کے لیے اور کیا کہہ سکتا ہے؟ کیونکہ تم اپنے خادم کو جانتے ہو۔\n19۔ اے خداوند، اپنے بندے کی خاطر، اور اپنے دل کے مطابق، تو نے یہ ساری عظمت کی ہے، ان سب عظیم چیزوں کو ظاہر کرنے میں۔ {زبردست...: عبرانی۔ عظمتیں}\n20. اے خداوند، {تیرے جیسا کوئی نہیں}، نہ ہی تیرے سوا کوئی خدا نہیں، جیسا کہ ہم نے اپنے کانوں سے سنا ہے۔\n21۔ اور زمین پر کون سی ایک قوم ہے جو تیری قوم اسرائیل جیسی ہے، جسے خدا نے اپنی قوم کو نجات دینے کے لیے کیا ہے، تمہیں عظمت اور ہولناک بنانے کے لیے، اپنی قوم کے سامنے سے ان قوموں کو نکال کر جنہیں تم نے مصر سے نجات دی ہے؟\n22۔ اپنی قوم کے لیے اسرائیل نے ہمیشہ کے لیے اپنی قوم بنائی؛ اور تو، اے خداوند، ان کا خدا بن گیا۔\n23۔ تو اب، اے خداوند، جو بات تو نے اپنے خادم اور اس کے گھر کے بارے میں کہی ہے، وہ ہمیشہ کے لیے قائم ہو جائے، اور جو کہا ہے وہ کرو۔\n24۔ یہ بھی قائم ہو جائے کہ تیرا نام ہمیشہ کے لیے بلند ہو جائے، اور کہا جائے، لشکروں کا رب اسرائیل کا خدا ہے، اسرائیل کا خدا ہے، اور داؤد کا گھرانہ، تیری بندہ تمہارے سامنے قائم ہو۔\n25۔ کیونکہ تو، اے میرے خدا، نے اپنے بندے کو بتایا ہے کہ تم اس کے لیے ایک گھر بناؤ گے، اس لیے تمہارے بندے نے اپنے دل میں دعا کرنے کا موقع پایا ہے۔ {ہسٹ...: عببرانی۔ تمہارے خادم کا کان ظاہر کر دیا ہے}\n26. اور اب، اے خداوند، تو خدا ہو، اور اپنے بندے سے یہ بھلائی کا وعدہ کیا ہے:\n27. اب تمہیں یہ پسند آئے کہ اپنے بندے کے گھر کو برکت دو، تاکہ وہ ہمیشہ تمہارے سامنے رہے: کیونکہ تو برکت دیتا ہے، اے خداوند، اور یہ ہمیشہ کے لیے بابرکت ہوگا۔ {آؤ...: یا، تمہیں پسند آیا}","1۔ اس کے بعد ہوا کہ داؤد نے فلسطینیوں کو شکست دی، انہیں زیر کر دیا، اور گت اور اس کے قصبے فلسطینیوں کے ہاتھوں سے چھین لیے۔\n2۔ اور اس نے موآب کو مارا؛ اور موآبائی داؤد کے خادم بن گئے، {اور} تحائف لے کر آئے۔\n3۔ اور داؤد نے زباہ کے بادشاہ ہدارزر کو ہامات پر حملہ کیا، جب وہ دریائے فرات کے کنارے اپنی سلطنت قائم کرنے گیا تھا۔ {ہداریزر: یا، ہادادیزر}\n4۔ اور داؤد نے اس سے ہزار رتھیں، سات ہزار گھڑ سوار اور بیس ہزار پیادہ لیے: داؤد نے تمام رتھ {گھوڑے} پر قبضہ کیا، لیکن ان میں سے سو رتھ محفوظ رکھے۔ {سات...: یا، سات سو}\n5۔ اور جب دمشق کے شامی حضرزر، بادشاہ زوباہ کی مدد کے لیے آئے، تو داؤد نے شامیوں میں سے دو بیس ہزار آدمیوں کو قتل کر دیا۔ {دمشق: عبرانی۔ دارمیسیک}\n6۔ پھر داؤد نے شام دمشق میں {گارنیں} قائم کیں؛ اور شامی داؤد کے خادم بن گئے، {اور} تحائف لاتے تھے۔ یوں خداوند نے داؤد کو جہاں بھی گیا، محفوظ رکھا۔\n7۔ اور داؤد نے ہدارزر کے خادموں پر موجود سونے کی ڈھالیں لے کر یروشلم لے آئیں۔\n8۔ اسی طرح تیبہات اور چون سے، ہدارزر کے شہروں سے، داؤد نے بہت سا پیتل لایا، جس سے سلیمان نے برسن سمندر، ستون اور برتن پیتل کے بنائے۔ {تیبتھ...: کتاب سیموئل بیٹاہ اور بیروتھائی میں بلایا گیا}\n9۔ اب جب حماث کے بادشاہ تو نے سنا کہ داؤد نے زبہ کے بادشاہ ہدارزر کے تمام لشکر کو شکست دی؛ {تو: جسے توئی بھی کہا جاتا ہے}\n10۔ اس نے اپنے بیٹے ہادورام کو بادشاہ داؤد کے پاس بھیجا، اس کی خیریت معلوم کرنے اور اسے مبارکباد دینے کے لیے، کیونکہ اس نے ہدارزر کے خلاف لڑائی کی تھی اور اسے مارا تھا؛ (کیونکہ ہداریزر نے تو کے ساتھ جنگ کی تھی؛) اور {اس کے ساتھ} سونے، چاندی اور پیتل کے ہر قسم کے برتن تھے۔ {ہادورم: جسے جورام بھی کہا جاتا ہے} {پوچھنے کے لیے...: یا، سلام کرنے کے لیے} {مبارکباد دینے کے لیے: عبرانی۔ برکت دینے کے لیے} {جنگ ہوئی: عبرانی۔ وہ مین آف وارز تھا}\n11۔ انہوں نے بادشاہ داؤد کو بھی خداوند کے لیے وقف کیا، چاندی اور سونا جو اس نے تمام قوموں سے لایا تھا؛ ادوم سے، موآب سے، عمون کے بچوں سے، فلسطینیوں سے، اور عمالیق سے۔\n12۔ مزید برآں، زرویاہ کے بیٹے ابیشائی نے نمک کی وادی میں اٹھارہ ہزار آدمیوں کو قتل کیا۔ {ابیشائی: عبرانی۔ ابشائی}\n13۔ اور اس نے ایڈم میں گارڈز قائم کیے؛ اور تمام ادومی داؤد کے خادم بن گئے۔ یوں خداوند نے داؤد کو جہاں بھی گیا، محفوظ رکھا۔\n14۔ یوں داؤد نے پورے اسرائیل پر حکومت کی، اور اپنے تمام لوگوں میں فیصلہ اور انصاف نافذ کیا۔\n15۔ اور یوآب زریاہ کا بیٹا لشکر پر تھا؛ اور یہوشافاط، احیلود کا بیٹا، ریکارڈر۔ {ریکارڈر: یا، ریممبرانسر}\n16. اور صادوق، اہیتب کا بیٹا، اور ابیمیلک ابیاتھر کا بیٹا، {تھے} کاہن تھے؛ اور شوشہ کاتب تھے؛ {ابیملک: جسے احیمیلک بھی کہا جاتا ہے} {شوشہ: جسے سریا یا شیشہ بھی کہا جاتا ہے}\n17۔ اور بنیعاہ، یہوعیادا کا بیٹا، چریثیوں اور پیلثیوں پر تھا؛ اور داؤد کے بیٹے بادشاہ کے سردار تھے۔ {بارے میں...: عبرانی بادشاہ کے ہاتھوں}","1۔ اس کے بعد یہ ہوا کہ ناہش، جو آمون کے بچوں کا بادشاہ تھا، فوت ہو گیا، اور اس کا بیٹا اس کی جگہ حکومت کرنے لگا۔\n2۔ اور داؤد نے کہا، میں حنون کے بیٹے ناحاش کے ساتھ مہربانی کروں گا، کیونکہ اس کے والد نے مجھ پر مہربانی کی۔ اور داؤد نے اپنے والد کے بارے میں اسے تسلی دینے کے لیے پیغامبر بھیجے۔ چنانچہ داؤد کے خادم آمون کے بچوں کی سرزمین میں حنون کے پاس آئے، تاکہ اسے تسلی دیں۔\n3۔ لیکن آمون کے بچوں کے شہزادوں نے حنون سے کہا، کیا تم سمجھتے ہو کہ داؤد تمہارے والد کی عزت کرتا ہے، کہ اس نے تمہارے پاس تسلی دینے والے بھیجے ہیں؟ کیا اس کے خادم آپ کے پاس تلاش کرنے، تختہ الٹنے، اور زمین کی جاسوسی کے لیے نہیں آتے؟ {تھنکیسٹ...: عبرانی۔ تمہاری آنکھوں میں داؤد ہے، وغیرہ}\n4۔ چنانچہ حنون نے داؤد کے خادموں کو لے کر شیو کیا، ان کے کپڑے ان کے کولہوں سے سختی سے کاٹ دیے اور انہیں بھیج دیا۔\n5۔ پھر {یقین} گیا، اور داؤد نے بتایا کہ مردوں کی خدمت کیسے کی جاتی ہے۔ اور اس نے ان سے ملنے بھیجا: کیونکہ مرد بہت شرمندہ تھے۔ اور بادشاہ نے کہا، جب تک تمہاری داڑھیاں اگ نہ جائیں، یریحو میں رہو، اور پھر واپس آنا۔\n6۔ اور جب آمون کے بچوں نے دیکھا کہ وہ داؤد کے لیے نفرت انگیز ہو گئے ہیں، تو حنون اور آمون کے بچوں نے ہزاروں چاندی کے ٹیلنٹ بھیجے تاکہ انہیں میسوپوٹیمیا سے، سریماخہ اور زوباہ سے رتھ اور گھڑ سوار کرائے پر لے سکیں۔ {ناپسندیدہ: عبرانی۔ تو اسٹنک}\n7۔ چنانچہ انہوں نے تیس دو ہزار رتھ کرائے پر لیے، اور ماخا کے بادشاہ اور اس کے لوگوں کو بھی؛ جو میڈیبا سے پہلے آئے اور پچنگ کی۔ اور آمون کے بچے اپنے شہروں سے جمع ہوئے اور جنگ کے لیے آئے۔\n8۔ اور جب داؤد نے یہ سنا، تو اس نے یوآب اور طاقتور سپاہیوں کے تمام لشکر کو بھیج دیا۔\n9۔ اور آمون کے بچے باہر آئے، اور شہر کے دروازے کے سامنے جنگ کو ترتیب دیا: اور جو بادشاہ آئے وہ خود میدان میں تھے۔\n10۔ اب جب یوآب نے دیکھا کہ جنگ اس کے سامنے اور پیچھے ہے، تو اس نے اسرائیل کی تمام پسند میں سے انتخاب کیا اور انہیں شامیوں کے خلاف صف میں کھڑا کر دیا۔ {لڑائی...: عبرانی۔ جنگ کا چہرہ تھا} {انتخاب: یا، نوجوانوں}\n11۔ اور باقی لوگوں کو اس نے اپنے بھائی ابیشائی کے ہاتھ میں دے دیا، اور وہ خود کو آمون کے بچوں کے خلاف صف میں کھڑا کر دیا۔ {ابیشائی: عبرانی۔ ابشائی}\n12۔ اور اس نے کہا، اگر سریانی میرے لیے بہت طاقتور ہیں تو تم میری مدد کرو گے، لیکن اگر آمون کے بچے تمہارے لیے بہت طاقتور ہیں تو میں تمہاری مدد کروں گا۔\n13۔ بہادر رہو، اور اپنے لوگوں اور اپنے خدا کے شہروں کے لیے بہادری سے برتاؤ کریں: اور خداوند اپنے سامنے جو اچھا ہے وہ کرے۔\n14۔ یوں یوآب اور اس کے ساتھ موجود لوگ شامیوں کے سامنے جنگ کے لیے قریب آ گئے؛ اور وہ اس کے سامنے بھاگ گئے۔\n15۔ اور جب آمون کے بچوں نے دیکھا کہ شامی بھاگ گئے ہیں، تو وہ بھی اپنے بھائی ابیشائی کے سامنے بھاگے اور شہر میں داخل ہو گئے۔ پھر یوآب یروشلم آیا۔\n16۔ اور جب شامیوں نے دیکھا کہ وہ اسرائیل کے سامنے بدترین حالت میں ہیں، تو انہوں نے پیغامبر بھیجے اور ان شامیوں کو باہر نکالا جو دریا کے پار تھے: اور شافاخ، ہدارزر کی فوج کا کپتان، ان کے سامنے گیا۔ {دریا: یعنی، فرات ہے} {شوفاچ: جسے شوباخ بھی کہا جاتا ہے}\n17۔ اور کہا گیا کہ ڈیوڈ؛ اور اس نے تمام اسرائیل کو جمع کیا، اردن کے پار سے گزرا، اور ان پر پہنچا، اور ان کے خلاف جنگ ترتیب دی۔ تو جب داؤد نے شامیوں کے خلاف جنگ ترتیب دی، تو وہ اس کے ساتھ لڑے۔\n18۔ لیکن شامی اسرائیل کے سامنے فرار ہو گئے؛ اور داؤد نے شامیوں میں سے سات ہزار {جو رتھوں میں لڑتے تھے' اور چالیس ہزار پیادہ کو مار ڈالا، اور فوج کے کپتان شوفاخ کو قتل کر دیا۔\n19۔ اور جب حداریزر کے خادموں نے دیکھا کہ وہ اسرائیل کے سامنے بدتر ہو گئے ہیں، تو انہوں نے داؤد سے صلح کر لی اور اس کے خادم بن گئے: نہ ہی شامی اب عمون کے بچوں کی مدد کریں گے۔","1۔ اور ایسا ہوا کہ سال ختم ہونے کے بعد، جب بادشاہ جنگ کے لیے نکلتے ہیں، یوآب نے فوج کی طاقت کو آگے بڑھایا، اور آمون کے بچوں کے ملک کو تباہ کر دیا، اور آ کر رباح کا محاصرہ کر لیا۔ لیکن داؤد یروشلم میں رکا رہا۔ اور یوآب نے ربع کو مارا اور اسے تباہ کر دیا۔ {بعد...: عبرانی۔ سال کی واپسی پر}\n2۔ اور داؤد نے اپنے بادشاہ کا تاج اپنے سر سے اتارا، اور دیکھا کہ اس کا وزن سونے کا ایک ٹیلنٹ ہے، اور اس میں قیمتی پتھر تھے؛ اور یہ داؤد کے سر پر لگا دیا گیا: اور اس نے شہر سے بہت زیادہ مال غنیمت بھی نکالا۔ {وزن کرنے کے لیے: عببرانی۔ وزن کا وزن}\n3۔ اور اس نے ان لوگوں کو باہر نکالا جو اس میں تھے، اور انہیں آریوں، لوہے کے کانٹوں اور کلہاڑیوں سے کاٹا۔ اسی طرح داؤد نے آمون کے تمام بچوں کے شہروں کے ساتھ معاملہ کیا۔ اور داؤد اور تمام لوگ یروشلم واپس آ گئے۔\n4۔ اور اس کے بعد ایسا ہوا کہ گیزر میں فلسطینیوں کے ساتھ جنگ چھڑ گئی؛ اسی وقت سیببے چائی ہوشاتی نے سپائی کو قتل کر دیا، جو دیو کے بچوں میں سے تھا: اور وہ مغلوب ہو گئے۔ {ابھر: یا، جاری: عبرانی کھڑا تھا} {گیزر: جسے گوب بھی کہا جاتا ہے} {سیپائی: جسے سف بھی کہا جاتا ہے} {دیو: یا، رافا}\n5۔ اور پھر فلسطینیوں کے ساتھ دوبارہ جنگ ہوئی؛ اور الہانان، جو یائر کا بیٹا تھا، نے لحمی کو قتل کیا، جو گولیات دی گٹائٹ کا بھائی تھا، جس کا نیزہ چھڑی بننے والے کی بیم کی طرح تھا۔ {جیر: جسے جاریوریگم بھی کہا جاتا ہے}\n6۔ اور پھر گات میں جنگ ہوئی، جہاں ایک {عظیم} قد کا آدمی تھا، جس کی انگلیاں اور پیر {چوڑ] بیس، چھ {ہر ہاتھ پر} اور {ہر پاؤں پر} تھے: اور وہ بھی دیو کا بیٹا تھا۔ {زبردست...: عبرانی۔ ناپ تول} {بیٹا...: عبرانی۔ دیو یا رافا کے ہاں پیدا ہوا}\n7۔ لیکن جب اس نے اسرائیل کی نافرمانی کی، تو شمیعہ داؤد کے بھائی کے بیٹے یوناتھن نے اسے قتل کر دیا۔ {چیلفائڈ: یا، ملامت شدہ} {شمیعہ: جسے شمہ بھی کہا جاتا ہے}\n8۔ یہ گات کے دیو سے پیدا ہوئے؛ اور وہ داؤد کے ہاتھوں اور اس کے خادموں کے ہاتھوں مارے گئے۔","1۔ اور شیطان نے اسرائیل کے خلاف کھڑا ہو کر داؤد کو اسرائیل کی گنتی پر اکسایا۔\n2۔ اور داؤد نے یوآب اور قوم کے حکمرانوں سے کہا، جاؤ، بئر شبع سے حتیٰ کہ دان تک اسرائیل کو گنو؛ اور ان کی تعداد میرے پاس لے آؤ، تاکہ میں جان سکوں۔\n3۔ اور یوآب نے جواب دیا، خداوند اپنے لوگوں کو سو گنا زیادہ بناتا ہے جتنا وہ ہیں: لیکن، میرے رب بادشاہ، کیا وہ سب میرے رب کے بندے نہیں ہیں؟ تو پھر میرے آقا کو یہ چیز کیوں چاہیے؟ وہ اسرائیل میں غیر قانونی داخلے کا سبب کیوں بنے گا؟\n4۔ پھر بھی بادشاہ کا حکم یوآب پر غالب آیا۔ چنانچہ یوآب روانہ ہوا، اور پورے اسرائیل میں گیا، اور یروشلم پہنچا۔\n5۔ اور یوآب نے لوگوں کی تعداد کا مجموعہ داؤد کو دیا۔ اور اسرائیل کے تمام {وہ} ہزار اور ایک لاکھ آدمی تھے جو تلوار نکالتے تھے: اور یہوداہ {تھا} چار لاکھ تیس ہزار آدمی جو تلوار نکالتے تھے۔\n6۔ لیکن لیوی اور بنیامین نے اسے ان میں شمار نہیں کیا: کیونکہ بادشاہ کا کلام یوآب کے لیے ناپسندیدہ تھا۔\n7۔ اور خدا اس چیز سے ناراض تھا؛ اسی لیے اس نے اسرائیل کو شکست دی۔ {اور...: عبرانی۔ اور خداوند کی نظر میں اس چیز کے بارے میں یہ برائی تھی}\n8۔ اور داؤد نے خدا سے کہا، میں نے بہت بڑا گناہ کیا ہے، کیونکہ میں نے یہ کام کیا: لیکن اب، میں تم سے التجا کرتا ہوں، اپنے بندے کی بدکاری کو دور کر دو؛ کیونکہ میں نے بہت بے وقوفی کی ہے۔\n9۔ اور خداوند نے گاد، داؤد کے دیکھنے والے سے کہا،\n10۔ جاؤ اور داؤد کو بتاؤ، کہو، خداوند فرماتا ہے، میں تمہیں تین {چیزیں} پیش کرتا ہوں: ان میں سے ایک کو چنو، تاکہ میں یہ تمہارے لیے کر سکوں۔ {آفر: عبرانی اسٹریچ آؤٹ}\n11۔ تو گاد داؤد کے پاس آیا اور اس سے کہا، خداوند یوں فرماتا ہے، 'چنو...: عبرانی۔ اپنے پاس لے جاؤ}\n12۔ یا تو تین سال کا قحط؛ یا تین مہینے اپنے دشمنوں کے سامنے تباہ ہونے کے لیے، جب تک کہ تمہارے دشمنوں کی تلوار تمہیں پکڑ لے؛ یا پھر تین دن تک خداوند کی تلوار، حتیٰ کہ وبا بھی، زمین میں اور خداوند کا فرشتہ اسرائیل کے تمام ساحلوں کو تباہ کر دے۔ اب اپنے آپ کو مشورہ دو کہ میں اس کے لیے کون سا کلام دوبارہ لاؤں گا جس نے مجھے بھیجا۔\n13۔ اور داؤد نے گاد سے کہا، میں بہت مشکل میں ہوں: اب مجھے خداوند کے ہاتھ میں دے دو؛ کیونکہ اس کی رحمتیں بہت بڑی ہیں: لیکن مجھے انسان کے ہاتھ میں نہ پڑنے دو۔ {بہت عظیم: یا، بہت زیادہ}\n14۔ تو خداوند نے اسرائیل پر وبا بھیجی، اور اسرائیل سے ستر ہزار آدمی آ گئے۔\n15۔ اور خدا نے یروشلم میں ایک فرشتہ بھیجا تاکہ اسے تباہ کر دے: اور جب وہ تباہ کر رہا تھا، خداوند نے دیکھا، اور اس نے اس برائی سے توبہ کی، اور اس فرشتے سے کہا جس نے تباہ کیا، بس کرو، اب اپنا ہاتھ سنبھالو۔ اور خداوند کا فرشتہ اورنان یبوسی کے تھریشنگ فلور کے پاس کھڑا تھا۔ {اورنان: جسے آراونا بھی کہا جاتا ہے}\n16۔ اور داؤد نے اپنی آنکھیں اٹھائیں، اور دیکھا کہ خداوند کا فرشتہ زمین اور آسمان کے درمیان کھڑا ہے، اس کے ہاتھ میں تلوار نکلی ہوئی ہے جو یروشلم کے اوپر پھیلی ہوئی ہے۔ پھر داؤد اور اسرائیل کے بزرگ، جو بور کے کپڑے میں ملبوس تھے، اپنے چہروں پر گر پڑے۔\n17۔ اور داؤد نے خدا سے کہا، {کیا} میں نے لوگوں کو گنے جانے کا حکم نہیں دیا؟ حتیٰ کہ میں ہی ہوں جس نے واقعی گناہ کیا اور برائی کی؛ لیکن {جہاں تک} ان بھیڑوں کا تعلق ہے، انہوں نے کیا کیا ہے؟ میں دعا کرتا ہوں کہ تیرا ہاتھ تھام لے، اے خداوند میرے خدا، مجھ پر اور میرے باپ کے گھر پر ہو؛ لیکن تمہارے لوگوں پر نہیں، تاکہ وہ پریشان ہوں۔\n18۔ پھر خداوند کے فرشتے نے گاد کو حکم دیا کہ وہ داؤد سے کہے، کہ داؤد اوپر جائے، اور اورنان دی یبوسائٹ کے تھریشنگ فلور میں خداوند کے لیے ایک قربان گاہ قائم کرے۔\n19۔ اور داؤد گاد کے کلام پر اوپر گیا، جو اس نے خداوند کے نام پر کہا۔\n20۔ اور اورنان نے پلٹ کر فرشتے کو دیکھا؛ اور اس کے چار بیٹے اس کے ساتھ چھپ گئے۔ اب اورنان گندم کی کوڑی کر رہا تھا۔ {اور اورنان...: یا، جب اورنان نے پیچھے مڑ کر فرشتے کو دیکھا، تو وہ اور اس کے چار بیٹے اس کے ساتھ چھپ گئے}\n21۔ اور جب داؤد اورنان پہنچا، اورنان نے دیکھا اور داؤد کو دیکھا، اور تھریشنگ فلور سے باہر نکلا اور داؤد کے سامنے سجدہ کیا، {اپنی} منہ زمین پر رکھ لیا۔\n22۔ پھر داؤد نے اورنان سے کہا، مجھے اس تھریشنگ فلور کی جگہ عطا فرما، تاکہ میں اس میں خداوند کے لیے ایک قربان گاہ بنا سکوں: تو اسے مجھے پوری قیمت پر عطا کرو تاکہ لوگوں سے وبا کو روکا جا سکے۔ {گرانٹ: عبرانی۔ دیں}\n23۔ اور اورنان نے داؤد سے کہا، اسے اپنے پاس لے لو، اور میرے آقا بادشاہ کو وہ کام کرنے دو جو اس کی نظر میں اچھا ہے: دیکھو، میں تمہیں بیل بھی دوں گا جلانے کی قربانیوں کے لیے، اور لکڑی کے لیے تھریشنگ کے اوزار، اور گوشت کی قربانی کے لیے گندم؛ میں پوری کوشش کرتا ہوں۔\n24۔ اور بادشاہ داؤد نے اورنان سے کہا، نہیں؛ لیکن میں اسے پوری قیمت پر ضرور خریدوں گا: کیونکہ میں وہ چیز نہیں لوں گا جو {ہے} جو {ہے} خداوند کے لیے، اور نہ ہی بغیر قیمت کے جلانے والی قربانیاں پیش کروں گا۔\n25۔ تو داؤد نے اورنان کو اس جگہ کے لیے چھ سو شیکل سونا وزن کے حساب سے دیا۔\n26۔ اور داؤد نے وہاں خداوند کے لیے ایک قربان گاہ بنائی، اور سلائی کی قربانیاں اور صلح کی قربانیاں پیش کیں، اور خداوند سے پکارا؛ اور اس نے اسے آسمان سے آگ کے ذریعے جلائے ہوئے قربان گاہ پر جواب دیا۔\n27۔ اور خداوند نے فرشتے کو حکم دیا؛ اور اس نے اپنی تلوار دوبارہ اس غلاف میں رکھ دی۔\n28۔ اس وقت جب داؤد نے دیکھا کہ خداوند نے اسے اورنان دی یبوسی کے تھریشنگ فلور میں جواب دیا ہے، تو اس نے وہاں قربانی دی۔\n29۔ کیونکہ خداوند کا خیمہ جو موسیٰ نے ویرانے میں بنایا تھا، اور سلائی کی قربان گاہ اس وقت گبعون کے بلند مقام پر تھے۔\n30۔ لیکن داؤد اس کے سامنے جا کر خدا سے پوچھ نہیں سکا: کیونکہ وہ خداوند کے فرشتے کی تلوار سے ڈرتا تھا۔","1۔ پھر داؤد نے کہا، یہ خداوند خدا کا گھر ہے، اور یہ اسرائیل کے لیے جلانے والی قربانی کا قربان گاہ ہے۔\n2۔ اور داؤد نے حکم دیا کہ وہ اجنبیوں کو جمع کریں جو اسرائیل کی سرزمین میں تھے؛ اور انہوں نے مزدوروں کو خدا کے گھر کی تعمیر کے لیے پتھر تراشنے کا حکم دیا۔\n3۔ اور داؤد نے دروازوں کے دروازوں اور جوڑنے کے لیے کیلوں کے لیے لوہا وافر مقدار میں تیار کیا؛ اور پیتل کی وافر مقدار میں بغیر وزن کے؛\n4۔ اسی طرح دیودار کے درخت بھی کثرت سے تھے: کیونکہ زیدونیوں اور صور کے لوگ داؤد کے لیے بہت سا دیودار لکڑی لاتے تھے۔\n5۔ اور داؤد نے کہا، سلیمان میرا بیٹا {ہے} جوان اور نرم دل ہے، اور خداوند کے لیے تعمیر ہونے والا گھر {جو بنایا جائے گا} سب ملکوں میں شہرت اور جلال کا حامل ہونا چاہیے: میں {لہٰذا} اب اس کی تیاری کروں گا۔ لہٰذا داؤد اپنی موت سے پہلے بھرپور تیاری کر رہا تھا۔\n6۔ پھر اس نے اپنے بیٹے سلیمان کو بلایا اور اسے حکم دیا کہ وہ اسرائیل کے خداوند خدا کے لیے ایک گھر تعمیر کرے۔\n7۔ اور داؤد نے سلیمان سے کہا، میرے بیٹے، جہاں تک میرا تعلق ہے، میرے ذہن میں تھا کہ خداوند میرے خدا کے نام پر ایک گھر بناؤں:\n8۔ لیکن خداوند کا کلام میرے پاس آیا، جس میں کہا گیا، تو نے بہت خون بہایا اور بڑی جنگیں کیں: تو میرے نام پر گھر نہیں بناؤ گے، کیونکہ تم نے میرے سامنے زمین پر بہت خون بہایا ہے۔\n9۔ دیکھو، تمہارے لیے ایک بیٹا پیدا ہوگا، جو آرام دہ انسان ہوگا؛ اور میں اسے اس کے آس پاس کے تمام دشمنوں سے سکون دوں گا: کیونکہ اس کا نام سلیمان ہوگا، اور میں اسرائیل کو اس کے زمانے میں سکون اور سکون دوں گا۔ {سلیمان: یعنی، امن پسند}\n10۔ وہ میرے نام کے لیے ایک گھر بنائے گا؛ اور وہ میرا بیٹا ہوگا، اور میں اس کا باپ بن جاؤں گا؛ اور میں ہمیشہ کے لیے اسرائیل پر اس کی سلطنت کا تخت قائم کروں گا۔\n11۔ اب، میرے بیٹے، خداوند تیرے ساتھ ہو؛ اور تو خوشحال ہو، اور خداوند اپنے خدا کے گھر کو تعمیر کرو، جیسا کہ اس نے تمہارے بارے میں کہا۔\n12۔ صرف خداوند تمہیں حکمت اور سمجھ دے، اور تمہیں اسرائیل کے بارے میں حکم دے، تاکہ تم خداوند اپنے خدا کے قانون کی پاسداری کرو۔\n13۔ تو اگر تم ان قوانین اور احکام کی تکمیل کرو جو خداوند نے موسیٰ کو اسرائیل کے بارے میں سونپے ہیں، تو تم کامیاب رہو گے: مضبوط اور بہادر رہو؛ نہ ڈرو، نہ ہی مایوس ہو۔\n14۔ اب، دیکھو، اپنی پریشانی میں میں نے خداوند کے گھر کے لیے ایک لاکھ ٹیلنٹ سونا اور ہزار ہزار ٹیلنٹ چاندی تیار کی ہے؛ اور بغیر وزن کے پیتل اور لوہے کے؛ کیونکہ یہ وافر مقدار میں ہے: میں نے لکڑی اور پتھر بھی تیار کیے ہیں؛ اور تم اس میں اضافہ کر سکتے ہو۔ {مسئلہ: یا، غربت}\n15۔ مزید برآں آپ کے ساتھ مزدور کثرت سے ہیں، پتھر اور لکڑی کے کاٹنے والے اور مزدور، اور ہر قسم کے چالاک لوگ ہر قسم کے کام کے لیے موجود ہیں۔ {مزدور...: یعنی معمار اور بڑھئی}\n16۔ سونے، چاندی، پیتل، اور لوہے کی کوئی تعداد نہیں۔ لہٰذا اٹھو، اور عمل کرو، اور خداوند تمہارے ساتھ ہو۔\n17۔ داؤد نے اسرائیل کے تمام شہزادوں کو حکم دیا کہ وہ اپنے بیٹے سلیمان کی مدد کریں، {کہا}،\n18. کیا خداوند تمہارا خدا تمہارے ساتھ نہیں ہے؟ اور کیا اس نے تمہیں ہر طرف آرام نہیں دیا؟ کیونکہ اس نے زمین کے باشندوں کو میرے ہاتھ میں دے دیا ہے؛ اور زمین خداوند کے سامنے اور اس کے لوگوں کے سامنے زیر کر دی جاتی ہے۔\n19۔ اب اپنا دل اور جان لگا کر خداوند اپنے خدا کی تلاش کرو؛ لہٰذا اٹھو، اور خداوند خدا کے مقدس مقام کو تعمیر کرو، تاکہ خداوند کے عہد کا صندوق اور خدا کے مقدس برتن اس گھر میں لے آئیں جو خداوند کے نام پر تعمیر کیا جائے گا۔","1۔ جب داؤد بوڑھا اور دنوں سے بھرپور ہوا، تو اس نے اپنے بیٹے سلیمان کو اسرائیل کا بادشاہ بنایا۔\n2۔ اور اس نے اسرائیل کے تمام شہزادوں، کاہنوں اور لاویوں کے ساتھ جمع کیا۔\n3۔ اب لاویوں کی تعداد تیس سال کی عمر سے لے کر اس سے اوپر گنے گئی: اور ان کی تعداد ان کے پولوں کے حساب سے، مرد بہ آدمی، تیس آٹھ ہزار تھی۔\n4۔ جن میں سے چوبیس ہزار خداوند کے گھر کے کام کو آگے بڑھانے کے لیے تھے؛ اور چھ ہزار {تھے} افسران اور جج: {مقرر...: یا، نگرانی}\n5. مزید یہ کہ چار ہزار قلی تھے؛ اور چار ہزار نے خداوند کی تعریف ان آلات سے کی جو میں نے بنائیں، {داؤد نے کہا}، تاکہ {اس کے ساتھ} تعریف کی جا سکے۔\n6۔ اور داؤد نے انہیں لاوی کے بیٹوں میں تقسیم کیا، یعنی گرشون، کوحات اور مراری۔ {کورسز: عبرانی۔ تقسیم}\n7۔ گرشونائیوں میں سے {تھے}، لعدن، اور شیمئی۔ {لادان: یا، لبنی}\n8۔ لادان کے بیٹے؛ چیف {تھا} جہیل، زیتھم، اور جوئل تین سال کا۔\n9۔ شیمئی کے بیٹے؛ شیلومیت، اور ہازیئل، اور ہاران، تین۔ یہ {تھے} لادان کے بزرگوں کے سردار۔\n10۔ اور شمعی کے بیٹے تھے، جہات، زینا، یسوع، اور بریہ۔ یہ چاروں شیمئی کے بیٹے تھے۔ {زینا: یا، زیزہ}\n11۔ اور جہات سردار تھا، اور زیزہ دوسرا: لیکن یسوع اور بریاہ کے زیادہ بیٹے نہیں تھے؛ لہٰذا وہ ایک ہی حساب میں تھے، جیسا کہ ان کے والد کے گھر کے مطابق تھا۔ {تھا...: عبرانی بیٹوں کی تعداد نہیں کی}\n12۔ کوہات کے بیٹے؛ امرام، اظہار، حبرون، اور عزیل، چار۔\n13۔ امرام کے بیٹے؛ ہارون اور موسیٰ: اور ہارون جدا ہو گیا، تاکہ وہ اور اس کے بیٹے سب سے مقدس چیزوں کو ہمیشہ کے لیے پاک کرے، خداوند کے سامنے لوبان جلائے، اس کی خدمت کرے، اور ہمیشہ کے لیے اس کے نام پر برکت دے۔\n14۔ اب موسیٰ خدا کے آدمی کے بارے میں، اس کے بیٹوں کو لاوی قبیلے سے نامزد کیا گیا۔\n15۔ موسیٰ کے بیٹے {تھے}، گرشوم، اور ایلیعزر۔\n16۔ گرشوم کے بیٹوں میں سے، شیبویل {تھا} سردار۔ {شبوئل: جسے شوبیل بھی کہا جاتا ہے}\n17۔ اور الیعزر کے بیٹے، ریحبیاہ سردار تھے۔ اور ایلیزر کے اور کوئی بیٹے نہیں تھے؛ لیکن رحبیہ کے بیٹے بہت زیادہ تھے۔ {چیف: یا، پہلا} {بہت زیادہ: عبرانی۔ انتہائی ضرب شدہ}\n18۔ ازہر کے بیٹوں سے؛ شیلومتھ دی چیف۔ {شیلومتھ: جسے شیلوموتھ بھی کہا جاتا ہے}\n19۔ حبرون کے بیٹوں سے؛ یریاہ پہلا، امریاہ دوسرے، جہزیئل تیسرا، اور جیکمیم چوتھا۔\n20۔ عزیل کے بیٹوں سے؛ میخا پہلا، اور جیسیاہ دوسرا۔\n21۔ مراری کے بیٹے؛ مہلی، اور مشی۔ مہلی کے بیٹے؛ الیعزر، اور کش۔\n22۔ اور الیعازر مر گیا، اس کے بیٹے نہیں ہوئے، صرف بیٹیاں تھیں: اور ان کے بھائیوں نے کیش کے بیٹوں کو لے لیا۔ {بھائیو: یا، رشتہ دار}\n23۔ موشی کے بیٹے؛ مہلی، ایڈر، اور جیریموتھ تین سال۔\n24. یہ لاوی کے بیٹے تھے جو ان کے باپ و اجداد کے گھر کے بعد تھے؛ {حتیٰ کہ} باپوں میں سے سردار، کیونکہ ان کے پولز کے مطابق ناموں کی تعداد سے گنا جاتا تھا، جو بیس سال کی عمر سے لے کر اس سے اوپر خداوند کے گھر کی خدمت کے لیے کام کرتے تھے۔\n25۔ کیونکہ داؤد نے فرمایا، خداوند اسرائیل کے خدا نے اپنے لوگوں کو سکون دیا ہے تاکہ وہ ہمیشہ یروشلم میں رہیں: {کہ...: یا، اور وہ یروشلم میں رہتا ہے، وغیرہ}\n26۔ اور لاویوں کے لیے بھی؛ وہ اب تک خیمہ گاہ یا اس کی کوئی برتن اس کی خدمت کے لیے نہیں لے جا سکیں گے۔\n27۔ کیونکہ داؤد کے آخری الفاظ کے مطابق لاویوں کو بیس سال اور اس سے زیادہ عمر سے نمبر دیا گیا: {نمبر: عبرانی۔ نمبر}\n28۔ کیونکہ ان کا کام ہارون کے بیٹوں کی خدمت کے لیے تھا، عدالتوں میں، اور کمروں میں، تمام مقدس چیزوں کی تطہیر کے لیے، اور خدا کے گھر کی خدمت کے کام کے لیے؛ {ان کے...: عبرانی۔ ان کا مقام ہارون کے بیٹوں کے ہاتھوں تھا}\n29۔ شوبریڈ کے لیے، اور گوشت کی نذری نذری عمدہ آٹے، بغیر خمیر کے کیک کے لیے، اور جو پین میں بیک کیا جاتا ہے، اور جو تلا جاتا ہے، اور ہر قسم کی پیمائش اور سائز کے لیے؛ {پین: یا، فلیٹ پلیٹ}\n30۔ اور ہر صبح کھڑے ہو کر خدا کا شکر ادا کرنا اور اس کی تعریف کرنا، اور اسی طرح برابر وقت پر؛\n31۔ اور خداوند کو سبت کے دنوں، نئے چاند پر، اور مقررہ تہواروں پر، تعداد کے حساب سے، ان کے حکم کے مطابق، خداوند کے سامنے مسلسل تمام جلی ہوئی قربانیاں پیش کرنا:\n32۔ اور کہ وہ جماعت کے خیمے کی ذمہ داری، مقدس {مقام} کی ذمہ داری، اور اپنے بھائیوں ہارون کے بیٹوں کی ذمہ داری خداوند کے گھر کی خدمت میں رکھیں۔","1. اب {یہ ہیں} ہارون کے بیٹوں کی تقسیمیں۔ ہارون کے بیٹے؛ ناداب، اور ابیہو، الیعازر، اور ایثمار۔\n2۔ لیکن نداب اور ابیہو اپنے والد سے پہلے فوت ہو گئے، اور ان کے کوئی اولاد نہ ہوئی: لہٰذا الیعزر اور ایثمار نے پادری کے عہدے کو قتل کر دیا۔\n3۔ اور داؤد نے انہیں تقسیم کیا، دونوں الیعزر کے بیٹوں کے صادوق اور ایثمار کے بیٹوں کے احیملک، ان کی خدمت کے عہدوں کے مطابق۔\n4۔ اور الیعزر کے بیٹوں میں اتمار کے بیٹوں سے زیادہ سردار پائے گئے؛ اور {یوں} وہ تقسیم ہو گئے۔ الیعزر کے بیٹوں میں {ان} کے آباؤ اجداد کے گھر کے سولہ سردار تھے، اور ایتھامار کے بیٹوں میں آٹھ ان کے باپ و اجداد کے خاندان کے مطابق تھے۔\n5۔ یوں انہیں قرعہ اندازی کے ذریعے تقسیم کیا گیا، ایک قسم کے ساتھ دوسرا؛ کیونکہ مقدس مقام کے گورنرز اور خدا کے گھرانے کے گورنرز الیعازر کے بیٹوں اور ایثمار کے بیٹوں کے تھے۔\n6۔ اور شمعیہ، نیتھانیئل کاتب کا بیٹا، لاویوں میں سے ایک، نے انہیں بادشاہ، شہزادوں، زادوک کاہن کے سامنے، اور ابیثار کے بیٹے احیمیلک کے سامنے لکھا، اور {پہلے} کاہنوں اور لاویوں کے باپوں کے سردار کے سامنے لکھا: ایک اہم گھرانہ الیعزر کے لیے لیا گیا، اور {ایک} ایتھامار کے لیے۔ {پرنسپل...: عبرانی۔ باپ کا گھر}\n7۔ اب پہلا قرعہ یہویاریرب کے پاس آیا، دوسرا جدایہ کے لیے،\n8۔ تیسرا ہارم کو، چوتھا سیوریم کو،\n9۔ پانچواں ملکیجہ کو، چھٹا میامین کو،\n10۔ ساتواں حکوز کو، آٹھواں ابیجہ کو،\n11۔ نویں یشوع کو، دسواں شکنیاہ کو،\n12۔ گیارہواں ایلیاشیب کو، بارہواں جاکیم کو،\n13۔ تیرہواں ہوپا کو، چودہواں یشیبیاب کو،\n14۔ پندرہواں بلگاہ کو، سولہواں ایمر کو،\n15۔ سترہواں حزیر کو، اٹھارہواں افسس کو،\n16۔ انیسواں پیتھاحیاہ کو، بیسواں یہزقیل کو،\n17۔ ایک اور بیسواں جاچن کو، دو اور بیسواں گامول کو،\n18۔ تیسویں اور بیسویں دلیہ کو، چارہ بیسویں معزیہ کو۔\n19. یہ وہ احکامات تھے جو انہوں نے اپنی خدمت میں خداوند کے گھر میں اپنے انداز کے مطابق اپنے باپ ہارون کے تحت آئے، جیسا کہ اسرائیل کے خداوند خدا نے اسے حکم دیا تھا۔\n20۔ اور لاوی کے باقی بیٹے {یہ تھے}: عمرم کے بیٹوں کے؛ شباعیل: شبیل کے بیٹوں سے؛ جہدیہ۔ {شبائیل: جسے شبوئل بھی کہا جاتا ہے}\n21۔ رحبیہ کے بارے میں: رحبیہ کے بیٹوں میں سے پہلا {تھا} ایشیہ۔\n22۔ ازھاریوں کی؛ شیلوموتھ: شیلوموتھ کے بیٹوں سے؛ جہاتھ۔ {شیلوموت: جسے شیلومتھ بھی کہا جاتا ہے}\n23۔ اور حبرون کے بیٹے؛ یریاہ {پہلا}، امریاہ دوم، جہازئیل تیسرا، جیکمیم چوتھا۔\n24۔ عزیل کے بیٹے؛ میخا: میخا کے بیٹوں سے؛ شامیر۔\n25. میخا کے بھائی {تھا} ایشیہ کے بیٹوں میں؛ زکریا۔\n26۔ مراری کے بیٹے ماہلی اور موشی تھے: جازیہ کے بیٹے؛ بینو۔\n27۔ یازیاہ کے مراری کے بیٹے؛ بینو، اور شوہام، اور زکر، اور ایبری۔\n28۔ مہلی سے {آیا} الیعازر، جس کے کوئی بیٹے نہیں تھے۔\n29۔ کیش کے بارے میں: کیش کا بیٹا رحمیل تھا۔\n30۔ موشی کے بیٹے بھی؛ مہلی، ایڈر، اور جیریموتھ۔ یہ لاویوں کے بیٹے تھے جو ان کے باپ و اجداد کے گھر کے بعد تھے۔\n31۔ اسی طرح انہوں نے اپنے بھائیوں کے خلاف قرعہ اندازی کی، جو ہارون کے بیٹوں تھے، جو داؤد بادشاہ، زادوق، اور احیملیک کی موجودگی میں تھے، اور کاہنوں اور لاویوں کے باپوں میں سے سردار، حتیٰ کہ اہم باپوں کے خلاف بھی اپنے چھوٹے بھائیوں کے خلاف۔","1۔ مزید برآں، داؤد اور فوج کے کپتان آساف، ہیمان، اور یدوتھن کے بیٹوں کی خدمت میں تقسیم ہو گئے، جو ہارپ، زبور اور جھنجھن کے ذریعے پیش گوئی کرتے تھے: اور مزدوروں کی تعداد ان کی خدمت کے مطابق یہ تھی:\n2۔ آساف کے بیٹوں سے؛ زکور، اور یوسف، اور نیثانیا، اور اسارلہ، جو آساف کے بیٹے تھے، اور بادشاہ کے حکم کے مطابق پیش گوئی کی گئی تھی۔ {اسارلہ: جسے یشارلہ بھی کہا جاتا ہے} {مطابق...: عبرانی بادشاہ کے ہاتھوں سے}\n3۔ جدوتون کے بیٹے: جیدوتون کے بیٹے؛ گیدلیہ، اور زری، اور یشاعیا، حشبیاہ، اور متیتیا، چھ سال کے، اپنے والد یدوتون کے ہاتھوں میں، جس نے ہارپ کے ساتھ پیش گوئی کی تھی، کہ وہ خداوند کا شکر ادا کرے اور تعریف کرے۔ {زیری: یا، ازری}\n4۔ ہیمان کے: ہیمان کے بیٹے؛ بوکیاہ، متانیا، عزئیل، شیبوئیل، اور یریموتھ، حنانیہ، حنانی، ایلیاتاہ، گدلتی، اور رومتیزر، یوشبکاشاہ، مالوتی، ہوتیر، {اور} مہازیوت: {عزئیل: جسے عزریل بھی کہا جاتا ہے} {شبویل: جسے شوبیل بھی کہا جاتا ہے}\n5۔ یہ سب خدا کے الفاظ میں ہیمان بادشاہ کے غیب گو کے بیٹے تھے، تاکہ سینگ اٹھا سکے۔ اور خدا نے ہیمن کو چودہ بیٹے اور تین بیٹیاں عطا کیں۔ {الفاظ: یا، اہمیت رکھتا ہے}\n6۔ یہ سب ان کے والد کے ہاتھوں گیت کے لیے خداوند کے گھر میں، سنبلز، زبور اور ہارپ کے ساتھ، خدا کے گھر کی خدمت کے لیے، بادشاہ کے حکم کے مطابق آصاف، یدوتون اور ہیمان کو۔ {مطابق...: عبرانی بادشاہ کے ہاتھوں سے}\n7۔ تو ان کی تعداد، اپنے بھائیوں کے ساتھ جنہیں خداوند کے گیتوں میں تعلیم دی گئی تھی، {حتیٰ کہ} تمام چالاک بھی، دو سو چوبیس آٹھ تھی۔\n8۔ اور وہ قرعہ اندازی کرتے ہیں، {وارڈ} کے خلاف، چھوٹے اور بڑے کے خلاف بھی، استاد کو عالم کے طور پر۔\n9۔ اب پہلا قرعہ یوسف کے لیے آصاف کے لیے آیا: دوسرا قرعہ جدلیاہ کو، جو اپنے بھائیوں اور بیٹوں کے ساتھ بارہ تھے:\n10۔ تیسرا زکور، {وہ}، اس کے بیٹے، اور اس کے بھائیوں کے لیے، {تھے} بارہ:\n11۔ چوتھا ازری سے، {وہ}، اس کے بیٹے، اور اس کے بھائیوں کے بارہ تھے:\n12۔ پانچواں نتھانیا سے، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n13۔ چھٹا بکیاہ سے، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n14۔ ساتواں یشارلہ سے، {و}، اس کے بیٹے، اور اس کے بھائیوں {تھے} بارہ تھے:\n15۔ یشاعیاہ کے لیے آٹھواں ہے، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n16۔ متانیاہ کے لیے نویں، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n17۔ دسواں شیمئی کو، {وہ}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n18۔ گیارہواں ازریئل، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\nانیس۔ بارہویں حشبیاہ کو، {وہ}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n20۔ تیرہواں شبیل کے لیے، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n21۔ چودھویں متیتھا کو، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n22۔ پندرہواں جیریموت کو، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n23۔ سولہواں حنانیاہ کو، {و}، اس کے بیٹے، اور اس کے بھائیوں {تھے} بارہ تھے:\n24۔ سترہواں، یوشبکاشہ کو، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n25۔ اٹھارہویں حنانی کو، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n26۔ مالوتی کے لیے انیسویں، {وہ}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n27۔ بیسواں الیاتھا کو، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\nاٹھائیس۔ ہوتیر کے لیے ایک اور بیسویں، {وہ}، اس کے بیٹے، اور اس کے بھائی، بارہ تھے:\n29۔ گدالتی کے دو اور بیسویں، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n30۔ مہازیوتھ کے تین اور بیسویں، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ:\n31۔ رومتیزر کے چار اور بیسویں کے لیے، {و}، اس کے بیٹے، اور اس کے بھائی، {تھے} بارہ۔","1۔ دربانوں کی تقسیمات کے بارے میں: کورھیوں کا {تھا} مشلیمیاہ کورے کا بیٹا، جو آصف کے بیٹوں کا تھا۔ {میشلیمیاہ: جسے شیلیمیاہ بھی کہا جاتا ہے} {آساف: جسے ایبیاساف بھی کہا جاتا ہے}\n2۔ اور مشلیمیاہ کے بیٹے تھے، زکریا پہلا بیٹا، یدیعیل دوسرے، زبادیا تیسرا، یثنیئل چوتھا،\n3۔ ایلام پانچویں، یہوحانان چھٹاں، ایلیوئنائی ساتواں\n4. مزید برآں، اوبیدوم کے بیٹے تھے، شمعیاہ پہلا بیٹا، یہوزاباد دوم، جوح تیسرا، سکار چوتھام، اور نیتھانیل پانچواں،\n5۔ امیئیل چھٹا، اسکار ساتواں، پیلتھائی آٹھواں: کیونکہ خدا نے اسے برکت دی۔ {وہ: یعنی، اوبیدیڈوم}\n6۔ شمعیاہ کے بیٹے بھی پیدا ہوئے، جو اپنے باپ کے گھرانے میں حکمرانی کرتے رہے: کیونکہ وہ بہادر اور طاقتور لوگ تھے۔\n7۔ شمعیاہ کے بیٹے؛ اوثنی، اور ریفائیل، اور عوبید، الزآباد، جن کے بھائی طاقتور تھے، ایلیہو، اور سماخاہ۔\n8۔ اوبیڈوم کے تمام بیٹے: وہ، ان کے بیٹے اور ان کے بھائی، جو خدمت کے لیے طاقت کے قابل تھے، تین سو اور دو اوبیدیڈوم کے تھے۔\n9۔ اور مشلیمیاہ کے بیٹے اور بھائی تھے، مضبوط آدمی، اٹھارہ سال کے۔\n10۔ مراری کے بچوں میں سے ہوساہ کے بیٹے تھے؛ سمری سردار تھا، (کیونکہ {اگرچہ} وہ پہلا اولاد نہیں تھا، پھر بھی اس کے والد نے اسے سردار بنایا؛)\n11۔ حلقیاہ دوسرے، تبالیاہ تیسرا، زکریا چوتھے: ہوساہ کے تمام بیٹے اور بھائی تیرہ سال کے تھے۔\n12۔ ان میں قلیوں کی تقسیمات شامل تھیں، حتیٰ کہ سردار حضرات میں بھی، جو ایک دوسرے کے خلاف کھڑے تھے، تاکہ خداوند کے گھر میں خدمت کریں۔\n13۔ اور انہوں نے اپنے آباؤ اجداد کے گھر کے مطابق چھوٹے اور بڑے دونوں طرح کے ہر دروازے کے لیے قرعہ ڈالے۔ {اور بھی...: یا، چھوٹے کے لیے بھی جتنا بڑے کے لیے}\n14۔ اور مشرق کی طرف زمین شیلمیاہ کے قبضے میں آ گئی۔ پھر زکریا کے بیٹے کے لیے، جو ایک دانا مشیر تھا، نے قرعہ اندازی کی؛ اور اس کا گروہ شمال کی طرف نکلا۔ {شلیمیاہ: جسے مشلیمیاہ بھی کہا جاتا ہے}\n15۔ اوبیڈیڈوم جنوب کی طرف؛ اور اپنے بیٹوں کو آسوپیم کا گھر۔ {Asuppim: عبوری۔ اجتماعات}\n16۔ شوپیم اور ہوساہ کی طرف {وہ پلاٹ مغرب کی طرف آیا}، شالچتھ کے دروازے کے ساتھ، اوپر جانے کے راستے پر، حفاظتی دیوار کے خلاف کھڑے ہوئے۔\n17۔ مشرق کی طرف چھ لاوی تھے، شمال کی طرف روزانہ چار، روزانہ چار جنوب کی طرف، اور اسوپیم کی طرف دو اور دو۔\n18۔ پاربار پر مغرب کی طرف، چار کاز وے پر، {اور} دو پاربار پر۔\n19۔ یہ وہ تقسیم ہیں جو کورے کے بیٹوں اور میراری کے بیٹوں کے درمیان پورٹرز کی تقسیم ہیں۔\n20۔ اور لاویوں میں، اخیاہ خدا کے گھر کے خزانے اور وقف شدہ چیزوں کے خزانے پر تھا۔ {وقف کیا گیا...: عببرانی۔ مقدس باتیں}\n21۔ {جہاں تک تعلق ہے} لادان کے بیٹے؛ گرشونائٹ لادان کے بیٹے، جو لادان گرشونائٹ کے بڑے باپ، {حتی} تھے، {تھے} جہیلی۔ {لادان: جسے لبنی بھی کہا جاتا ہے} {جہیلی: جسے جہیل بھی کہا جاتا ہے}\n22۔ جہیلی کے بیٹے؛ زیتھم، اور اس کا بھائی یوئیل، {جو خدا کے گھر کے خزانے تھے}۔\n23۔ امرامی، {اور} ازہاریوں، حبرونیوں، {اور} عزیلائیوں میں:\n24۔ اور شیبویل، گرشوم کا بیٹا، موسیٰ کا بیٹا، خزانے کا حکمران تھا۔\n25۔ اور اس کے بھائی الیعزر کے ذریعے؛ رحبیاہ اس کا بیٹا، اور یشعیاہ اس کا بیٹا، اور یورام اس کا بیٹا، زکری اس کا بیٹا، اور شلومیت اس کا بیٹا۔\n26۔ جو شلومتھ اور اس کے بھائیوں کے پاس وقف شدہ چیزوں کے خزانے تھے، جو داؤد بادشاہ، بڑے بزرگوں، ہزاروں اور سینکڑوں کے کپتانوں، اور لشکر کے کپتانوں نے وقف کیے تھے۔\n27۔ جنگوں میں حاصل شدہ مال غنیمت میں سے انہوں نے خداوند کے گھر کی حفاظت کے لیے وقف کیا۔ {سپائلز...: عببرانی۔ لڑائیاں اور غنیمت}\n28۔ اور وہ سب کچھ جو ساموئیل دیکھنے والا، ساؤل کیش کا بیٹا، ابنر نیر کا بیٹا، اور یوآب زرویاہ کا بیٹا وقف کیا تھا؛ {اور} جس نے {کچھ بھی وقف کیا} شیلومیت اور اس کے بھائیوں کے ہاتھ میں۔\n29۔ ازھاریوں میں، چنانیاہ اور اس کے بیٹے اسرائیل کے بیرونی کاروبار، افسران اور ججوں کے لیے تھے۔\n30۔ {اور} ہبرونیوں میں سے، حشبیہ اور اس کے بھائی، بہادر لوگ، ایک ہزار سات سو، ان میں اس طرف اردن کے مغرب میں اسرائیل کے افسران تھے، خداوند کے تمام کاموں میں اور بادشاہ کی خدمت میں۔ {افسران...: عببرانی۔ چارج کے اوپر}\n31۔ ہیبرونیوں میں {تھا} یرییاہ سردار تھا، {حتی} حبرونیوں میں بھی، جیسا کہ اس کے آباؤ اجداد کی نسلوں کے مطابق۔ داؤد کی حکومت کے چالیسویں سال میں انہیں تلاش کیا گیا، اور ان میں سے عظیم بہادر لوگ یزر آف گیلعاد میں ملے۔\n32۔ اور اس کے بھائی، بہادر لوگ، دو ہزار سات سو سردار باپ تھے، جنہیں بادشاہ داؤد نے روبینیوں، گادیوں، اور مناسی کے آدھے قبیلے پر حکمران بنایا، خدا سے متعلق ہر معاملہ اور بادشاہ کے معاملات کے لیے۔ {معاملات: عبرانی۔ چیز}","1۔ اب بنی اسرائیل ان کی تعداد کے مطابق، ہزاروں اور سینکڑوں کے سردار اور کپتان، اور ان کے افسران جو بادشاہ کی خدمت کرتے تھے، جو سال کے تمام مہینوں میں مہینے بہ ماہ آتے اور جاتے تھے، ہر کورس کی تعداد بیس چار ہزار تھی۔\n2۔ پہلے مہینے کے پہلے کورس میں {تھا} جاشوبیم، زبدیل کا بیٹا: اور اس کے سفر میں {تھے} بیس اور چار ہزار۔\n3۔ پیریز کے بچوں میں سے وہ پہلے مہینے کے لیے میزبان کے تمام کپتانوں کا سربراہ تھا۔\n4۔ اور دوسرے مہینے کے دوران {تھا} دودائی ایک اہوہائٹ، اور اس کے دور میں {تھا} مکلوت بھی حکمران تھا: اس کے دور میں بھی بیس چار ہزار تھے۔ {ڈودائی: جسے ڈوڈو بھی کہا جاتا ہے}\n5۔ تیسرے مہینے کے لیے لشکر کا تیسرا کپتان بنیاہ تھا، جو یہویادا کا بیٹا تھا، ایک سردار کاہن تھا: اور اس کے دور میں اس کی تعداد بیس چار ہزار تھی۔ {چیف...: یا، پرنسپل آفیسر}\n6. یہ {وہ} بنایاہ ہے، {جو} تیس میں طاقتور تھا، اور تیس سے اوپر: اور اس کے راستے میں {تھا} امیز آباد اس کا بیٹا۔\n7۔ چوتھا {کپتان} چوتھے مہینے {تھا} عساہیل جو یوآب کا بھائی تھا، اور اس کے بعد اس کا بیٹا زبادیہ: اور اس کے دور میں {تھا} بیس چار ہزار۔\n8۔ پانچویں مہینے کا پانچواں کپتان {تھا} شمحوت ازراہائی: اور اس کے دور میں {تھے} بیس اور چار ہزار۔\n9۔ چھٹے مہینے کے لیے چھٹا {کپتان} ایرا تھا، جو اکیش دی ٹیکوئیٹ کا بیٹا تھا: اور اس کے دور میں بیس چار ہزار تھے۔\n10۔ ساتویں {کپتان} ساتویں مہینے {تھا} ہیلیز دی پیلونائٹ، افرائیم کے بچوں میں سے: اور اس کے سفر میں وہ بیس اور چار ہزار تھے۔\n11۔ آٹھویں {کپتان} آٹھویں مہینے کے لیے {تھا} سبیکائی ہوشاطی، زرہیوں کا: اور اس کے دور میں {تھے} بیس چار ہزار۔\n12۔ نویں {کپتان} نویں مہینے کے لیے {تھا} ابیزر انیتوتھیائی، بنیمی خاندان سے: اور اس کے دور میں بیس اور چار ہزار تھے۔\n13۔ دسویں مہینے کے لیے دسویں {کپتان} مہارائی نیتوفاتھی، زرہیوں کا تھا: اور اس کے دور میں بیس اور چار ہزار تھے۔\n14۔ گیارہویں مہینے کے لیے گیارہواں {کپتان} بنایاہ پیراتھونی، افرائیم کے بچوں میں سے تھا: اور اس کے دور میں بیس چار ہزار تھے۔\n15۔ بارہویں {کپتان} بارہویں مہینے {تھا} ہیلڈائی نیتوفاتھی، اوتھنیئل کا؛ اور اس کے سفر میں اس کی تعداد بیس اور چار ہزار تھی۔ {ہیلڈائی: جسے ہیلید بھی کہا جاتا ہے}\n16۔ مزید یہ کہ اسرائیل کے قبائل پر: روبینیوں کا حکمران {تھا} الیعزر جو زکری کا بیٹا تھا: شمیعونیوں کا، شیفطیہ ماخہ کا بیٹا:\n17۔ لاویوں سے، حشبیاہ کموئیل کا بیٹا: آرونیوں کا، زادوک:\n18۔ یہوداہ کے، ایلیہو، {ایک} داؤد کے بھائیوں میں سے: یساکر کا، عمری مائیکل کا بیٹا: {ایلیہو: جسے ایلیاب بھی کہا جاتا ہے}\n19۔ زبولون کی، اشمایا عوبدیہ کا بیٹا: نفتالی کا، یریموت عزرییل کا بیٹا:\n20۔ افرائیم کے بچوں سے، ہوشع جو عززیہ کا بیٹا تھا: منسی کے آدھے قبیلے سے، یوئیل پیدعیاہ کا بیٹا:\n21۔ گلعاد میں مناسی کے آدھے قبیلے سے، زکریا کا بیٹا ایدو: بنیامین کا، یاسیئل ابنر کا بیٹا:\n22۔ دان کا، عزریئل یروہام کا بیٹا۔ یہ {تھے} اسرائیل کے قبائل کے شہزادے۔\n23۔ لیکن داؤد نے ان کی تعداد بیس سال اور اس سے کم عمر سے نہیں لی، کیونکہ خداوند نے کہا تھا کہ وہ اسرائیل کو آسمانوں کے ستاروں کی طرح بڑھائے گا۔\n24۔ زرویاہ کے بیٹے یوآب کی تعداد بڑھنے لگی، لیکن وہ مکمل نہ ہوا، کیونکہ اس پر اسرائیل پر غصہ آیا؛ نہ ہی بادشاہ داؤد کی تواریخ میں یہ نمبر درج کیا گیا تھا۔ {تھا: عبرانی۔ عروج پر پہنچا}\n25۔ اور بادشاہ کے خزانے کے اوپر عزماویث بیٹا عدئیل تھا: اور کھیتوں، شہروں، دیہاتوں اور قلعوں میں گوداموں کے اوپر، یہوناتھن عوزیاہ کا بیٹا تھا:\n26۔ اور ان کے اوپر جو زمین کی کاشت کا کام کر رہا تھا {تھا} عزری بیٹا چلوب کا:\n27۔ اور انگور کے باغات پر {تھا} شیمی رامتائی: شراب کے تہہ خانے کے لیے انگور کے باغات میں اضافہ {تھا} زبدی دی شیفمائٹ: {اضافے سے زیادہ...: عبرانی۔ انگور کے باغات کے اوپر}\n28۔ اور زیتون کے درختوں اور خوشامد کے درختوں کے اوپر جو {نشیبی میدانوں میں تھے} بعلحنان دی گدریتے: اور تیل کے تہہ خانوں کے اوپر {تھا} یوآش:\n29۔ اور ان ریوڑوں پر جو شارون میں کھاتے تھے {تھا} شیترائی شارونی تھا: اور ان ریوڑوں پر {جو وادیوں میں تھے} شفعت بیٹا ادلائی تھا:\n30۔ اونٹوں کے اوپر بھی اوبیل اسماعیلی تھا: اور گدھوں کے اوپر جہدیہ میرونوثی:\n31۔ اور جھنڈوں کے اوپر جازیز دی ہیگریٹ تھا۔ یہ سب {تھے} اس مادے کے حکمران تھے جو {تھا} بادشاہ داؤد کا۔\n32۔ اسی طرح یوناتھن داؤد کا چچا مشیر، دانا اور کاتب تھا: اور جہیئل، ہخمونی کا بیٹا، بادشاہ کے بیٹوں کے ساتھ تھا: {کاتب: یا، سیکرٹری} {بیٹا...: یا، ہخمونائی}\n33۔ اور اہیتوفیل بادشاہ کا مشیر تھا: اور ہوشائی آرکائٹ بادشاہ کا ساتھی تھا:\n34۔ اور اہیتوفیل کے بعد یہوعیدا بنایاہ اور ابیاتار کا بیٹا تھا: اور بادشاہ کی فوج کا سردار یوسف تھا۔","1۔ اور داؤد نے اسرائیل کے تمام شہزادوں، قبائل کے شہزادے، اور ان کمپنیوں کے کپتانوں کو جو بادشاہ کی خدمت کرتے تھے، ہزاروں کے کپتان، سینکڑوں کے کپتان، اور بادشاہ اور اس کے بیٹوں کی تمام ملکیت کے محافظوں کو جمع کیا،  اور طاقتور مردوں کے ساتھ، اور تمام بہادر مردوں کے ساتھ، یروشلم کی طرف۔ {قبضہ: یا، مویشی} {اور...: یا، اور اس کے بیٹے} {افسران: یا، خواجہ سرا}\n2۔ پھر داؤد بادشاہ اپنے قدموں پر کھڑا ہوا اور کہا، \"میری بات سنو، میرے بھائیو، اور میرے لوگو: {جہاں تک میرا تعلق ہے}، میں نے اپنے دل میں خدا کے عہد کے صندوق اور ہمارے خدا کے قدموں کے لیے آرام کا گھر بنانے کا ارادہ کیا تھا، اور تعمیر کے لیے تیار کیا تھا:\n3۔ لیکن خدا نے مجھ سے کہا، تم میرے نام کے لیے گھر نہیں بناؤ گے، کیونکہ تم جنگ کے آدمی رہے ہو اور خون بہایا ہے۔ {خون: عبرانی۔ bloods}\n4۔ اگرچہ اسرائیل کے خداوند خدا نے مجھے میرے والد کے تمام گھرانے سے پہلے ہمیشہ کے لیے اسرائیل کا بادشاہ چنا: کیونکہ اس نے یہوداہ کو حکمران کے طور پر چنا ہے؛ اور یہوداہ کے گھرانے سے، جو میرے والد کا گھر تھا؛ اور میرے والد کے بیٹوں میں سے وہ چاہتا تھا کہ میں {می} پورے اسرائیل کا بادشاہ بناؤں:\n5۔ اور میرے تمام بیٹوں میں سے، (کیونکہ خداوند نے مجھے بہت سے بیٹے دیے ہیں)، اس نے میرے بیٹے سلیمان کو خداوند کی بادشاہی کے تخت پر بیٹھنے کے لیے منتخب کیا ہے۔\n6۔ اور اس نے مجھ سے کہا، سلیمان تیرے بیٹے، وہ میرا گھر اور میرے دربار تعمیر کرے گا، کیونکہ میں نے اسے اپنا بیٹا چنا ہے، اور میں اس کا باپ بنوں گا۔\n7۔ مزید برآں، میں اس کی بادشاہی کو ہمیشہ کے لیے قائم کروں گا، اگر وہ میرے احکامات اور فیصلوں پر ثابت قدم رہے، جیسا کہ آج کے دن ہے۔ {مستقل: عبرانی۔ مضبوط}\n8۔ اب تمام اسرائیل، خداوند کی جماعت کے سامنے، اور ہمارے خدا کے سامنے، خداوند اپنے خدا کے تمام احکامات کو قائم رکھو اور ان کی تلاش کرو، تاکہ تم اس اچھی زمین پر قبضہ کر سکو، اور اسے ہمیشہ کے لیے اپنے بچوں کے لیے وراثت کے طور پر چھوڑ دو۔\n9۔ اور تو، سلیمان میرے بیٹے، اپنے باپ کے خدا کو جانتا ہے، اور اسے کامل دل اور رضامندی سے عبادت کرتا ہے: کیونکہ خداوند تمام دلوں کو تلاش کرتا ہے، اور خیالات کے تمام خیالات کو سمجھتا ہے: اگر تم اسے تلاش کرو گے تو وہ تم میں سے ملے گا؛ لیکن اگر تم اسے چھوڑ دو، تو وہ تمہیں ہمیشہ کے لیے نکال دے گا۔\n10۔ اب دھیان رکھو؛ کیونکہ خداوند نے تمہیں عبادت گاہ کے لیے گھر بنانے کے لیے منتخب کیا ہے: مضبوط رہو، اور یہ کام کرو۔\n11۔ پھر داؤد نے اپنے بیٹے سلیمان کو برآمدے، اس کے گھروں، خزانوں، اوپری کمروں، اندرونی کمروں اور رحم کی نشست کی جگہ کا نقشہ دیا،\n12۔ اور روح کے ذریعے اس کے پاس جو کچھ تھا، خداوند کے گھر کے عدالتوں اور آس پاس کے تمام کمروں کا، خدا کے گھر کے خزانے اور وقف شدہ چیزوں کے خزانے کا نمونہ: {ان سب کا...: عبرانی۔ جو کچھ بھی اس کے ساتھ تھا}\n13۔ کاہنوں اور لاویوں کے کورسز کے لیے، خداوند کے گھر کی خدمت کے تمام کاموں کے لیے، اور خداوند کے گھر میں خدمت کے تمام برتنوں کے لیے۔\n14۔ {اس نے سونے کی اشیاء کے لیے وزن کے حساب سے سونا دیا، ہر قسم کے خدمت کے آلات کے لیے؛ {چاندی بھی} تمام چاندی کے آلات کے لیے وزن کے لحاظ سے، ہر قسم کی خدمت کے تمام آلات کے لیے:\n15۔ حتیٰ کہ سونے کی موم بتی کے لیے، اور ان کے سونے کے چراغ کے لیے، ہر موم بتی کے لیے وزن کے حساب سے، اور چاندی کے شمعدانوں کے وزن کے حساب سے، {دونوں} موم بتی کے لیے، اور {بھی} اس کے چراغ کے لیے، ہر شمع دان کے استعمال کے مطابق۔\n16۔ اور وزن کے حساب سے {اس نے ہر میز کے لیے سونا دیا} کی میز کے لیے؛ اور {اسی طرح} چاندی کی میزوں کے لیے:\n17۔ گوشت کے کانٹوں، پیالوں اور پیالوں کے لیے خالص سونا؛ اور سونے کے حوضوں کے لیے {اس نے ہر حوض کے لیے وزن کے حساب سے سونا دیا}؛ اور {اسی طرح} ہر چاندی کے بیسن کے وزن کے حساب سے:\n18۔ اور خوشبو کے محراب کے لیے وزن کے حساب سے صاف شدہ سونا؛ اور سونا کروبیوں کے رتھ کے نقش کے لیے، جو اپنے پروں کو پھیلا کر خداوند کے عہد کے صندوق کو ڈھانپتا تھا۔\n19۔ یہ سب {یہ، داؤد نے فرمایا}، خداوند نے مجھے {اپنے} ہاتھ سے {حتیٰ کہ} اس نمونے کے تمام کاموں کو بھی تحریری طور پر سمجھایا۔\n20۔ اور داؤد نے اپنے بیٹے سلیمان سے کہا، مضبوط اور بہادر رہو اور یہ عمل کرو: نہ ڈرو نہ ڈرو، کیونکہ خداوند خدا، {حتی} میرا خدا، {حتی} تیرے ساتھ ہوگا؛ وہ تمہیں مایوس نہیں کرے گا، نہ ہی تمہیں چھوڑے گا، جب تک تم خداوند کے گھر کی خدمت کے لیے تمام کام مکمل نہ کر لو۔\n21۔ اور دیکھو، کاہنوں اور لاویوں کے طریقے ہیں، {یہاں تک کہ وہ بھی خدا کے گھرانے کی تمام خدمت کے لیے تمہارے ساتھ ہوں گے}؛ اور ہر قسم کی کاریگری کے لیے ہر رضاکار ماہر آدمی، کسی بھی قسم کی خدمت کے لیے تمہارے ساتھ ہوں گے: اور شہزادے اور تمام لوگ {مکمل طور پر} تیرے حکم کے تابع ہوں گے۔","1۔ مزید برآں، داؤد بادشاہ نے تمام جماعت سے کہا، سلیمان میرے بیٹے، جسے صرف خدا نے چنا ہے، ابھی جوان اور نرم ہے، اور کام عظیم ہے: محل انسان کے لیے نہیں، بلکہ خداوند خدا کے لیے ہے۔\n2۔ اب میں نے اپنی پوری طاقت سے اپنے خدا کے گھر کے لیے سونا تیار کیا ہے {سونے کی چیزوں کے لیے} اور چاندی کی {چیز} کے لیے، اور پیتل پیتل کے لیے {چیز} کے لیے، لوہا لوہے کی چیزوں کے لیے، اور لکڑی کی {چیز} کے لیے؛ اونکس پتھر، اور {پتھر} جو لگائے جائیں گے، چمکدار پتھر، اور مختلف رنگوں کے، اور ہر قسم کے قیمتی پتھر، اور سنگ مرمر کے پتھر وافر مقدار میں۔\n3۔ مزید برآں، چونکہ میں نے اپنی محبت اپنے خدا کے گھر کے لیے رکھی ہے، میرے پاس اپنی مناسب بھلائی ہے، سونا اور چاندی کی، {جو} میں نے اپنے خدا کے گھر کو دی ہے، اس سے بڑھ کر جو میں نے مقدس گھر کے لیے تیار کیا ہے،\n4. {حتیٰ کہ} تین ہزار ٹیلنٹ سونے کی، اوفیر کے سونے سے، اور سات ہزار تلنٹ صاف شدہ چاندی کی، تاکہ گھروں کی دیواروں پر سجایا جا سکے:\n5۔ سونے کی {چیز} کے لیے، اور چاندی کی {چیز} کے لیے، اور کاریگروں کے ہاتھوں بنائے گئے ہر قسم کے کام کے لیے۔ اور پھر، آج اپنی خدمت خداوند کے لیے کون وقف کرنے کو تیار ہے؟ {ان کی خدمت کو مقدس کریں: عبرانی۔ اس کا ہاتھ بھر دو}\n6۔ پھر اسرائیل کے قبائل کے باپوں اور شہزادوں میں سے سردار، اور ہزاروں اور سینکڑوں کے کپتانوں نے، بادشاہ کے کام کے حکمرانوں کے ساتھ، خوش دلی سے پیشکش کی،\n7۔ اور خدا کے گھر کی خدمت کے لیے سونے کے پانچ ہزار ٹیلنٹ اور دس ہزار ڈرم، اور چاندی سے دس ہزار ٹیلنٹ، اور پیتل کے اٹھارہ ہزار ٹیلنٹ اور ایک لاکھ لوہے کے ٹیلنٹ دیے۔\n8۔ اور جن کے پاس {قیمتی} پتھر ملے تھے، انہوں نے {ان} خداوند کے گھرانے کے خزانے کو یہییل گرشونی کے ہاتھ سے دے دیے۔\n9۔ پھر لوگوں نے خوشی منائی، کیونکہ انہوں نے خوش دلی سے پیش کیا، کیونکہ انہوں نے پورے دل سے خداوند کو خوشی سے پیش کیا: اور داؤد بادشاہ نے بھی بڑی خوشی سے خوشی منائی۔\n10۔ اسی لیے داؤد نے تمام جماعت کے سامنے خداوند کو برکت دی: اور داؤد نے کہا، مبارک ہو، اے رب اسرائیل کے خدا، ہمارے باپ، ہمیشہ ہمیشہ کے لیے۔\n11. اے خداوند، عظمت، طاقت، جلال، فتح، اور عظمت تیرا ہے: کیونکہ جو کچھ آسمان اور زمین میں ہے وہ سب تیرا ہے؛ بادشاہی تیرا ہے، اے خداوند، اور تو سب سے بلند سر کے طور پر بلند ہے۔\n12۔ دولت اور عزت دونوں تمہاری طرف سے آئے، اور تم سب پر حکمرانی کرتے ہو؛ اور تمہارے ہاتھ میں طاقت اور طاقت ہے؛ اور تمہارے ہاتھ میں عظیم بنانے اور سب کو طاقت دینے کے لیے ہے۔\n13۔ اب، ہمارے خدا، ہم تیرا شکر ادا کرتے ہیں اور تیرے جلال والے نام کی تعریف کرتے ہیں۔\n14. لیکن میں کون ہوں، اور میرے لوگ کیا ہیں، جو ہم اس قسم کے بعد اتنی خوشی سے پیش کر سکیں؟ کیونکہ سب کچھ تیری طرف سے ہے، اور ہم نے تمہیں دیا ہے۔ {ہو سکتا ہے: عبوری۔ برقرار رکھو، یا، طاقت حاصل کرو} {تمہاری...: عبرانی۔ تمہارے ہاتھ کا}\n15۔ کیونکہ ہم آپ کے سامنے اجنبی ہیں، اور سفر کرنے والے ہیں، جیسے ہمارے تمام باپ و اجداد تھے: ہمارے زمین پر دن ایک سایہ کی طرح ہیں، اور کوئی دائمی نہیں۔ {مستقل: عبرانی۔ توقع}\n16. اے خداوند ہمارے خدا، یہ سب ذخیرہ جو ہم نے تمہارے مقدس نام کے لیے گھر بنانے کے لیے تیار کیا ہے، وہ سب تیرے ہاتھ سے آتا ہے، اور یہ سب تمہارا ہے۔\n17. میں یہ بھی جانتا ہوں، میرے خدا، کہ تو دل کو آزماتا ہے، اور راستبازی میں خوشی محسوس کرتا ہے۔ جہاں تک میرا تعلق ہے، اپنے دل کی صاف گوئی میں میں نے یہ سب کچھ خوش دلی سے پیش کیا ہے: اور اب میں نے خوشی سے دیکھا ہے کہ تمہارے لوگ جو یہاں موجود ہیں، خوش دلی سے تمہیں پیش کر رہے ہیں۔ {موجود: عبرانی مل گیا}\n18. اے ابراہیم، اسحاق اور اسرائیل کے خداوند، ہمارے آباؤ اجداد، اسے ہمیشہ اپنے قوم کے دل کے خیالات میں رکھ کر رکھ، اور ان کے دل کو اپنے لیے تیار کرو: {تیار کرو: یا، قائم کرو}\n19۔ اور میرے بیٹے سلیمان کو ایک کامل دل دے، تاکہ وہ تمہارے احکامات، تمہاری گواہیاں اور تمہارے قوانین کی پاسداری کرے، اور یہ سب کچھ کرے، اور محل تعمیر کرے، {اس کے لیے جو میں نے انتظام کیا ہے۔'\n20۔ اور داؤد نے سب جماعت سے کہا، اب اپنے خداوند کو برکت دو۔ اور تمام جماعت نے اپنے باپوں کے خداوند خدا کو برکت دی، سر جھکایا، اور خداوند اور بادشاہ کی عبادت کی۔\n21۔ اور انہوں نے خداوند کے لیے قربانیاں قربان کیں، اور اس دن کے اگلے دن خداوند کے لیے ایک ہزار بیل، ہزار مینڈے، اور ہزار بھیڑ، ان کے مشروبات اور تمام اسرائیل کے لیے قربانیاں فراوان مقدار میں قربانیاں پیش کیں:\n22۔ اور اس دن خداوند کے سامنے بڑی خوشی سے کھایا اور پیا۔ اور انہوں نے سلیمان کو داؤد کے بیٹے کو دوسری بار بادشاہ بنایا، اور اسے خداوند کے سامنے {تاکہ وہ چیف گورنر} بنے، اور زادوک {کاہن} مقرر کیا۔\n23۔ پھر سلیمان اپنے والد داؤد کی جگہ خداوند کے تخت پر بادشاہ بن کر بیٹھا اور خوشحال ہوا؛ اور تمام اسرائیل نے اس کی اطاعت کی۔\n24۔ اور تمام شہزادے، طاقتور لوگ، اور بادشاہ داؤد کے تمام بیٹے بھی، سلیمان بادشاہ کے سامنے سر تسلیم خم کر گئے۔ {جمع کرایا گیا...: عبرانی۔ سلیمان کے نیچے ہاتھ دیا}\n25۔ اور خداوند نے سلیمان کو تمام اسرائیل کی نظر میں بہت بڑھا چڑھا کر پیش کیا، اور اسے ایسی شاہی عظمت عطا کی جو اس سے پہلے اسرائیل میں کسی بادشاہ پر نہیں تھی۔\n26۔ یوں یسوع کے بیٹے داؤد نے پورے اسرائیل پر حکومت کی۔\n27۔ اور وہ وقت جب اس نے اسرائیل پر حکومت کی، وہ چالیس سال تھا؛ انہوں نے ہبرون میں سات سال حکومت کی، اور یروشلم میں تیس تین سال حکومت کی۔\n28۔ اور وہ ایک اچھے بوڑھے عمر میں مر گیا، جو دنوں اور دولت اور عزت سے بھرپور تھا: اور اس کا بیٹا سلیمان نے اس کی جگہ حکومت کی۔\n29۔ اب داؤد بادشاہ کے اعمال، سب سے پہلے اور آخری، دیکھیں، یہ {سموئیل دی سیئر' کی کتاب میں، اور ناتھن نبی کی کتاب میں، اور گاد دی سیئر کی کتاب {کتاب: یا، تاریخ: عبرانی۔ الفاظ}\n30۔ اپنی پوری حکومت اور طاقت کے ساتھ، اور ان وقتوں کے ساتھ جو اس پر گزرے، اسرائیل پر، اور تمام ملکوں کی سلطنتوں پر۔"];
